CARDIO.register({"item":"224","meta":{"num":224,"short":"HTA","title":"Hypertension artérielle de l'adulte et de l'enfant","section":"I","chapter":4,"pages":"81-111","sdd":[{"num":42,"label":"Hypertension artérielle"},{"num":53,"label":"Hypertension durant la grossesse"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":201,"label":"Dyskaliémie"},{"num":253,"label":"Prescrire des diurétiques"},{"num":282,"label":"Prescription médicamenteuse, consultation de suivi et éducation d'un patient hypertendu"},{"num":320,"label":"Prévention des maladies cardiovasculaires"},{"num":328,"label":"Annonce d'une maladie chronique"},{"num":354,"label":"Évaluation de l'observance thérapeutique"}]},"objectives":[{"id":"224-obj-01","rank":"A","rubric":"Définition","title":"Définition de l'HTA","desc":""},{"id":"224-obj-02","rank":"A","rubric":"Prévalence, épidémiologie","title":"Épidémiologie de l'HTA, HTA facteur de risque cardiovasculaire majeur","desc":"Prévalence, liens (âge, obésité, diabète, etc.), complications cardiovasculaires, répartition HTA essentielle et secondaire"},{"id":"224-obj-03","rank":"B","rubric":"Physiopathologie","title":"Physiopathologie de l'HTA","desc":"Principaux mécanismes (rénine ou volodépendants), facteurs environnementaux"},{"id":"224-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Mesure de la pression artérielle","desc":"Connaître les méthodes de mesure de la PA (consultation, automesure, MAPA) et interpréter"},{"id":"224-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Évaluation initiale d'un patient hypertendu","desc":"Circonstances de découverte, interrogatoire, risque cardiovasculaire, examen clinique"},{"id":"224-obj-06","rank":"A","rubric":"Examens complémentaires","title":"Examens complémentaires de 1re intention","desc":"Bilan biologique minimal, ECG"},{"id":"224-obj-07","rank":"A","rubric":"Suivi et/ou pronostic","title":"Complications de l'HTA, retentissement sur les organes cibles","desc":"Neurosensorielles, cardiovasculaires, rénales"},{"id":"224-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes d'orientation en faveur d'une HTA secondaire","desc":"Savoir mener l'examen clinique et prescrire les examens complémentaires permettant d'évoquer une HTA secondaire"},{"id":"224-obj-09","rank":"A","rubric":"Étiologies","title":"Connaître les principales causes d'HTA secondaire","desc":"Néphropathies parenchymateuses, HTA rénovasculaire, causes endocriniennes, coarctation de l'aorte, etc."},{"id":"224-obj-10","rank":"B","rubric":"Diagnostic positif","title":"Connaître la démarche diagnostique en cas de suspicion d'HTA secondaire","desc":"Clinique, biologie, imagerie"},{"id":"224-obj-11","rank":"A","rubric":"Identifier une urgence","title":"Reconnaître une urgence hypertensive et une HTA maligne","desc":"Définition d'une crise hypertensive et d'une urgence hypertensive"},{"id":"224-obj-12","rank":"B","rubric":"Définition","title":"Définition d'une HTA résistante","desc":"Connaître les facteurs de résistance (non-observance, sel, syndrome d'apnées du sommeil, médicaments ou substances hypertensives, etc.)"},{"id":"224-obj-13","rank":"A","rubric":"Prise en charge","title":"Connaître les objectifs de la consultation d'annonce","desc":"Intérêts et objectifs de la prise en charge, modification du style de vie, prise en charge des autres facteurs de risque"},{"id":"224-obj-14","rank":"A","rubric":"Prise en charge","title":"Connaître la stratégie du traitement médicamenteux de l'HTA","desc":"Traitement initial, classes thérapeutiques, adaptation, surveillance, chiffres cible de PA"},{"id":"224-obj-15","rank":"A","rubric":"Prise en charge","title":"Connaître les principaux effets indésirables et contre-indications des traitements antihypertenseurs","desc":""},{"id":"224-obj-16","rank":"B","rubric":"Prise en charge","title":"Connaître les situations cliniques particulières pouvant orienter le choix du traitement antihypertenseur","desc":""},{"id":"224-obj-17","rank":"A","rubric":"Prise en charge","title":"Connaître les particularités du traitement antihypertenseur du sujet âgé de plus de 80 ans","desc":""},{"id":"224-obj-18","rank":"A","rubric":"Prise en charge","title":"Prise en charge d'une urgence hypertensive","desc":""},{"id":"224-obj-19","rank":"A","rubric":"Suivi et/ou pronostic","title":"Plan de soins à long terme et modalités de suivi d'un patient hypertendu","desc":"Savoir évaluer l'efficacité du traitement, la tolérance au traitement et l'observance du patient"},{"id":"224-obj-20","rank":"A","rubric":"Prise en charge","title":"Principes de prise en charge d'une HTA secondaire","desc":"HTA rénovasculaire et endocrinienne"},{"id":"224-obj-21","rank":"A","rubric":"Définition","title":"Connaître la définition de l'HTA chez l'enfant et l'existence de normes pédiatriques","desc":""},{"id":"224-obj-22","rank":"A","rubric":"Diagnostic positif","title":"Mesure de la pression artérielle chez l'enfant","desc":"Indications de la mesure de la PA chez l'enfant (examen systématique annuel après 3 ans, présence de FDR) et modalités (brassard adapté, abaques selon l'âge et le sexe)"},{"id":"224-obj-23","rank":"B","rubric":"Étiologies","title":"Connaître les principales causes d'HTA chez l'enfant","desc":""}],"course":{"sections":[{"id":"224-sec-01","title":"Mesure de la pression artérielle : consultation, AMT, MAPA","rank":"A","objectives":["224-obj-04"],"content":"### Pression artérielle de consultation\n\nConditions **standardisées**. Appareil **électronique validé** (oscillométrique, au bras), recalibré régulièrement ; l'auscultation au stéthoscope n'est plus de 1re intention **sauf en fibrillation atriale**.\n\n- Sujet **assis**, au calme, repos physique et psychique **> 5 min**, **> 30 min** après effort, café ou cigarette ; **vessie vide** ; dos calé ; bras posé sur un support.\n- **Brassard adapté** à la taille du bras (3 tailles : obèse, standard, enfant), placé à hauteur du cœur.\n- **≥ 3 mesures** à 1–2 min d'intervalle, **moyenne des 2 dernières** ; si les 2 premières PAS diffèrent de **> 10 mmHg** → mesures supplémentaires.\n- **Deux bras** à la 1re consultation : une asymétrie fait suspecter une **sténose de l'artère subclavière** ; le bras aux valeurs les plus hautes devient le bras de référence.\n- **Hypotension orthostatique** à la 1re consultation (âgé, fragile, diabétique, dysautonomie) : PA + FC après 5 min allongé/assis puis debout à **1 et 3 min** ; positive si baisse **PAS ≥ 20** et/ou **PAD ≥ 10 mmHg** à 1 et/ou 3 min.\n- **FC de repos** au pouls pendant **≥ 30 s** à la recherche d'une arythmie.\n\n> [B] **Pièges** : artères calcifiées incompressibles (âgé, diabétique, hémodialysé) → PA **surestimée de 20 mmHg** (parfois 40–50) ; pouls radial encore perçu brassard gonflé au-dessus de la PAS = **manœuvre d'Osler** ; cordon induré huméral/radial. **Pression pulsée (PAS − PAD) > 65 mmHg** = rigidité artérielle.\n\n### Automesure tensionnelle (AMT)\n\nMesure à domicile par le patient : **examen recommandé en France pour confirmer** l'HTA ; meilleure prédiction du risque CV, meilleure corrélation aux organes cibles, meilleure adhésion. Appareil **validé, semi-automatique, brassard huméral** (poignet = plus d'erreurs) ; éducation du patient indispensable.\n\n**« Règle des 3 »** (SFHTA/HAS) : **3 jours consécutifs**, **3 mesures le matin** (20 min après le lever, avant petit-déjeuner et médicaments) et **3 le soir** (dans l'heure avant le coucher), après 5 min de repos, assis, avant-bras sur la table → **18 mesures**. Le patient note PAS, PAD, FC (fiche ou application), calcule la moyenne des 2 dernières de chaque série et apporte le relevé.\n\n### Mesure ambulatoire de la PA (MAPA)\n\nSi l'AMT est **impossible ou non fiable** (manipulation, report, anxiété). Bon prédicteur du risque CV (la **PA nocturne** est plus précise que la diurne), très corrélée aux organes cibles, évalue la baisse sous traitement. Sur **24 h** d'activité habituelle, appareil automatique, brassard adapté ; **journal** (coucher, lever, prises, symptômes) ; mesures toutes les **15–30 min le jour**, **30–60 min la nuit**.\n\nIndications spécifiques : confirmer une **HTA résistante** ; rechercher des **épisodes d'hypotension symptomatiques** (asthénie, lipothymies) ; **forte variabilité** des mesures ; explorer la **PA nocturne**.","keyPoints":["Mesure de consultation : appareil électronique validé, ≥ 3 mesures à 1–2 min d'intervalle, moyenne des 2 dernières, après > 5 min de repos assis.","PA aux deux bras à la première consultation ; asymétrie → sténose subclavière ; bras le plus élevé = référence.","Hypotension orthostatique = baisse PAS ≥ 20 et/ou PAD ≥ 10 mmHg à 1 et/ou 3 min debout.","L'AMT est l'examen recommandé en France pour confirmer l'HTA : règle des 3 (3 mesures matin + 3 soir, 3 jours) = 18 mesures.","MAPA sur 24 h si AMT impossible ou peu fiable, HTA résistante, hypotensions symptomatiques, variabilité, PA nocturne.","La PA nocturne en MAPA est le meilleur prédicteur du risque cardiovasculaire."],"pitfalls":["Le stéthoscope n'est plus la méthode de première intention, sauf en fibrillation atriale.","Le brassard de poignet expose à plus d'erreurs : préférer le brassard huméral.","Artères incompressibles (âgé, diabétique, dialysé) : la PA au brassard est surestimée de 20 mmHg ou plus (manœuvre d'Osler)."],"src":"p. 83-85"},{"id":"224-sec-02","title":"Définition, catégories de PA, grades et profils particuliers","rank":"A","objectives":["224-obj-01","224-obj-04"],"content":"La distribution des PA est **continue** et le passage à l'HTA est graduel. L'ESC 2024 distingue **3 catégories** : PA non élevée, PA élevée, HTA.\n\n### Les trois catégories selon la méthode de mesure (tableau 4.1)\n\n| Mesure | PA non élevée | PA élevée [B] | HTA |\n|---|---|---|---|\n| Consultation | < 120/70 | 120–139 et/ou 70–89 | **≥ 140 et/ou ≥ 90** |\n| AMT | < 120/70 | 120–134 et/ou 70–84 | **≥ 135 et/ou ≥ 85** |\n| MAPA 24 h | < 115/65 | 115–130 et/ou 65–79 | **≥ 130 et/ou ≥ 80** |\n| MAPA diurne | < 120/70 | 120–134 et/ou 70–84 | ≥ 135 et/ou ≥ 85 |\n| MAPA nocturne | < 110/60 | 110–119 et/ou 60–69 | ≥ 120 et/ou ≥ 70 |\n\n- **PA normale** (adulte) : PAS < 120 **et** PAD < 70 mmHg (consultation ou AMT).\n- [B] **PA élevée** : catégorie importante car elle impose une **évaluation du risque CV global** (SCORE2, SCORE2-OP, SCORE2-Diabetes, ou situations d'emblée à haut risque : maladie CV, insuffisance rénale, hypercholestérolémie familiale) et parfois un traitement antihypertenseur si le risque est suffisant.\n- **HTA** : moyenne des PAS **≥ 140** et/ou PAD **≥ 90 mmHg** en consultation. Le diagnostic posé au cabinet doit être **confirmé hors cabinet** (en l'absence d'urgence hypertensive), préférentiellement par **AMT**, à défaut par MAPA. En AMT : **≥ 135/85 mmHg**.\n\n### Grades de sévérité (PA de consultation, tableau 4.2)\n\n| Grade | PAS (mmHg) | | PAD (mmHg) |\n|---|---|---|---|\n| Grade 1 | 140–159 | et/ou | 90–99 |\n| Grade 2 | 160–179 | et/ou | 100–109 |\n| Grade 3 | ≥ 180 | et/ou | ≥ 110 |\n\n> Devant une **HTA de grade 3**, rechercher **systématiquement une urgence hypertensive**.\n\nDélai de la mesure hors cabinet de confirmation lors d'une première consultation : **dans le mois** pour un grade 2, **dans la semaine** pour un grade 3 sans urgence hypertensive.\n\n### Discordance consultation / ambulatoire\n\nSi les mesures concordent, l'HTA est confirmée. Deux profils fréquents :\n\n- **HTA « blouse blanche »** (**15–20 %** des adultes) : PA de consultation > 140/90 mais mesures ambulatoires normales. Pas de traitement médicamenteux, mais **mesures hygiénodiététiques** et **surveillance régulière hors cabinet** (risque d'HTA confirmée secondairement).\n- **HTA masquée** (**10–15 %** des adultes) : PA de consultation < 140/90 mais HTA en ambulatoire (ex. AMT > 135/85). Souvent PA de cabinet proche des seuils et **risque CV élevé**. Même risque d'événements que l'HTA habituelle → **même prise en charge** ; les mesures hors cabinet guident la surveillance et les décisions.","keyPoints":["HTA en consultation : PAS ≥ 140 et/ou PAD ≥ 90 mmHg ; en AMT : ≥ 135/85 ; en MAPA 24 h : ≥ 130/80.","PA normale : < 120/70 mmHg ; PA élevée : 120–139/70–89 en consultation (120–134/70–84 en AMT).","Grades : 1 = 140–159/90–99 ; 2 = 160–179/100–109 ; 3 = ≥ 180/≥ 110 mmHg.","Toute HTA de grade 3 impose de rechercher une urgence hypertensive.","Confirmation hors cabinet dans le mois (grade 2) ou dans la semaine (grade 3 sans urgence).","HTA blouse blanche (15–20 %) : pas de médicament, MHD et surveillance ; HTA masquée (10–15 %) : traiter comme une HTA classique."],"pitfalls":["Ne jamais débuter un antihypertenseur sur des seules mesures de cabinet (hors urgence hypertensive).","Les seuils diffèrent selon la méthode : 140/90 (cabinet) ≠ 135/85 (AMT) ≠ 130/80 (MAPA 24 h).","L'HTA masquée n'est pas bénigne : elle expose au même risque que l'HTA habituelle."],"src":"p. 85-87"},{"id":"224-sec-03","title":"Épidémiologie et poids de l'HTA","rank":"A","objectives":["224-obj-02"],"content":"### Chiffres clés\n\n- Maladie chronique **la plus fréquente** en France et dans le monde : plus de **1,5 milliard** de personnes atteintes ; **première cause de mortalité** mondiale (> **10 millions** de décès par an).\n- France, 2023 : **17 millions** d'adultes hypertendus et **1,6 million** de nouveaux patients traités chaque année.\n- Étude **ESTEBAN** (France, milieu des années 2010) : **30 %** des adultes de 18 à 74 ans hypertendus ; **50 %** des hypertendus non traités (voire non diagnostiqués) ; **50 %** des diagnostiqués-traités non contrôlés ; au final, seuls **25 %** des hypertendus sont diagnostiqués, traités **et** contrôlés.\n- La prévalence augmente avec l'âge : **> 60 % après 70 ans**, **70 % après 80 ans**.\n- Facteurs associés : autre FDR CV, **surpoids**, populations défavorisées, **alcool**, sédentarité, stress répétés.\n- Le niveau de PA est un trait **partiellement héritable** : enfants d'un ou deux parents hypertendus plus à risque, surtout si HTA parentale précoce.\n- En France, l'HTA est la **1re maladie chronique**, le **1er FDR CV de mortalité** et le **2e facteur d'années de vie perdues en bonne santé** : FDR CV majeur, notamment de la maladie athéromateuse.\n- Répartition : **90 % d'HTA essentielle**, **10 % d'HTA secondaire**.\n\n### Surrisque de l'hypertendu (versus normotendu)\n\nLa mortalité CV est **doublée**, par excès de complications :\n\n| Complication | Surrisque |\n|---|---|\n| AVC | **× 7** |\n| Insuffisance cardiaque | **× 4** |\n| Insuffisance coronarienne (dont SCA) | **× 3** |\n| Artériopathie des membres inférieurs | **× 2** |\n| Fibrillation atriale, IRC terminale, démence vasculaire | fréquence accrue |\n\n### Bénéfice du contrôle tensionnel\n\n- Atteindre les objectifs tensionnels réduit les complications CV et rénales et la mortalité CV. Cette **réversibilité** du risque est **meilleure pour les AVC** que pour les accidents coronariens.\n- Méta-analyse de **2015** : une baisse de **5–6 mmHg de PAD** et de **10 mmHg de PAS** pendant 5 ans diminue le risque d'**AVC d'un tiers**, d'**insuffisance coronarienne d'1/6** et d'**insuffisance cardiaque de 46 %**.\n\n### Dépistage (ESC 2024)\n\nDépistage d'une PA élevée ou d'une HTA **au moins tous les 3 ans avant 40 ans** et **au moins une fois par an à partir de 40 ans**. Tous les professionnels (généraliste, spécialiste, médecin du travail, infirmier, IPA, pharmacien) sont encouragés à y participer.","keyPoints":["HTA = maladie chronique la plus fréquente et première cause de mortalité dans le monde (> 1,5 milliard de personnes, > 10 millions de décès/an).","France : 17 millions d'hypertendus, 30 % des 18–74 ans (ESTEBAN), seuls 25 % diagnostiqués, traités et contrôlés.","Prévalence > 60 % après 70 ans et 70 % après 80 ans.","Surrisque : AVC × 7, insuffisance cardiaque × 4, coronaropathie × 3, AOMI × 2 ; mortalité CV × 2.","La baisse de la PA est plus efficace sur les AVC que sur les événements coronariens.","Dépistage au moins tous les 3 ans avant 40 ans, annuel à partir de 40 ans."],"pitfalls":["Ne pas confondre les chiffres : 30 % de prévalence chez les adultes, mais 70 % après 80 ans.","L'HTA secondaire ne représente que 10 % des cas : l'HTA essentielle reste le diagnostic dans 90 % des cas."],"src":"p. 87-88"},{"id":"224-sec-04","title":"Physiopathologie de l'HTA","rank":"B","objectives":["224-obj-03"],"content":"### Systèmes régulateurs de la PA\n\n| Horizon | Mécanisme |\n|---|---|\n| **Court terme** | Système **sympathique** : baroréflexe carotidien et aortique, centre vasopresseur du tronc cérébral, chaînes sympathiques latérovertébrales, médullosurrénales. Médiateurs α1-adrénergiques **vasoconstricteurs** et β2-adrénergiques **vasodilatateurs**. |\n| **Moyen terme** (volémie, vasomotricité) | Système **rénine-angiotensine-aldostérone** et **peptides natriurétiques** (ANP, BNP). |\n| **Long terme** | **Natriurèse de pression** (l'élévation de PA augmente l'excrétion urinaire de sodium) et système **arginine-vasopressine**. |\n\n### HTA secondaire versus essentielle\n\n- **10 %** : HTA **secondaire**, due à une cause spécifique (toxique, iatrogène, rénale, rénovasculaire, endocrinienne) dont le traitement ciblé peut fortement améliorer le contrôle, voire guérir l'HTA.\n- **90 %** : HTA **essentielle**, résultat combiné de facteurs **génétiques** (héritabilité du niveau de PA) et **environnementaux** : autres FDR CV (tabac, diabète), alimentation **riche en sodium et pauvre en potassium** (fruits, légumes), surpoids, alcool, sédentarité, absence d'activité physique, vieillissement.\n\n### Mécanismes de l'HTA essentielle\n\nDysfonction de plusieurs systèmes régulateurs :\n\n- tonus des **petites artères de résistance** ;\n- **balance hydrosodée** ;\n- système **arginine-vasopressine** ;\n- système **rénine-angiotensine-aldostérone** ;\n- système **sympathique** (baroréflexe) ;\n- **insulinorésistance** (sujets en surpoids).\n\nConséquences, qui s'associent pour déclencher puis amplifier la maladie :\n\n1. **hyperréactivité** des vaisseaux de résistance (vasoconstriction) ;\n2. **remodelage structurel** des artérioles (fibrose de la média, hyperplasie des cellules musculaires lisses) ;\n3. **rigidité** accrue de l'aorte et de ses branches ;\n4. **rétention hydrosodée** (inadéquation PA / excrétion sodée).\n\n### Formes familiales\n\n- **15 %** des HTA essentielles sont **familiales** : début souvent **précoce avant 30 ans**, même profil chez un ou les deux parents ; composante génétique forte mais **polygénique** → **pas d'indication à un test génétique**.\n- De très rares formes **monogéniques**, liées le plus souvent à des anomalies de l'homéostasie rénale.","keyPoints":["Régulation à court terme : système sympathique et baroréflexe ; à moyen terme : SRAA et peptides natriurétiques ; à long terme : natriurèse de pression et vasopressine.","90 % d'HTA essentielle (gènes + environnement), 10 % d'HTA secondaire potentiellement curable.","L'HTA essentielle associe hyperréactivité des artères de résistance, remodelage artériolaire, rigidité aortique et rétention hydrosodée.","L'insulinorésistance participe à l'HTA du sujet en surpoids.","15 % des HTA essentielles sont familiales (début avant 30 ans), polygéniques, sans indication de test génétique."],"pitfalls":["Une HTA familiale précoce n'est pas une indication de test génétique : les formes monogéniques sont très rares."],"src":"p. 88-89"},{"id":"224-sec-05","title":"Complications et retentissement sur les organes cibles","rank":"A","objectives":["224-obj-07"],"content":"Relation **continue et positive** entre le niveau de PA et l'incidence des complications **cardiaques** (insuffisance cardiaque, cardiopathie ischémique, FA), **neurovasculaires** (AVC, démence) et **rénales** (néphropathie).\n\n### Complications cardiovasculaires\n\n- **Insuffisance cardiaque à FEVG altérée** : soit d'origine **ischémique** (coronaropathie ± infarctus), soit liée à l'HTA elle-même par élévation permanente de la **postcharge** (HTA sévère, plus souvent chez les sujets noirs) → VG **dilaté et hypertrophié** = **HVG excentrique**.\n- **Insuffisance cardiaque à FEVG préservée** : anomalies du remplissage (compliance, relaxation) liées à l'**HVG** et à la fibrose, cœur **hypertrophié non dilaté**.\n- **Cardiopathie ischémique** : angor, SCA avec ou sans sus-ST. L'angor peut relever de l'athérome coronaire, de l'HTA seule (baisse de la **réserve coronarienne** par HVG) ou des deux.\n- **Fibrillation atriale** : l'HTA en est la **1re cause** (**70 %** des patients en FA sont hypertendus). Mécanisme : troubles du remplissage → hausse de la pression diastolique VG → **dilatation de l'oreillette gauche**. L'HTA compte **1 point** dans le score **CHA2DS2-VASc**.\n- **Mort subite** : risque **× 3**.\n- **Maladie athéromateuse** : AOMI, sténose carotidienne, anévrisme de l'aorte abdominale.\n\nMortalité CV multipliée par **5 chez l'homme** et **3 chez la femme**.\n\n### Complications neurovasculaires\n\n- **AIT et AVC ischémique** : **80 %** des AVC de l'hypertendu.\n- **Hémorragie cérébrale** : **20 %** (intraparenchymateuse par rupture de microanévrisme ou nécrose fibrinoïde) ; hémorragie méningée (souvent associée à une malformation vasculaire) ; formes mixtes.\n- **Encéphalopathie hypertensive** : surtout dans les HTA d'aggravation rapide (HTA maligne, toxémie gravidique, glomérulonéphrite aiguë).\n- **Lacunes cérébrales**, **démence vasculaire**.\n- **Rétinopathie hypertensive** : au stade le plus grave (**stade 4**) œdème papillaire et hémorragies rétiniennes.\n\n### Complications rénales\n\n- **Néphroangiosclérose** : l'HTA chronique non contrôlée altère successivement artérioles, glomérules, tubules et interstitium → insuffisance rénale par **réduction néphronique**, qui aggrave à son tour l'HTA (cercle vicieux). Signe précoce : **microalbuminurie** (glomérulopathie).\n- Insuffisance rénale sur **athérome des artères rénales** (sténose) et/ou **emboles de cholestérol**.\n- **Insuffisance rénale aiguë iatrogène** : diurétiques (déshydratation extracellulaire) ou bloqueur du SRA en cas de **sténose bilatérale** des artères rénales ou de sténose sur **rein unique**.","keyPoints":["Relation continue et positive entre le niveau de PA et les complications cardiaques, neurovasculaires et rénales.","Deux formes d'insuffisance cardiaque : FEVG altérée (ischémie ou postcharge, HVG excentrique) et FEVG préservée (HVG concentrique, fibrose).","L'HTA est la première cause de FA (70 % des patients en FA) et vaut 1 point au CHA2DS2-VASc.","AVC de l'hypertendu : 80 % ischémiques, 20 % hémorragiques.","Mort subite × 3 ; mortalité CV × 5 chez l'homme, × 3 chez la femme.","Néphroangiosclérose : microalbuminurie précoce, puis insuffisance rénale qui aggrave l'HTA.","IRA iatrogène : diurétiques (déshydratation) ou IEC/ARA2 sur sténose bilatérale ou rein unique."],"pitfalls":["L'angor de l'hypertendu peut survenir sans athérome coronaire, par baisse de la réserve coronarienne liée à l'HVG.","Rétinopathie stade 4 (œdème papillaire) = HTA maligne, pas une simple complication chronique."],"src":"p. 89-90"},{"id":"224-sec-06","title":"Circonstances de découverte, interrogatoire et examen clinique","rank":"A","objectives":["224-obj-05","224-obj-08"],"content":"### Découverte\n\nHTA le plus souvent **latente** (examen systématique). Symptômes non spécifiques : **céphalées occipitales** matinales, battantes, résistant aux antalgiques, cédant au lever ; fatigabilité, nervosité, insomnie ; **phosphènes** ; **épistaxis** — ils n'**affirment pas** l'HTA ni ne **justifient** un traitement immédiat. D'où le **dépistage systématique**. PA ≥ 140/90 au cabinet = **suspicion**, à **confirmer hors cabinet** (AMT/MAPA) avant traitement, sauf urgence.\n\n### Évaluation initiale : 5 objectifs\n\n**Niveau de PA** ; **risque CV global** ; **organes cibles** (vasculaire, cardiaque, cérébral, rénal), clinique ou infraclinique ; **facteurs aggravants** ; **HTA secondaire** → puis **consultation d'annonce**.\n\n### Interrogatoire\n\n- Ancienneté, valeurs antérieures ; **FDR CV** : dyslipidémie, diabète, tabac, ATCD familiaux CV précoces.\n- **Facteurs aggravants** : graisses animales, sel, peu de fruits/légumes ; alcool ; sédentarité, faible activité ; surpoids (prise de poids récente) ; **ronflements, pauses nocturnes** (conjoint) → SAOS.\n- **Grossesses compliquées** : HTA/diabète gravidique, prééclampsie, prématurité, fausses couches répétées, mort fœtale in utero.\n- **Organes cibles** : ATCD coronariens, IC, AVC/AIT, artériopathie, néphropathie ; neuro (céphalées, vertiges, troubles visuels, déficit, cognition → **MMSE**) ; cœur (palpitations, douleur thoracique, dyspnée, OMI) ; rein (soif, polyurie, nycturie, hématurie) ; artères (extrémités froides, claudication).\n- **HTA secondaire** :\n  - histoire familiale de **néphropathie** (polykystose) ou de **polyendocrinopathies** ; infections urinaires répétées, hématurie, néphropathie connue ;\n  - **médicaments** : contraceptifs oraux, vasoconstricteurs nasaux, corticoïdes, AINS, érythropoïétine, ciclosporine, tacrolimus, dérivés de l'ergot de seigle, inhibiteurs de tyrosine-kinase, anti-VEGF ;\n  - **toxiques** : réglisse (boissons anisées, bonbons, tisanes), cannabis, cocaïne, amphétamines, alcool ;\n  - **triade de Ménard** (céphalées, sueurs, palpitations) par crises → phéochromocytome ;\n  - asthénie, crampes, tétanie, paresthésies, constipation → **hypokaliémie** / hyperaldostéronisme ;\n  - ecchymoses faciles, hyperandrogénie (oligospanioménorrhée, aménorrhée) → **hypercortisolisme** (Cushing).\n\n### Examen clinique\n\n- **Hypotension orthostatique**.\n- **Organes cibles** : souffles carotidiens, déficit neurologique ; tachycardie, arythmie, galop, OMI, signes d'IC ; pouls abolis ou asymétriques, souffle abdominal, masse battante, extrémités froides, lésions cutanées ischémiques.\n- **HTA secondaire** : souffle précordial + **pouls fémoraux faibles/abolis** (coarctation) ; **souffle aortique abdominal** (rénovasculaire) ; **gros reins** (polykystose) ; **neurofibromatose** cutanée (phéochromocytome) ; **Cushing** (peau fine, vergetures pourpres, érythrose, amyotrophie proximale, signe du tabouret, bosse de bison, hirsutisme).\n- **Obésité viscérale** : poids, IMC, tour de taille debout.","keyPoints":["L'HTA est le plus souvent asymptomatique, découverte lors d'un examen systématique.","Céphalées occipitales matinales, phosphènes, épistaxis, fatigabilité : symptômes non spécifiques qui n'affirment pas l'HTA et ne justifient pas un traitement immédiat.","Évaluation initiale : niveau de PA, risque CV global, organes cibles, facteurs aggravants, HTA secondaire, puis consultation d'annonce.","Interroger sur les médicaments et toxiques hypertensiogènes : contraceptifs, AINS, corticoïdes, vasoconstricteurs nasaux, EPO, anticalcineurines, réglisse, cocaïne, amphétamines, cannabis, alcool.","Triade de Ménard (céphalées, sueurs, palpitations) par crises = phéochromocytome.","Examen : pouls fémoraux (coarctation), souffle abdominal (rénovasculaire), gros reins (polykystose), taches de neurofibromatose (phéo), signes de Cushing."],"pitfalls":["Crampes, asthénie, tétanie ou constipation chez un hypertendu doivent faire penser à une hypokaliémie et à un hyperaldostéronisme.","Oublier de rechercher une cause secondaire ou un facteur aggravant lors du bilan initial est une notion inacceptable.","Le SAOS se dépiste dès l'interrogatoire (ronflements, pauses nocturnes rapportés par le conjoint)."],"src":"p. 90-92"},{"id":"224-sec-07","title":"Examens complémentaires, atteinte infraclinique, risque global et consultation d'annonce","rank":"A","objectives":["224-obj-06","224-obj-08","224-obj-13"],"content":"### Bilan systématique (« bilan minimal »)\n\nBut : autres FDR CV, atteinte **infraclinique**, arguments pour une HTA secondaire.\n\n- **Glycémie à jeun**, **HbA1c** ;\n- **cholestérol total, HDL-C, triglycérides**, LDL-C calculé ;\n- **natrémie, kaliémie** (si possible sans garrot) ;\n- **hémoglobine, hématocrite** ;\n- **créatininémie** + DFG estimé (**CKD-EPI**) ;\n- rapport **protéinurie/créatininurie** sur échantillon (matinal) ;\n- **ECG de repos**.\n\n### Examens selon le contexte (s'ils modifient la prise en charge)\n\n- **Échocardiographie** si ECG anormal ou symptômes cardiaques (dyspnée) ; **pas chez l'asymptomatique à ECG normal**.\n- **IPS**, **échodoppler** des TSA ou des membres inférieurs si souffle ou symptômes d'AOMI (pas chez l'asymptomatique).\n- **Fond d'œil** : grade 2–3 avec suspicion d'HTA maligne ; recommandé dans le **grade 3**.\n- **β-hCG** si grossesse possible (antihypertenseurs contre-indiqués).\n\n### Atteinte infraclinique\n\n**ECG** (peu sensible : des signes électriques = HVG marquée) : HVG (**Sokolow, Cornell, Lewis**), séquelle d'infarctus méconnu, repolarisation (ischémie vs surcharge VG), troubles du rythme (FA). Un ECG initial normal sert de référence.\n\n**Échocardiographie** : HVG = masse VG **> 115 g/m² (homme)**, **> 95 g/m² (femme)** ou remodelage concentrique (pronostic altéré) ; fonction systolique (cinétique segmentaire → coronaropathie) et diastolique (remplissage, OG dilatée) ; anévrisme de l'aorte ascendante ou abdominale, coarctation.\n\n**Reins** : créatinine ↑ / clairance ↓ = DFG ↓ ; insuffisance rénale si DFG **< 60 ml/min/1,73 m²**. Protéinurie glomérulaire (albuminurie) ou tubulaire : **RAC > 300 mg/g**, pathologique dès **> 30 mg/g**. **Microalbuminurie systématique seulement chez le diabétique**.\n\n**Fond d'œil** : **stade 3** (hémorragies, exsudats) et **stade 4** (œdème papillaire) = risque CV accru ; PA non contrôlée + stade 4 = **HTA maligne**.\n\n### Avis spécialisé d'emblée\n\nHTA **sévère d'emblée (grade 3)** ; HTA **avant 40 ans** (sauf obésité : dépister d'abord un SAOS) ; HTA **résistante** ; contexte d'HTA secondaire (ex. **HTA + hypokaliémie**).\n\n### Risque CV global\n\nDéfini au terme du bilan (ATCD CV, organes cibles, FDR) ; guide surveillance et traitement.\n\n- **Élevé d'emblée** : ATCD coronarien, AVC/AIT, AOMI, IC, insuffisance rénale modérée/sévère, atteinte d'organe cible cardiaque ou vasculaire, hypercholestérolémie familiale.\n- **Diabétiques** : le plus souvent élevé ; **SCORE2-Diabetes** chez les 40–69 ans.\n- **Autres** : **SCORE2** / **SCORE2-OP** (risque à 10 ans).\n\n### Consultation d'annonce\n\nAprès confirmation (AMT/MAPA) et bilan : informer sur la maladie et ses complications ; expliquer les **bénéfices démontrés** du traitement ; détailler mesures médicamenteuses et non médicamenteuses (sel, alcool, poids, activité, alimentation) ; fixer les **objectifs** dont la **cible de PA** ; **plan de soins** à court et long terme ; avis du patient → **décision médicale partagée**.","keyPoints":["Bilan minimal : glycémie à jeun + HbA1c, bilan lipidique, Na/K, Hb/Ht, créatininémie avec DFG (CKD-EPI), rapport protéinurie/créatininurie, ECG de repos.","Échocardiographie seulement si ECG anormal ou symptômes ; jamais systématique chez l'asymptomatique à ECG normal.","HVG échographique : masse VG > 115 g/m² (homme), > 95 g/m² (femme).","Protéinurie : RAC > 300 mg/g ; pathologique dès > 30 mg/g ; microalbuminurie systématique seulement chez le diabétique.","Fond d'œil recommandé dans l'HTA de grade 3 ; stade 4 (œdème papillaire) = HTA maligne.","Avis spécialisé d'emblée : grade 3, âge < 40 ans (hors obésité), HTA résistante, signes d'HTA secondaire (hypokaliémie).","Risque élevé d'emblée si maladie CV, insuffisance rénale, atteinte d'organe cible ou hypercholestérolémie familiale ; sinon SCORE2/SCORE2-OP, SCORE2-Diabetes chez le diabétique de 40–69 ans."],"pitfalls":["L'ECG est peu sensible pour l'HVG : un ECG normal n'exclut pas une HVG.","Chez l'obèse hypertendu de moins de 40 ans, dépister un SAOS avant l'avis spécialisé.","Penser au dosage de β-hCG : plusieurs antihypertenseurs sont contre-indiqués pendant la grossesse."],"src":"p. 92-94"},{"id":"224-sec-08","title":"Objectifs, stratégie thérapeutique, cibles et mesures hygiénodiététiques","rank":"A","objectives":["224-obj-13","224-obj-14"],"content":"### Objectif et bénéfices\n\nRéduire la **mortalité CV et rénale** à long terme. Un traitement adapté diminue le risque d'**AVC de 20–30 %** et celui de **SCA et d'insuffisance cardiaque de 10–20 %**. **Aucune limite d'âge** pour envisager un traitement.\n\n### Quatre piliers\n\n1. mesures hygiénodiététiques ;\n2. traitement des FDR associés (cf. item 222) ;\n3. traitement médicamenteux ;\n4. éducation thérapeutique.\n\n### Stratégie selon la PA de consultation et le risque (tableau 4.3, ESC 2024)\n\n| Situation | MHD | Traitement pharmacologique |\n|---|---|---|\n| PAS 120–129 | oui | non |\n| PAS 130–139 **sans** risque CV élevé | oui | non ; surveillance régulière, réévaluation annuelle du risque |\n| PAS 130–139 **avec** risque CV élevé | oui | après **3 mois** de MHD si la cible n'est pas atteinte (monothérapie si PA ≥ 130/80) |\n| **HTA confirmée** | oui | **oui, d'emblée** chez tous |\n\n### Cibles tensionnelles\n\n- Suivi **fréquent** (tous les mois si besoin) jusqu'à la cible, idéalement atteinte **à 3 mois**.\n- Cible générale (ESC 2024) : **PAS 120–129 mmHg** et **PAD 70–79 mmHg**, en visant si possible **120/70**.\n- Cible **adaptée d'emblée** en cas d'hypotension orthostatique, de fragilité, d'âge > 85 ans ou d'espérance de vie limitée, et **au cours du suivi** selon la tolérance.\n- Si la cible est inatteignable ou mal tolérée : viser la PA **la plus basse possible et < 140/90 mmHg**.\n\n### Mesures hygiénodiététiques (chez tous, PA élevée ou HTA)\n\nBaisse attendue de la **PAS de 5 à 10 mmHg** ; permettent de réduire nombre et doses de médicaments.\n\n- **Activité physique** régulière : aérobie (endurance) + résistance dynamique (squats, pompes) et/ou isométrique (planche, chaise) ; lutte contre la **sédentarité**.\n- **Poids** : cible **IMC 20–25 kg/m²**, périmètre abdominal **< 94 cm (homme)** et **< 80 cm (femme)**.\n- **Alcool** : supprimer ou réduire, cible **< 10 unités/semaine**.\n- **Sel** : **5–6 g/j**, soit natriurèse des 24 h ≈ **100 mmol/j** (1 g de NaCl = 17 mmol de sodium).\n- **Potassium** : augmenter l'apport (substituts de sel, fruits et légumes) sauf maladie rénale chronique avancée.\n- **Arrêt du tabac**.\n- Alimentation de **type méditerranéen** : fruits, légumes, peu de graisses saturées, limitation maximale du sucre et des boissons sucrées (sodas, jus).\n- **Café non limité** ; boissons à la taurine et caféine déconseillées.","keyPoints":["Objectif : réduire la mortalité CV et rénale ; le traitement diminue les AVC de 20–30 % et les SCA/IC de 10–20 %.","Quatre piliers : MHD, traitement des FDR, médicaments, éducation thérapeutique ; aucune limite d'âge.","HTA confirmée = traitement médicamenteux immédiat ; PA élevée à risque élevé = MHD 3 mois puis monothérapie si ≥ 130/80.","Cible : PAS 120–129 et PAD 70–79 mmHg (idéalement 120/70), à atteindre en 3 mois ; sinon la plus basse tolérée et < 140/90.","MHD : sel 5–6 g/j, alcool < 10 unités/semaine, IMC 20–25, tour de taille < 94 cm (H) / < 80 cm (F), activité physique, potassium, régime méditerranéen, arrêt du tabac.","Les MHD font baisser la PAS de 5 à 10 mmHg en moyenne."],"pitfalls":["Pas de régime sans sel strict : la cible est 5–6 g de sel par jour.","Le café n'est pas à restreindre ; ce sont les boissons à la taurine/caféine qui sont déconseillées.","L'augmentation du potassium est contre-indiquée en cas de maladie rénale chronique avancée."],"src":"p. 95-96"},{"id":"224-sec-09","title":"Traitement médicamenteux : classes, initiation, contre-indications, effets indésirables, éducation","rank":"A","objectives":["224-obj-14","224-obj-15","224-obj-16"],"content":"### Cinq classes de 1re intention\n\nEfficaces sur la morbi-mortalité CV (AVC, SCA, IC) : **inhibiteurs calciques** (DHP ou non), **IEC**, **ARA2**, **bêtabloquants**, **thiazidiques ou apparentés** (indapamide). **Bêtabloquants** : **moins efficaces sur les AVC**, à l'initiation seulement sur **autre indication**, **jamais en monothérapie**. **Persistance** : ARA2 et IEC > IC > thiazidiques et bêtabloquants.\n\n### Initiation : bithérapie d'emblée\n\n**Faible dose**, **association fixe** (1 comprimé), **monoprise** (demi-vie longue), avec deux des classes IEC, ARA2, thiazidique, IC :\n\n- **IEC ou ARA2 + IC dihydropyridine** ;\n- **IEC ou ARA2 + thiazidique** (ou apparenté).\n\n> **Jamais IEC + ARA2** ; un bloqueur du SRA est souvent utilisé dès le début.\n\n### Monothérapie initiale (≥ 1 critère)\n\nPA élevée (120–139/70–89) à traiter ; fragilité modérée ou sévère ; hypotension orthostatique préexistante ; âge **> 85 ans**. Molécule parmi IEC, ARA2, thiazidique, IC (DHP habituellement).\n\n### Comorbidités orientant le choix [B]\n\n| Comorbidité | Classes à préférer |\n|---|---|\n| Diabète + microalbuminurie ou IR | IEC, ARA2 (+ iSGLT2 probable) |\n| Insuffisance rénale et/ou protéinurie | IEC, ARA2 |\n| ATCD d'AVC | IEC, ARA2, IC, diurétique |\n| ATCD d'infarctus | IEC, ARA2, BB |\n| Angor | IC, BB |\n| IC à FEVG altérée | IEC (ARA2 si intolérance), BB, diurétique (+ ARM) |\n\nTenir compte aussi des **contre-indications** et des **interactions**.\n\n### Contre-indications\n\n| Classe | Absolues | Relatives |\n|---|---|---|\n| IEC | grossesse ; angio-œdème sous IEC | hyperkaliémie ; femme en âge de procréer sans contraception ; sténose bilatérale des artères rénales ; IR sévère |\n| ARA2 | grossesse | idem IEC |\n| Thiazidiques | goutte ; hypokaliémie ; hypercalcémie ; grossesse | — |\n| Bêtabloquants | asthme ; BAV 2 et 3 | bradycardie ; syndrome de Raynaud |\n| IC dihydropyridines | IC non contrôlée | — |\n| IC non dihydropyridines (bradycardisants) | BAV 2 et 3 ; IC à FEVG altérée | bradycardie ; autres troubles de conduction |\n\n### Effets indésirables (réversibles à l'arrêt)\n\n| Classe | Effets indésirables |\n|---|---|\n| Thiazidiques | hypokaliémie, hyponatrémie, hyperglycémie, hyperuricémie, IR fonctionnelle |\n| Bêtabloquants | asthénie (début), bradycardie sinusale, acrosyndrome, hypoglycémie, baisse de libido, dysfonction érectile, prise de poids |\n| IC dihydropyridines | OMI, céphalées, vertiges, flushs |\n| IC non dihydropyridines | idem + bradycardie, troubles de conduction, constipation |\n| IEC | **toux**, hyperkaliémie, IR fonctionnelle |\n| ARA2 | hyperkaliémie, IR fonctionnelle |\n\n### Éducation thérapeutique\n\nRenforce l'adhésion : **AMT** (règle des 3) ; observance (horaires adaptés, pilulier) ; **suspension transitoire** de diurétiques/IEC/ARA2 si **risque d'hypovolémie** (diarrhée, vomissements, fièvre, canicule), surtout chez l'âgé, avec ionogramme et créatininémie ; rappel des messages de l'annonce ; éducation ciblée sur les FDR ; approche **centrée sur le patient**.","keyPoints":["Cinq classes de 1re intention : IC, IEC, ARA2, bêtabloquants, thiazidiques (indapamide) ; les bêtabloquants préviennent moins bien les AVC.","Débuter par une bithérapie fixe à faible dose en monoprise : IEC/ARA2 + IC dihydropyridine ou IEC/ARA2 + thiazidique.","Ne jamais associer IEC et ARA2 ; pas de bêtabloquant sans autre indication.","Monothérapie initiale : PA élevée traitée, fragilité, hypotension orthostatique, âge > 85 ans.","IEC et ARA2 : contre-indiqués pendant la grossesse ; angio-œdème sous IEC = CI absolue ; prudence si hyperkaliémie, sténose bilatérale, IR sévère.","Bêtabloquants : CI absolues asthme et BAV 2-3 ; thiazidiques : goutte, hypokaliémie, hypercalcémie, grossesse.","Effets indésirables typiques : toux (IEC), OMI et flushs (IC DHP), hypokaliémie/hyperuricémie (thiazidiques), bradycardie et dysfonction érectile (BB).","Éduquer à suspendre transitoirement diurétiques/IEC/ARA2 en cas de déshydratation (diarrhée, fièvre, canicule)."],"pitfalls":["L'association IEC + ARA2 est proscrite.","Les IC non dihydropyridines (bradycardisants) sont contre-indiqués en BAV 2-3 et en IC à FEVG altérée, pas les dihydropyridines.","La persistance est la plus faible avec les diurétiques et les bêtabloquants : y penser devant un échec."],"src":"p. 96-100"},{"id":"224-sec-10","title":"Situations particulières : sujet âgé et HTA de l'enfant","rank":"A","objectives":["224-obj-17","224-obj-21","224-obj-22","224-obj-23"],"content":"### Sujet âgé\n\nL'âge seul ne suffit pas à guider le traitement : rechercher une **fragilité gériatrique** modérée ou sévère et des arguments pour une **espérance de vie limitée** à moyen terme. Dépister **systématiquement l'hypotension orthostatique** (risque élevé) et se souvenir du risque accru de **iatrogénie**.\n\nEn pratique (ESC 2024) :\n\n- **< 85 ans**, sans fragilité ni facteur limitant l'espérance de vie → **pas d'adaptation** de la prise en charge ;\n- un hypertendu traité qui atteint **85 ans** ne doit **pas voir son traitement arrêté ou réduit** systématiquement s'il est bien toléré (clinique et paraclinique) ;\n- **adapter** la prise en charge si au moins un critère : **fragilité modérée/sévère**, **âge > 85 ans**, **espérance de vie < 3 ans**.\n\nAdaptations :\n\n1. débuter en **monothérapie** ;\n2. privilégier **IC dihydropyridines** et/ou **IEC/ARA2** en 1re intention, **thiazidiques à faible dose** en 2e intention ;\n3. **éviter bêtabloquants** (sauf indication formelle) et **alphabloquants** ;\n4. **ne pas dépasser une trithérapie** ;\n5. **individualiser la cible** selon la tolérance clinique et paraclinique ; le patient doit être **exempt d'hypotension orthostatique** à cette cible.\n\nEn cas d'hypovolémie (diarrhée, vomissements, fièvre, canicule), le sujet âgé doit savoir réduire ou suspendre transitoirement diurétiques, IEC et ARA2, avec contrôle du ionogramme et de la fonction rénale.\n\n### HTA de l'enfant\n\nLe chapitre fixe les objectifs suivants (contenu détaillé hors chapitre) :\n\n- il existe une **définition spécifique** de l'HTA chez l'enfant, fondée sur des **normes pédiatriques** ;\n- la PA doit être mesurée chez l'enfant lors de l'**examen systématique annuel après 3 ans** et en présence de **facteurs de risque** ;\n- modalités : **brassards adaptés** à la taille de l'enfant et **abaques selon l'âge et le sexe** ; la taille « enfant » fait partie des 3 tailles de brassard ;\n- [B] les principales **causes d'HTA de l'enfant** sont à connaître ; le chapitre cite la **coarctation aortique** (enfant et adulte jeune) et les **néphropathies parenchymateuses** (HTA de l'adolescent ou de l'adulte jeune, polykystose) parmi les causes secondaires à début précoce.","keyPoints":["Chez le sujet âgé, c'est la fragilité et l'espérance de vie, pas l'âge seul, qui guident l'adaptation du traitement.","Adapter si fragilité modérée/sévère, âge > 85 ans ou espérance de vie < 3 ans : monothérapie initiale, IC DHP et/ou IEC/ARA2, thiazidique faible dose en 2e ligne.","Chez l'âgé fragile : pas de bêtabloquant ni d'alphabloquant, pas plus d'une trithérapie, cible individualisée sans hypotension orthostatique.","Ne pas alléger systématiquement un traitement bien toléré au passage des 85 ans.","Enfant : mesure de la PA à l'examen systématique annuel après 3 ans et en cas de FDR, avec brassard adapté et abaques âge/sexe."],"pitfalls":["Un patient de moins de 85 ans non fragile se traite comme un adulte plus jeune : pas d'adaptation par l'âge seul.","Chez l'enfant, il n'existe pas de seuil unique : l'HTA se définit sur des normes pédiatriques."],"src":"p. 82, 99-100"},{"id":"224-sec-11","title":"Surveillance des premiers mois, suivi au long cours et HTA résistante","rank":"A","objectives":["224-obj-14","224-obj-19","224-obj-12"],"content":"### Premiers mois : surveillance et adaptation\n\n- PA surveillée de préférence par **AMT** : **1 mois après chaque adaptation** et **avant chaque consultation**.\n- Après introduction ou changement de dose d'**IEC/ARA2** ou de **diurétique** : **ionogramme** + **créatininémie/DFGe**.\n- À chaque consultation : **hypotension orthostatique** (âgé, insuffisant rénal, diabétique) ; **effets indésirables** (changer de molécule ou de classe ; réversibles à l'arrêt) ; si mauvaise tolérance, **réadapter la cible** (tolérée, la plus proche possible de la théorique).\n\n**Objectif non atteint à 1 mois** (ESC 2024) :\n\n1. renforcer l'adhésion aux **MHD** ;\n2. renforcer l'**observance** médicamenteuse ;\n3. **majorer** en privilégiant le **passage en trithérapie** (idéalement **IEC/ARA2 + IC + thiazidique** ou apparenté) avant d'augmenter les doses ;\n4. revoir à **1 mois avec AMT**.\n\n### Patient à la cible\n\n- [B] Faible risque ou HTA de grade 1 : consultation **tous les 6 mois** ; risque CV élevé ou traitement par MHD seules : **tous les 3 mois**.\n- Consultation : symptômes ; **équilibre tensionnel** (cabinet + AMT/MAPA) ; **observance, tolérance** ; FDR et MHD ; **hypotension orthostatique** (diabète, Parkinson, âgé).\n- Paraclinique : **chaque année** Na, K, créatininémie, protéinurie (plus souvent chez l'âgé) ; **tous les 3 ans** glycémie à jeun et bilan lipidique (si ni diabète ni dyslipidémie) ; **ECG tous les 3 à 5 ans** sauf cardiopathie ou symptômes.\n- Adapter le traitement si **hypotension orthostatique**, fragilité gériatrique ou **interactions** (bradycardisants + bêtabloquants, **AINS + IEC/ARA2**).\n\n### Cible non atteinte sous trithérapie\n\n1. confirmer par **AMT ou MAPA** ;\n2. réévaluer **observance** et tolérance ;\n3. **facteurs de résistance** : **sel**, prise de **poids**, **alcool**, **dépression**, médicaments hypertensiogènes (AINS, corticoïdes, vasoconstricteurs, œstrogènes), substances psychoactives/illicites (cannabis, cocaïne, amphétamines), **apnées du sommeil** ;\n4. trithérapie **optimale** : IEC/ARA2 + IC + thiazidique, **tous à dose optimale**.\n\n> On ne parle d'HTA résistante que chez un patient recevant un **diurétique thiazidique** (ou apparenté).\n\n### HTA résistante [B]\n\n**Définition** : PA > cible malgré MHD et **≥ 3 classes** à dose optimale **dont un thiazidique**, confirmée par **AMT** (souvent MAPA). Éliminer une **fausse résistance** (blouse blanche, brassard inadapté, doses insuffisantes ou pas de diurétique, inobservance, MHD non suivies : sel, poids, alcool) puis **avis spécialisé**. Causes : substances hypertensiogènes ; **SAOS** ; **HTA secondaire méconnue** ; **surcharge volémique** (diurétique insuffisant, insuffisance rénale).\n\nSans cause curable, ajouter à la trithérapie : **ARM** (**spironolactone** en 1re intention, **éplérénone** si intolérance) → **bêtabloquant** (si non déjà indiqué) → **alphabloquant** ou **antihypertenseur central** → **dénervation rénale** au cas par cas.","keyPoints":["AMT 1 mois après chaque adaptation et avant chaque consultation ; ionogramme + créatininémie après tout changement d'IEC/ARA2 ou de diurétique.","Cible non atteinte à 1 mois : renforcer MHD et observance, passer en trithérapie IEC/ARA2 + IC + thiazidique avant de majorer les doses, revoir à 1 mois avec AMT.","À la cible : consultation tous les 6 mois (faible risque, grade 1) ou 3 mois (risque élevé, MHD seules) ; bilan biologique annuel ; glycémie et lipides tous les 3 ans ; ECG tous les 3 à 5 ans.","HTA résistante : PA > cible sous ≥ 3 classes à dose optimale dont un thiazidique, malgré les MHD, confirmée par AMT/MAPA.","Éliminer une fausse résistance (blouse blanche, brassard, doses, observance, sel/poids/alcool) avant l'avis spécialisé.","4e ligne : spironolactone (éplérénone si intolérance), puis bêtabloquant, puis alphabloquant/central, dénervation rénale au cas par cas."],"pitfalls":["Sans diurétique thiazidique dans la trithérapie, on ne peut pas parler d'HTA résistante.","Les AINS interagissent avec IEC/ARA2 et sont une cause classique de déséquilibre tensionnel.","Ne pas augmenter les doses de la bithérapie avant d'être passé en trithérapie."],"src":"p. 100-102"},{"id":"224-sec-12","title":"HTA secondaire : dépistage, bilan et causes rénales","rank":"A","objectives":["224-obj-08","224-obj-09","224-obj-10","224-obj-20"],"content":"### Quand dépister une HTA secondaire\n\n- HTA **sévère** : PA **> 180/110 mmHg**, surtout d'apparition **brutale** ou d'**aggravation rapide** ;\n- HTA **résistante** ;\n- âge **< 40 ans** ;\n- HTA avec **hypokaliémie** ;\n- tout point d'appel de l'interrogatoire, de l'examen ou de la biologie initiale.\n\n**Avis spécialisé** recommandé pour les explorations.\n\n### Bilan paraclinique [B] (adapté aux points d'appel)\n\n- **polygraphie ventilatoire nocturne** (SAOS) ;\n- **échographie rénale + échodoppler des artères rénales** (néphropathie, sténose) ;\n- **angioscanner abdominal** (néphropathie, lésion surrénalienne, sténose des artères rénales) ;\n- **urines des 24 h** : natriurèse, kaliurèse, créatininurie, protéinurie, **dérivés méthoxylés des catécholamines**, **cortisol libre urinaire**, **aldostéronurie** ;\n- **dosages sanguins** : **rénine et aldostérone** (conditions de prélèvement strictes), dérivés méthoxylés plasmatiques, **test de freinage minute** si suspicion d'hypercorticisme.\n\n### Néphropathies parenchymateuses\n\n- Causes rénales les plus fréquentes : **glomérulopathies chroniques** et **polykystose rénale**.\n- Évoquées devant une HTA de l'**adolescent ou de l'adulte jeune** ; **masses abdominales bilatérales** → polykystose.\n- Orientation : **protéinurie**, **hématurie**, **insuffisance rénale**.\n- **Échographie** : taille des reins, contours, épaisseur corticale, obstacle des voies excrétrices, tumeurs.\n- Prise en charge : celle de la néphropathie causale.\n\n### HTA rénovasculaire\n\nSténose des artères rénales, deux causes :\n\n| Cause | Terrain | Siège |\n|---|---|---|\n| **Athérome** (la plus fréquente) | autres localisations athéromateuses, FDR | **ostium et tiers proximal** |\n| **Dysplasie fibromusculaire** (plus rare) | **femme jeune** | **deux tiers distaux** |\n\n[B] Signes évocateurs : **souffle abdominal latéralisé** ; **OAP récidivant** sans cause cardiaque ; **hypokaliémie avec hyperaldostéronisme secondaire** (rénine **et** aldostérone augmentées) ; **insuffisance rénale**, parfois révélée par l'introduction d'un IEC/ARA2 ; **petit rein** du côté sténosé. Confirmation et quantification : **échodoppler des artères rénales** et **angioscanner abdominal**.\n\nTraitement : MHD, **aspirine**, **statine** (si athérome), antihypertenseurs.\n\n- **Sténose athéromateuse** : revascularisation (angioplastie **avec endoprothèse**) discutée **uniquement** en cas de souffrance du rein homolatéral (HTA résistante, dégradation de la fonction rénale, protéinurie importante) et si le rein reste fonctionnel.\n- **Fibrodysplasie** : angioplastie **sans endoprothèse**, plus largement utilisée.","keyPoints":["Dépister une HTA secondaire si : PA > 180/110 (brutale ou s'aggravant), HTA résistante, âge < 40 ans, hypokaliémie, ou point d'appel.","Bilan spécialisé : polygraphie nocturne, écho-doppler rénal, angioscanner abdominal, urines des 24 h (métanéphrines, cortisol libre, aldostérone), rénine/aldostérone plasmatiques, freinage minute.","Causes rénales parenchymateuses les plus fréquentes : glomérulopathies chroniques et polykystose (gros reins bilatéraux, sujet jeune).","Sténose athéromateuse : ostium et tiers proximal ; dysplasie fibromusculaire : femme jeune, deux tiers distaux.","Rénovasculaire : souffle abdominal latéralisé, OAP flash, hypokaliémie avec rénine et aldostérone élevées, IRA sous IEC/ARA2, petit rein.","Revascularisation de la sténose athéromateuse seulement si souffrance rénale (HTA résistante, IR progressive, protéinurie) ; angioplastie sans stent pour la fibrodysplasie."],"pitfalls":["Dans l'HTA rénovasculaire, l'hyperaldostéronisme est secondaire : la rénine est élevée (contrairement au Conn où elle est basse).","Une insuffisance rénale apparaissant sous IEC/ARA2 doit faire évoquer une sténose des artères rénales."],"src":"p. 102-103"},{"id":"224-sec-13","title":"HTA secondaire : causes endocriniennes, coarctation, SAOS, médicaments","rank":"A","objectives":["224-obj-09","224-obj-10","224-obj-20"],"content":"### Phéochromocytome\n\nTumeur **rare**, souvent **bénigne**, de la **médullosurrénale**, sécrétant des catécholamines **par pics** ; HTA dans **70 %** des cas. Formes familiales : **NEM2**, **von Hippel-Lindau**, **neurofibromatose 1**, paragangliomes familiaux.\n\n- HTA **permanente ou paroxystique** + **triade de Ménard** (céphalées, sueurs, palpitations) ; troubles du rythme ; parfois **cardiomyopathie de stress** révélatrice.\n- Diagnostic : **dérivés méthoxylés des catécholamines** (métanéphrines, normétanéphrines) **urinaires et/ou plasmatiques**.\n- Localisation : **scanner + scintigraphie à la MIBG** (tumeur parfois extrasurrénalienne ; confirmation fonctionnelle).\n- Traitement : **exérèse chirurgicale** après **alphabloquants** à doses progressives **associés aux bêtabloquants** (limite poussée hypertensive et hypotension par déplétion volémique peropératoires).\n\n### Hyperaldostéronisme primaire (syndrome de Conn)\n\n- **Adénome surrénalien (30 %)** ou **hyperplasie bilatérale (70 %)**, rarement corticosurrénalome malin.\n- [B] Évocateur : **hypokaliémie < 3,7 mmol/L** (inconstante), HTA sévère, résistante, du sujet jeune, atteinte d'organes cibles disproportionnée, **nodule surrénalien** fortuit.\n- Biologie : **aldostérone ↑**, **rénine ↓**, **rapport aldostérone/rénine très élevé** ; dosage le matin **2 h après le lever**, en **normokaliémie**, apports sodés larges, arrêt des **ARM depuis 6 semaines**, des **IEC, ARA2, diurétiques, bêtabloquants depuis 2 semaines**.\n- **Scanner** : lésion unilatérale ou hyperplasie bilatérale. Lésion unilatérale + patient demandeur : **cathétérisme des veines surrénaliennes** (latéralisation) → **surrénalectomie** ; sinon **spironolactone** (ARM) en 1re intention.\n\n### Autres causes endocriniennes\n\n**Syndrome de Cushing** (hypercortisolisme), **acromégalie**, **hyperthyroïdie**.\n\n### Coarctation aortique\n\nEnfant et adulte jeune ; fermeture anormale du **canal artériel** → sténose de l'**isthme aortique**. **Souffle mésosystolique parasternal gauche et dorsal**, **pouls fémoraux absents**, **HTA aux bras** et PA basse aux jambes. Confirmation : **échocardiographie, IRM**. Traitement **chirurgical** ou **endoluminal** (dilatation + endoprothèse).\n\n### Syndrome d'apnées du sommeil\n\nÉvoqué chez l'**obèse**, surtout si HTA **résistante**, et chez les **« non dippers »** (pas de baisse nocturne en MAPA). [B] **Polygraphie ou polysomnographie** nocturne ; traitement par **masque de pression positive** nocturne.\n\n### Médicaments et substances\n\n**Action vasopressive** (les plus fréquents) : **corticoïdes**, **contraceptifs oraux**, **érythropoïétine**, **ciclosporine/tacrolimus**, **antiangiogéniques**, **sympathomimétiques**, **IRSNa** (recapture sérotonine-noradrénaline), **réglisse**, herbes (**ephedra, ma huang**), **alcool**, **cocaïne, amphétamines**.\n\n**Interférence avec les antihypertenseurs** : **AINS**, **antirétroviraux**, inhibiteurs du **CYP17A1** (jus de pamplemousse, macrolides, antifongiques azolés).","keyPoints":["Phéochromocytome : HTA paroxystique + triade de Ménard ; diagnostic sur métanéphrines urinaires/plasmatiques ; scanner + MIBG ; chirurgie après alphabloquant puis bêtabloquant.","Conn : hyperplasie bilatérale 70 %, adénome 30 % ; aldostérone haute, rénine basse, rapport très élevé ; hypokaliémie < 3,7 mmol/L inconstante.","Dosages rénine/aldostérone : matin 2 h après le lever, normokaliémie, sel libre, arrêt ARM 6 semaines et IEC/ARA2/diurétiques/BB 2 semaines.","Adénome unilatéral confirmé par cathétérisme des veines surrénaliennes = surrénalectomie ; sinon spironolactone.","Coarctation : souffle parasternal gauche et dorsal, pouls fémoraux absents, HTA aux bras et PA basse aux jambes ; écho + IRM ; chirurgie ou endoprothèse.","SAOS : obèse, HTA résistante, non dipper ; polygraphie ; masque de pression positive nocturne.","Autres endocrinopathies : Cushing, acromégalie, hyperthyroïdie."],"pitfalls":["La normokaliémie n'exclut pas un hyperaldostéronisme primaire : l'hypokaliémie est inconstante.","Ne pas doser rénine et aldostérone sous ARM, IEC, ARA2, diurétiques ou bêtabloquants : résultats ininterprétables.","Jus de pamplemousse, macrolides et azolés modifient l'action des antihypertenseurs (inhibition du CYP17A1)."],"src":"p. 103-105"},{"id":"224-sec-14","title":"Urgences hypertensives et HTA maligne","rank":"A","objectives":["224-obj-11","224-obj-18"],"content":"### Définitions\n\n- **Crise hypertensive** : HTA de **grade 3 sans souffrance viscérale** → **pas une urgence**.\n- **Urgence hypertensive** : HTA (souvent **> 180/110 mmHg**) **+ atteinte aiguë d'un organe cible** ; **pronostic vital** engagé ; inclut l'HTA maligne.\n- **HTA maligne** : PA élevée (pas de seuil, souvent grade 3) + **œdème papillaire** au fond d'œil (**stade 4**), ± atteintes aiguës : cardiaques (IVG, ischémie), rénales (**IRA**, protéinurie abondante, hématurie), neurologiques (**PRES**, encéphalopathie, coma), **microangiopathie thrombotique** (anémie hémolytique mécanique, thrombopénie). Souvent AEG en quelques semaines, troubles digestifs, soif, déshydratation. Sans traitement : **insuffisance rénale sévère irréversible et mortelle en quelques mois**.\n\n### Principales urgences hypertensives\n\nHTA + **SCA** (± sus-ST) ; **IVG / OAP** ; **dissection aortique** ; **encéphalopathie hypertensive** (HTIC) ; **PRES** (cécité centrale, lésions occipitales) ; HTA + **hémorragie méningée ou AVC** ; **phéochromocytome** ; **toxiques** (amphétamines, LSD, cocaïne, ecstasy) ; **prééclampsie sévère / éclampsie** (extraction fœtale urgente).\n\n### Bilan\n\nBiologie : créatinine, protéinurie, **plaquettes, coagulation** (CIVD), **troponine**, toxiques (cocaïne), NFS, **schizocytes**, bilirubine libre, haptoglobine, LDH. **ECG** (SCA) ; **radio thoracique** (OAP) ; **échocardiographie** (fonction VG, cinétique, remplissage) ; **fond d'œil** (OVCR, stade 4) ; **scanner cérébral** si AVC/hémorragie suspectés ; **imagerie aortique** (ETT, scanner, ETO) si dissection.\n\n### Prise en charge\n\n- **Soins intensifs** adaptés à l'organe atteint ou **réanimation** ; PA **toutes les 15 min**.\n- Signe neurologique → **scanner avant tout antihypertenseur** (hémorragie vs ischémie).\n- Cas général : **− 20 à 25 % en 2 h**, **160/110 mmHg en 2 à 6 h** ; **pas de chute brutale** (autorégulation altérée → hypoperfusion cérébrale, ischémie myocardique ou rénale).\n- **Dissection aortique** : au contraire, **PAS < 120 mmHg le plus vite possible**.\n- 1re intention : **urapidil IV** (alphabloquant) et/ou **nicardipine IV** (IC ; **contre-indiquée en insuffisance cardiaque**).\n- **Phéochromocytome** : **labétalol IV** (alpha + bêtabloquant).\n- **SCA ou OAP** : **dérivés nitrés IV** en 1re intention.\n\n### AVC (ESC 2024)\n\n| Situation | Objectif |\n|---|---|\n| **Hémorragie intracérébrale** | baisse immédiate (**< 6 h**) vers **PAS 140–160 mmHg** (limite l'expansion de l'hématome) ; pas de chute de PAS **> 70 mmHg** (IRA, aggravation neurologique) |\n| **AVC ischémique sans reperfusion** | pas de baisse active sauf PA **> 220/120** → **− 10–15 % sur quelques heures** |\n| **Thrombolyse IV** | **< 185/110** avant, puis **< 180/105 pendant 24 h** |\n| **Thrombectomie** (± thrombolyse) | **< 180/105** avant l'intervention et pendant les 24 h suivantes |\n| Stable, encore > 140/90 **≥ 3 jours** après un AVC ischémique | débuter ou reprendre un antihypertenseur |","keyPoints":["Crise hypertensive = grade 3 sans souffrance viscérale (pas une urgence) ; urgence hypertensive = HTA + atteinte aiguë d'un organe cible.","HTA maligne = PA élevée + œdème papillaire (stade 4) ± IRA, IVG, PRES, microangiopathie thrombotique ; évolue vers l'IR terminale en quelques mois sans traitement.","Urgences : SCA, OAP, dissection, encéphalopathie, PRES, AVC/hémorragie méningée, phéo, toxiques, prééclampsie sévère/éclampsie.","Soins intensifs, PA toutes les 15 min, scanner cérébral avant traitement si signe neurologique.","Cible générale : − 20 à 25 % en 2 h, 160/110 mmHg en 2–6 h ; dissection : PAS < 120 le plus vite possible.","Urapidil IV et/ou nicardipine IV en 1re intention ; labétalol IV pour le phéochromocytome ; nitrés IV pour SCA/OAP.","Hémorragie cérébrale : PAS 140–160 dans les 6 h (pas de chute > 70 mmHg) ; AVC ischémique : ne traiter que si > 220/120 (− 10–15 %) ; thrombolyse : < 185/110 puis < 180/105 sur 24 h."],"pitfalls":["Ne pas confondre crise hypertensive (pas d'atteinte viscérale, pas d'urgence) et urgence hypertensive.","Une baisse trop brutale de la PA aggrave le cerveau, le cœur et le rein : viser 160/110 en 2 à 6 h, pas une normalisation.","La nicardipine est contre-indiquée en insuffisance cardiaque : préférer les nitrés IV dans l'OAP.","Devant un déficit neurologique, aucun antihypertenseur avant le scanner cérébral."],"src":"p. 105-107"}],"essentials":[{"id":"224-ess-01","rank":"A","text":"L'HTA se définit en consultation par une moyenne de PAS ≥ 140 et/ou de PAD ≥ 90 mmHg, à confirmer hors cabinet par AMT (de préférence) ou MAPA avant tout traitement, sauf urgence hypertensive.","src":"p. 85-86"},{"id":"224-ess-02","rank":"A","text":"En AMT, l'HTA correspond à une moyenne ≥ 135/85 mmHg ; en MAPA des 24 heures, à ≥ 130/80 mmHg.","src":"p. 86"},{"id":"224-ess-03","rank":"A","text":"La mesure de consultation impose au moins 3 mesures espacées de 1 à 2 minutes après plus de 5 minutes de repos assis, en retenant la moyenne des 2 dernières.","src":"p. 83"},{"id":"224-ess-04","rank":"A","text":"La règle des 3 de l'AMT : 3 mesures le matin et 3 le soir pendant 3 jours consécutifs, soit 18 mesures, avec un appareil validé à brassard huméral.","src":"p. 84"},{"id":"224-ess-05","rank":"A","text":"La PA doit être mesurée aux deux bras lors de la première consultation ; une asymétrie fait suspecter une sténose de l'artère subclavière.","src":"p. 83"},{"id":"224-ess-06","rank":"A","text":"L'hypotension orthostatique est confirmée par une baisse de PAS ≥ 20 mmHg et/ou de PAD ≥ 10 mmHg à 1 et/ou 3 minutes d'orthostatisme.","src":"p. 84"},{"id":"224-ess-07","rank":"A","text":"Toute HTA de grade 3 (≥ 180 et/ou ≥ 110 mmHg) impose de rechercher une urgence hypertensive et une confirmation ambulatoire dans la semaine.","src":"p. 86"},{"id":"224-ess-08","rank":"A","text":"L'HTA blouse blanche (PA de cabinet élevée, ambulatoire normale) ne se traite pas par médicaments mais par MHD et surveillance ; l'HTA masquée se traite comme une HTA habituelle.","src":"p. 86-87"},{"id":"224-ess-09","rank":"A","text":"L'HTA est la maladie chronique la plus fréquente et la première cause de mortalité dans le monde ; en France, 17 millions d'adultes sont hypertendus et seuls 25 % sont diagnostiqués, traités et contrôlés.","src":"p. 87"},{"id":"224-ess-10","rank":"A","text":"Le dépistage de l'HTA est recommandé au moins tous les 3 ans avant 40 ans et au moins une fois par an à partir de 40 ans.","src":"p. 88"},{"id":"224-ess-11","rank":"A","text":"L'HTA est essentielle dans 90 % des cas et secondaire (cause toxique, iatrogène, rénale, rénovasculaire ou endocrinienne) dans 10 % des cas.","src":"p. 88"},{"id":"224-ess-12","rank":"A","text":"L'HTA est la première cause de fibrillation atriale (70 % des patients en FA sont hypertendus) et compte 1 point dans le score CHA2DS2-VASc.","src":"p. 89"},{"id":"224-ess-13","rank":"A","text":"Chez l'hypertendu, 80 % des AVC sont ischémiques et 20 % hémorragiques ; la baisse de la PA prévient mieux les AVC que les événements coronariens.","src":"p. 88-90"},{"id":"224-ess-14","rank":"A","text":"L'HTA est le plus souvent latente, découverte à l'examen systématique ; céphalées occipitales matinales, phosphènes ou épistaxis ne suffisent ni à l'affirmer ni à justifier un traitement immédiat.","src":"p. 90"},{"id":"224-ess-15","rank":"A","text":"Le bilan minimal de l'hypertendu comprend glycémie à jeun et HbA1c, bilan lipidique, natrémie, kaliémie, hémoglobine, créatininémie avec DFG (CKD-EPI), rapport protéinurie/créatininurie et ECG de repos.","src":"p. 92"},{"id":"224-ess-16","rank":"A","text":"L'échocardiographie n'est indiquée qu'en cas d'anomalie ECG ou de symptômes cardiaques ; le fond d'œil est recommandé dans l'HTA de grade 3.","src":"p. 93-94"},{"id":"224-ess-17","rank":"A","text":"Un avis spécialisé d'emblée s'impose en cas d'HTA de grade 3, d'HTA avant 40 ans (hors obésité), d'HTA résistante ou de contexte évocateur d'HTA secondaire comme une hypokaliémie.","src":"p. 94"},{"id":"224-ess-18","rank":"A","text":"La consultation d'annonce informe sur la maladie et ses complications, explique les bénéfices du traitement, fixe la cible de PA et le plan de soins, et aboutit à une décision médicale partagée.","src":"p. 94"},{"id":"224-ess-19","rank":"A","text":"La cible tensionnelle générale est une PAS de 120 à 129 mmHg et une PAD de 70 à 79 mmHg, idéalement 120/70, à atteindre en 3 mois ; sinon la PA la plus basse tolérée et < 140/90 mmHg.","src":"p. 95-96"},{"id":"224-ess-20","rank":"A","text":"Le traitement médicamenteux est débuté d'emblée chez tout hypertendu confirmé ; en cas de PA élevée à risque CV élevé, il est introduit après 3 mois de MHD si la PA reste ≥ 130/80 mmHg.","src":"p. 95"},{"id":"224-ess-21","rank":"A","text":"Les MHD visent 5–6 g de sel par jour, moins de 10 unités d'alcool par semaine, un IMC de 20–25 kg/m², un périmètre abdominal < 94 cm chez l'homme et < 80 cm chez la femme, l'arrêt du tabac et une activité physique régulière.","src":"p. 96"},{"id":"224-ess-22","rank":"A","text":"Cinq classes ont prouvé leur efficacité sur la morbi-mortalité : inhibiteurs calciques, IEC, ARA2, bêtabloquants et diurétiques thiazidiques ou apparentés.","src":"p. 96"},{"id":"224-ess-23","rank":"A","text":"Le traitement initial est une bithérapie fixe à faible dose en monoprise associant un IEC ou un ARA2 à un inhibiteur calcique dihydropyridine ou à un thiazidique ; IEC et ARA2 ne s'associent jamais.","src":"p. 97"},{"id":"224-ess-24","rank":"A","text":"Les bêtabloquants préviennent moins bien les AVC que les autres classes et ne sont utilisés à l'initiation qu'en présence d'une autre indication ; la monothérapie par bêtabloquant n'est pas recommandée.","src":"p. 96-97"},{"id":"224-ess-25","rank":"A","text":"Une monothérapie initiale est réservée à la PA élevée avec indication de traitement, à la fragilité modérée ou sévère, à l'hypotension orthostatique préexistante et à l'âge > 85 ans.","src":"p. 97"},{"id":"224-ess-26","rank":"A","text":"IEC et ARA2 sont contre-indiqués pendant la grossesse ; l'œdème angioneurotique sous IEC contre-indique définitivement les IEC.","src":"p. 98"},{"id":"224-ess-27","rank":"A","text":"Les bêtabloquants sont contre-indiqués dans l'asthme et les BAV de 2e et 3e degré ; les thiazidiques dans l'hypercalcémie, l'hypokaliémie, la goutte et la grossesse.","src":"p. 98"},{"id":"224-ess-28","rank":"A","text":"La toux est l'effet indésirable typique des IEC ; les dihydropyridines donnent œdèmes des membres inférieurs, céphalées et flushs ; les thiazidiques hypokaliémie, hyponatrémie, hyperglycémie et hyperuricémie.","src":"p. 100"},{"id":"224-ess-29","rank":"A","text":"Après toute introduction ou modification d'IEC/ARA2 ou de diurétique, il faut contrôler le ionogramme sanguin et la fonction rénale, et réaliser une AMT à 1 mois.","src":"p. 100"},{"id":"224-ess-30","rank":"A","text":"Si la cible n'est pas atteinte à 1 mois, on renforce MHD et observance puis on passe en trithérapie IEC/ARA2 + inhibiteur calcique + thiazidique avant d'augmenter les doses.","src":"p. 100"},{"id":"224-ess-31","rank":"A","text":"Chez le sujet de plus de 85 ans, fragile ou à espérance de vie < 3 ans : monothérapie initiale, IC dihydropyridine et/ou IEC/ARA2, pas de bêtabloquant ni d'alphabloquant, pas plus d'une trithérapie, cible individualisée sans hypotension orthostatique.","src":"p. 99-100"},{"id":"224-ess-32","rank":"A","text":"Le suivi du patient contrôlé comporte une consultation tous les 3 à 6 mois, un bilan biologique annuel (Na, K, créatinine, protéinurie), glycémie et lipides tous les 3 ans, ECG tous les 3 à 5 ans.","src":"p. 101"},{"id":"224-ess-33","rank":"B","text":"L'HTA résistante est une PA au-dessus de la cible malgré les MHD et au moins trois classes à dose optimale dont un diurétique thiazidique, confirmée par AMT ou MAPA ; elle impose un avis spécialisé.","src":"p. 101-102"},{"id":"224-ess-34","rank":"B","text":"Dans l'HTA résistante vraie, on ajoute la spironolactone (éplérénone si intolérance), puis un bêtabloquant, puis éventuellement alphabloquant ou central, la dénervation rénale se discutant au cas par cas.","src":"p. 102"},{"id":"224-ess-35","rank":"A","text":"Une HTA secondaire se dépiste en cas de PA > 180/110 mmHg brutale ou s'aggravant, d'HTA résistante, d'âge < 40 ans, d'hypokaliémie ou de tout point d'appel clinique ou biologique.","src":"p. 102"},{"id":"224-ess-36","rank":"A","text":"La sténose athéromateuse de l'artère rénale touche l'ostium et le tiers proximal ; la dysplasie fibromusculaire touche la femme jeune et les deux tiers distaux.","src":"p. 103"},{"id":"224-ess-37","rank":"A","text":"Le phéochromocytome se manifeste par une HTA permanente ou paroxystique avec triade de Ménard ; le diagnostic repose sur les dérivés méthoxylés des catécholamines et le traitement sur la chirurgie après alphabloquants puis bêtabloquants.","src":"p. 103-104"},{"id":"224-ess-38","rank":"A","text":"L'hyperaldostéronisme primaire est dû à une hyperplasie bilatérale (70 %) ou à un adénome de Conn (30 %) ; aldostérone haute, rénine basse, rapport aldostérone/rénine très élevé.","src":"p. 104"},{"id":"224-ess-39","rank":"A","text":"L'urgence hypertensive associe une HTA le plus souvent > 180/110 mmHg à une atteinte aiguë d'un organe cible ; la crise hypertensive (grade 3 sans souffrance viscérale) n'est pas une urgence.","src":"p. 105-106"},{"id":"224-ess-40","rank":"A","text":"L'urgence hypertensive se traite en soins intensifs par urapidil et/ou nicardipine IV, en baissant la PA de 20 à 25 % en 2 heures vers 160/110 mmHg en 2 à 6 heures, sauf dissection aortique où la PAS doit passer sous 120 mmHg au plus vite.","src":"p. 106"}],"numbers":[{"id":"224-num-01","rank":"A","label":"Seuil d'HTA en consultation","value":"PAS ≥ 140 et/ou PAD ≥ 90 mmHg","src":"p. 85"},{"id":"224-num-02","rank":"A","label":"Seuil d'HTA en AMT","value":"PAS ≥ 135 et/ou PAD ≥ 85 mmHg","src":"p. 86"},{"id":"224-num-03","rank":"A","label":"Seuil d'HTA en MAPA sur 24 h","value":"PAS ≥ 130 et/ou PAD ≥ 80 mmHg","src":"p. 86"},{"id":"224-num-04","rank":"A","label":"Seuil d'HTA en MAPA nocturne","value":"PAS ≥ 120 et/ou PAD ≥ 70 mmHg","src":"p. 86"},{"id":"224-num-05","rank":"A","label":"PA normale (non élevée) de l'adulte","value":"PAS < 120 et PAD < 70 mmHg","src":"p. 85"},{"id":"224-num-06","rank":"B","label":"PA élevée en consultation","value":"PAS 120–139 et/ou PAD 70–89 mmHg","src":"p. 85"},{"id":"224-num-07","rank":"A","label":"Grades d'HTA (consultation)","value":"Grade 1 : 140–159/90–99 ; grade 2 : 160–179/100–109 ; grade 3 : ≥ 180/≥ 110 mmHg","src":"p. 86"},{"id":"224-num-08","rank":"A","label":"Repos avant la mesure de consultation","value":"> 5 minutes ; > 30 minutes après effort, café ou cigarette","src":"p. 83"},{"id":"224-num-09","rank":"A","label":"Nombre de mesures en consultation","value":"≥ 3 mesures à 1–2 min d'intervalle, moyenne des 2 dernières ; mesures supplémentaires si les 2 premières PAS diffèrent de > 10 mmHg","src":"p. 83"},{"id":"224-num-10","rank":"A","label":"Critères d'hypotension orthostatique","value":"Baisse de PAS ≥ 20 mmHg et/ou de PAD ≥ 10 mmHg à 1 et/ou 3 min debout","src":"p. 84"},{"id":"224-num-11","rank":"A","label":"Règle des 3 de l'AMT","value":"3 mesures matin + 3 mesures soir × 3 jours = 18 mesures (matin : 20 min après le lever)","src":"p. 84"},{"id":"224-num-12","rank":"A","label":"Fréquence des mesures en MAPA","value":"Toutes les 15–30 min le jour, 30–60 min la nuit, sur 24 h","src":"p. 85"},{"id":"224-num-13","rank":"B","label":"Pression pulsée signant une rigidité artérielle","value":"> 65 mmHg","src":"p. 84"},{"id":"224-num-14","rank":"B","label":"Surestimation de la PA par artères incompressibles (manœuvre d'Osler)","value":"20 mmHg, parfois 40 à 50 mmHg","src":"p. 84"},{"id":"224-num-15","rank":"A","label":"Délai de confirmation ambulatoire","value":"Dans le mois pour un grade 2 ; dans la semaine pour un grade 3 sans urgence","src":"p. 86"},{"id":"224-num-16","rank":"A","label":"Prévalence de l'HTA blouse blanche / masquée","value":"15–20 % / 10–15 % des adultes","src":"p. 86-87"},{"id":"224-num-17","rank":"A","label":"Prévalence de l'HTA en France (ESTEBAN)","value":"30 % des 18–74 ans ; 17 millions d'adultes en 2023 ; 25 % seulement diagnostiqués, traités et contrôlés","src":"p. 87"},{"id":"224-num-18","rank":"A","label":"Prévalence selon l'âge","value":"> 60 % après 70 ans ; 70 % après 80 ans","src":"p. 87"},{"id":"224-num-19","rank":"A","label":"Surrisque de complications chez l'hypertendu","value":"AVC × 7, insuffisance cardiaque × 4, coronaropathie × 3, mort subite × 3, AOMI × 2 ; mortalité CV × 2","src":"p. 87-89"},{"id":"224-num-20","rank":"A","label":"Bénéfice d'une baisse de 10 mmHg de PAS (et 5–6 de PAD) sur 5 ans","value":"AVC − 1/3, insuffisance coronarienne − 1/6, insuffisance cardiaque − 46 %","src":"p. 88"},{"id":"224-num-21","rank":"A","label":"Rythme de dépistage de l'HTA","value":"Au moins tous les 3 ans avant 40 ans ; au moins 1 fois par an à partir de 40 ans","src":"p. 88"},{"id":"224-num-22","rank":"A","label":"Part d'HTA essentielle / secondaire","value":"90 % / 10 % ; 15 % des HTA essentielles sont familiales","src":"p. 88-89"},{"id":"224-num-23","rank":"A","label":"Proportion d'hypertendus parmi les patients en FA","value":"70 %","src":"p. 89"},{"id":"224-num-24","rank":"A","label":"Répartition des AVC chez l'hypertendu","value":"80 % ischémiques, 20 % hémorragiques","src":"p. 90"},{"id":"224-num-25","rank":"A","label":"HVG échocardiographique","value":"Masse VG > 115 g/m² (homme) ou > 95 g/m² (femme)","src":"p. 93"},{"id":"224-num-26","rank":"A","label":"Seuils de protéinurie (rapport albuminurie/créatininurie)","value":"> 300 mg/g = protéinurie ; > 30 mg/g déjà pathologique ; insuffisance rénale si DFG < 60 ml/min/1,73 m²","src":"p. 93-94"},{"id":"224-num-27","rank":"A","label":"Âge imposant un avis spécialisé et un dépistage d'HTA secondaire","value":"< 40 ans","src":"p. 94, 102"},{"id":"224-num-28","rank":"A","label":"Cible tensionnelle générale (ESC 2024)","value":"PAS 120–129 et PAD 70–79 mmHg, idéalement 120/70 ; à atteindre à 3 mois ; sinon < 140/90","src":"p. 95-96"},{"id":"224-num-29","rank":"A","label":"Réduction du risque par le traitement","value":"AVC − 20 à 30 % ; SCA et insuffisance cardiaque − 10 à 20 %","src":"p. 95"},{"id":"224-num-30","rank":"A","label":"Baisse de PAS attendue des mesures hygiénodiététiques","value":"5 à 10 mmHg","src":"p. 96"},{"id":"224-num-31","rank":"A","label":"Cibles des MHD","value":"Sel 5–6 g/j (natriurèse ≈ 100 mmol/j ; 1 g NaCl = 17 mmol Na) ; alcool < 10 unités/semaine ; IMC 20–25 ; tour de taille < 94 cm (H), < 80 cm (F)","src":"p. 96"},{"id":"224-num-32","rank":"A","label":"Âge de la monothérapie initiale et de l'adaptation gériatrique","value":"> 85 ans (ou fragilité modérée/sévère, ou espérance de vie < 3 ans)","src":"p. 97, 99"},{"id":"224-num-33","rank":"A","label":"Délai de réévaluation après adaptation thérapeutique","value":"AMT à 1 mois ; trithérapie si cible non atteinte à 1 mois","src":"p. 100"},{"id":"224-num-34","rank":"B","label":"Rythme des consultations une fois la cible atteinte","value":"Tous les 6 mois (faible risque, grade 1) ; tous les 3 mois (risque élevé, MHD seules)","src":"p. 101"},{"id":"224-num-35","rank":"A","label":"Surveillance paraclinique du patient contrôlé","value":"Na, K, créatinine, protéinurie : 1 fois/an ; glycémie et lipides : tous les 3 ans ; ECG : tous les 3 à 5 ans","src":"p. 101"},{"id":"224-num-36","rank":"B","label":"Hypokaliémie évocatrice d'hyperaldostéronisme","value":"< 3,7 mmol/L","src":"p. 104"},{"id":"224-num-37","rank":"B","label":"Fenêtres thérapeutiques avant dosage rénine/aldostérone","value":"ARM arrêtés depuis 6 semaines ; IEC, ARA2, diurétiques, bêtabloquants depuis 2 semaines ; prélèvement le matin 2 h après le lever","src":"p. 104"},{"id":"224-num-38","rank":"A","label":"Hyperaldostéronisme primaire : répartition des causes","value":"Hyperplasie bilatérale 70 % ; adénome 30 %","src":"p. 104"},{"id":"224-num-39","rank":"A","label":"Objectif tensionnel dans l'urgence hypertensive (cas général)","value":"Baisse de 20–25 % en 2 h, 160/110 mmHg en 2 à 6 h ; surveillance PA toutes les 15 min","src":"p. 106"},{"id":"224-num-40","rank":"A","label":"Cibles de PA dans les AVC et la dissection","value":"Dissection : PAS < 120 au plus vite ; hémorragie cérébrale : PAS 140–160 dans les 6 h (pas de chute > 70 mmHg) ; AVC ischémique : traiter si > 220/120 (− 10–15 %) ; thrombolyse : < 185/110 puis < 180/105 sur 24 h","src":"p. 106-107"}],"mnemonics":[{"id":"224-mn-01","rank":"A","title":"Les 5 classes de 1re intention","mnemonic":"L'ABCDI de l'HTA","expansion":"- **A** : **A**RA2\n- **B** : **B**êtabloquants (moins efficaces sur les AVC, seulement si autre indication)\n- **C** : inhibiteurs **C**alciques (dihydropyridines ou non)\n- **D** : **D**iurétiques thiazidiques ou apparentés (indapamide)\n- **I** : **I**EC","src":"p. 96"},{"id":"224-mn-02","rank":"A","title":"Complications de l'HTA (surrisque)","mnemonic":"FADA-CRI","expansion":"- **F** : **F**ibrillation atriale\n- **A** : **A**VC (× 7)\n- **D** : **D**émence vasculaire\n- **A** : **A**OMI (× 2)\n- **C** : insuffisance **C**oronarienne, SCA (× 3)\n- **R** : insuffisance **R**énale chronique terminale\n- **I** : **I**nsuffisance cardiaque (× 4)","src":"p. 87-88"},{"id":"224-mn-03","rank":"A","title":"Symptômes non spécifiques révélateurs de l'HTA","mnemonic":"CÉPI","expansion":"- **C** : **C**éphalées occipitales matinales, battantes, cédant au lever\n- **É** : **É**pistaxis\n- **P** : **P**hosphènes\n- **I** : **I**nsomnie, nervosité, fatigabilité anormale\n\nAucun ne permet d'affirmer l'HTA ni de traiter immédiatement.","src":"p. 90"},{"id":"224-mn-04","rank":"A","title":"Signes d'examen orientant vers une HTA secondaire","mnemonic":"FRANC","expansion":"- **F** : pouls **F**émoraux diminués ou abolis + souffle précordial → coarctation aortique\n- **R** : gros **R**eins palpables → polykystose\n- **A** : souffle **A**ortique abdominal → HTA rénovasculaire\n- **N** : signes cutanés de **N**eurofibromatose → phéochromocytome\n- **C** : syndrome de **C**ushing (peau fine, vergetures pourpres, bosse de bison, hirsutisme, signe du tabouret)","src":"p. 92"},{"id":"224-mn-05","rank":"A","title":"Bilan biologique systématique de l'hypertendu","mnemonic":"« Grand Lion, Il Hurle, Chasse Puis Écoute »","expansion":"- **G** : **G**lycémie à jeun + HbA1c\n- **L** : bilan **L**ipidique (CT, HDL-C, TG, LDL-C calculé)\n- **I** : **I**onogramme : natrémie, kaliémie (sans garrot)\n- **H** : **H**émoglobine, hématocrite\n- **C** : **C**réatininémie + DFG (CKD-EPI)\n- **P** : **P**rotéinurie (rapport protéinurie/créatininurie sur échantillon)\n- **É** : **É**CG de repos","src":"p. 92"},{"id":"224-mn-06","rank":"A","title":"Indications d'avis spécialisé d'emblée / dépistage d'HTA secondaire","mnemonic":"« Karim Joue Rugby Sérieusement » (K-J-R-S)","expansion":"- **K** : hypo**K**aliémie (ou autre point d'appel d'HTA secondaire)\n- **J** : sujet **J**eune, HTA avant 40 ans (sauf obèse : dépister d'abord un SAOS)\n- **R** : HTA **R**ésistante\n- **S** : HTA **S**évère d'emblée, grade 3 (> 180/110 mmHg)","src":"p. 94, 102"},{"id":"224-mn-07","rank":"A","title":"Mesures hygiénodiététiques","mnemonic":"PASTA + K + M","expansion":"- **P** : **P**oids (IMC 20–25, tour de taille < 94 cm H / < 80 cm F)\n- **A** : **A**lcool < 10 unités/semaine\n- **S** : **S**el 5–6 g/j (natriurèse ≈ 100 mmol/j)\n- **T** : arrêt du **T**abac\n- **A** : **A**ctivité physique (aérobie + résistance), lutte contre la sédentarité\n- **K** : potassium (**K**) augmenté sauf maladie rénale chronique avancée\n- **M** : alimentation **M**éditerranéenne, peu de sucre et de boissons sucrées ; café non limité","src":"p. 96"},{"id":"224-mn-08","rank":"B","title":"Facteurs de résistance au traitement","mnemonic":"SOS-DAMPS","expansion":"- **S** : **S**el en excès\n- **O** : mauvaise **O**bservance\n- **S** : **S**AOS\n- **D** : **D**épression\n- **A** : **A**lcool\n- **M** : **M**édicaments hypertensiogènes (AINS, corticoïdes, vasoconstricteurs, œstrogènes)\n- **P** : prise de **P**oids\n- **S** : **S**ubstances psychoactives ou illicites (cannabis, cocaïne, amphétamines)","src":"p. 101"},{"id":"224-mn-09","rank":"A","title":"Principales urgences hypertensives","mnemonic":"DÉPÔTS PAP","expansion":"- **D** : **D**issection aortique (PAS < 120 au plus vite)\n- **É** : **E**ncéphalopathie hypertensive\n- **P** : **P**héochromocytome (labétalol IV)\n- **Ô** : **O**AP / insuffisance ventriculaire gauche (nitrés IV)\n- **T** : **T**oxiques (amphétamines, LSD, cocaïne, ecstasy)\n- **S** : **S**CA avec ou sans sus-ST (nitrés IV)\n- **P** : **P**RES (cécité centrale, lésions occipitales)\n- **A** : **A**VC ou hémorragie méningée\n- **P** : **P**rééclampsie sévère / éclampsie","src":"p. 106"},{"id":"224-mn-10","rank":"A","title":"Causes endocriniennes d'HTA secondaire","mnemonic":"CACHÉ","expansion":"- **C** : **C**onn (hyperaldostéronisme primaire : hyperplasie bilatérale 70 %, adénome 30 %)\n- **A** : **A**cromégalie\n- **C** : **C**ushing (hypercortisolisme)\n- **H** : **H**yperthyroïdie\n- **É** : ph**É**ochromocytome (triade de Ménard)","src":"p. 103-104"},{"id":"224-mn-11","rank":"A","title":"Médicaments hypertensiogènes à rechercher à l'interrogatoire","mnemonic":"RACE CAVE","expansion":"- **R** : **R**églisse (boissons anisées, bonbons, tisanes)\n- **A** : **A**INS\n- **C** : **C**orticoïdes\n- **E** : **E**rythropoïétine\n- **C** : **C**ontraceptifs oraux\n- **A** : **A**nticalcineurines (ciclosporine, tacrolimus)\n- **V** : **V**asoconstricteurs nasaux, anti-**V**EGF et inhibiteurs de tyrosine-kinase\n- **E** : dérivés de l'**E**rgot de seigle\n\nSans oublier les toxiques : cannabis, cocaïne, amphétamines, alcool.","src":"p. 91-92"},{"id":"224-mn-12","rank":"A","title":"Atteintes aiguës de l'HTA maligne","mnemonic":"CRâNe-M","expansion":"Œdème papillaire (stade 4) + PA élevée, avec possible atteinte :\n- **C** : **C**ardiaque (insuffisance ventriculaire gauche, ischémie myocardique)\n- **R** : **R**énale (IRA, protéinurie abondante, hématurie)\n- **N** : **N**eurologique (PRES, encéphalopathie, coma)\n- **M** : **M**icroangiopathie thrombotique (anémie hémolytique mécanique, thrombopénie)","src":"p. 107"}]},"questions":[{"id":"224-qcm-001","type":"QRM","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"stem":"Un patient de 55 ans consulte pour un contrôle tensionnel. Parmi les conditions suivantes, lesquelles sont requises pour une mesure fiable de la PA de consultation ?","options":[{"t":"Mesurer après plus de 5 minutes de repos assis, au calme","ok":true,"why":"Le repos physique et psychique de plus de 5 minutes est une condition standardisée de la mesure."},{"t":"Utiliser un brassard adapté à la taille du bras, positionné à hauteur du cœur","ok":true,"why":"Trois tailles de brassard existent (obèse, standard, enfant) et le brassard doit être placé à hauteur du cœur."},{"t":"Une seule mesure suffit si le patient paraît détendu","ok":false,"why":"Au moins 3 mesures espacées de 1 à 2 minutes sont nécessaires, en retenant la moyenne des 2 dernières."},{"t":"Mesurer juste après une tasse de café","ok":false,"why":"Il faut attendre plus de 30 minutes après un café, une cigarette ou un effort physique."},{"t":"Privilégier systématiquement l'auscultation au stéthoscope","ok":false,"why":"L'appareil électronique validé est recommandé en 1re intention ; le stéthoscope n'est réservé qu'aux patients en fibrillation atriale."}],"explanation":"La mesure de consultation impose des conditions standardisées : repos, brassard adapté, au moins 3 mesures avec moyenne des 2 dernières, et un appareil électronique validé sauf en fibrillation atriale.","src":"p. 83"},{"id":"224-qcm-002","type":"QRM","rank":"B","objective":"224-obj-04","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Chez un patient diabétique hémodialysé de 70 ans, la PA au brassard est mesurée à 210/100 mmHg alors que le pouls radial reste perçu lorsque le brassard est gonflé au-dessus de la PAS estimée. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une manœuvre d'Osler positive","ok":true,"why":"La persistance du pouls radial perçu brassard gonflé au-dessus de la PAS définit cette manœuvre, liée à des artères incompressibles."},{"t":"La PA mesurée est probablement surestimée, parfois de 40 à 50 mmHg","ok":true,"why":"Les calcifications artérielles du sujet âgé, diabétique ou dialysé entraînent une surestimation d'environ 20 mmHg, pouvant atteindre 40 à 50 mmHg."},{"t":"Une pression pulsée supérieure à 65 mmHg est un autre marqueur de cette rigidité artérielle","ok":true,"why":"La pression pulsée (PAS − PAD) au-delà de 65 mmHg signe également une rigidité artérielle."},{"t":"Ce phénomène ne concerne que les sujets jeunes indemnes de facteur de risque","ok":false,"why":"Au contraire, il touche typiquement le sujet âgé, diabétique ou hémodialysé aux artères calcifiées."},{"t":"Ce seul résultat impose un traitement antihypertenseur intraveineux immédiat","ok":false,"why":"Il s'agit d'un artefact de mesure à reconnaître, pas d'une indication de traitement IV urgent en tant que tel."}],"explanation":"Les artères incompressibles surestiment la PA au brassard ; la manœuvre d'Osler et une pression pulsée élevée sont deux indices de ce piège de mesure.","trap":"Ne pas confondre une PA artificiellement élevée par rigidité artérielle avec une véritable urgence hypertensive.","src":"p. 84"},{"id":"224-qcm-003","type":"QRM","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":2,"stem":"Quelles situations justifient de recourir à la MAPA plutôt qu'à l'automesure tensionnelle (AMT) ?","options":[{"t":"Confirmer une HTA résistante","ok":true,"why":"La MAPA fait partie des examens permettant de confirmer une HTA résistante."},{"t":"Rechercher des épisodes d'hypotension symptomatique (asthénie, lipothymies)","ok":true,"why":"C'est une indication spécifique citée pour la MAPA."},{"t":"Explorer la pression artérielle nocturne","ok":true,"why":"La MAPA permet d'étudier spécifiquement la PA nocturne, meilleur prédicteur du risque cardiovasculaire."},{"t":"Une forte variabilité des mesures d'un jour à l'autre","ok":true,"why":"La variabilité importante des mesures fait partie des situations où la MAPA est utile."},{"t":"L'absence de toute difficulté du patient à réaliser son automesure","ok":false,"why":"Dans ce cas, l'AMT reste l'examen recommandé en première intention en France."}],"explanation":"La MAPA est utilisée quand l'AMT est impossible ou peu fiable, ou dans des situations particulières : HTA résistante, hypotensions symptomatiques, forte variabilité, exploration de la PA nocturne.","src":"p. 85"},{"id":"224-qcm-004","type":"QRM","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"stem":"Concernant la mesure de la PA aux deux bras lors de la première consultation d'un patient hypertendu, quelles propositions sont exactes ?","options":[{"t":"Elle permet de dépister une asymétrie tensionnelle","ok":true,"why":"C'est justement l'objectif de cette mesure bilatérale."},{"t":"Une asymétrie fait suspecter une sténose de l'artère subclavière","ok":true,"why":"Une différence de PA entre les deux bras oriente vers cette hypothèse."},{"t":"En cas d'asymétrie, le bras avec les valeurs les plus basses devient le bras de référence","ok":false,"why":"C'est au contraire le bras aux valeurs les plus élevées qui devient le bras de référence."},{"t":"Cette mesure bilatérale ne concerne que les patients de plus de 60 ans","ok":false,"why":"Elle est recommandée chez tout patient, dès la première consultation."},{"t":"Elle fait partie des recommandations de la première consultation pour un hypertendu","ok":true,"why":"La mesure aux deux bras est une des recommandations de la mesure de consultation."}],"explanation":"La PA doit être mesurée aux deux bras à la première consultation : une asymétrie évoque une sténose subclavière, et le bras aux valeurs les plus hautes devient la référence.","src":"p. 83"},{"id":"224-qcm-005","type":"QRM","rank":"A","objective":"224-obj-01","tags":["définition","diagnostic"],"difficulty":2,"stem":"Concernant les catégories de pression artérielle définies par les recommandations européennes de 2024, quelles propositions sont exactes ?","options":[{"t":"La PA normale de l'adulte est inférieure à 120/70 mmHg en consultation","ok":true,"why":"La PA non élevée correspond à une PAS < 120 et une PAD < 70 mmHg."},{"t":"La catégorie « PA élevée » impose une évaluation du risque cardiovasculaire global","ok":true,"why":"Cette catégorie justifie le calcul du risque (SCORE2, SCORE2-OP, etc.) et parfois un traitement si le risque est élevé."},{"t":"La PA élevée se situe entre 120-139 mmHg de PAS et/ou 70-89 mmHg de PAD en consultation","ok":true,"why":"Ce sont exactement les bornes de la catégorie « PA élevée » en mesure de consultation."},{"t":"La catégorie « PA élevée » impose systématiquement un traitement médicamenteux immédiat","ok":false,"why":"Le traitement pharmacologique n'y est introduit qu'après 3 mois de mesures hygiénodiététiques si le risque est élevé et la cible non atteinte."},{"t":"La distribution des PA dans la population comporte un seuil net séparant normotendus et hypertendus","ok":false,"why":"Elle est au contraire continue, le passage à l'HTA étant graduel."}],"explanation":"L'ESC 2024 distingue trois catégories continues de PA ; seule la PA élevée à risque élevé conduit, après échec des MHD, à un traitement pharmacologique.","src":"p. 85"},{"id":"224-qcm-006","type":"QRM","rank":"A","objective":"224-obj-01","tags":["définition"],"difficulty":1,"stem":"À partir de quelles valeurs de PA de consultation parle-t-on d'HTA de grade 3 ?","options":[{"t":"PAS ≥ 140 et/ou PAD ≥ 90 mmHg","ok":false,"why":"Ce sont les valeurs définissant l'HTA en général (grade 1 débutant)."},{"t":"PAS ≥ 160 et/ou PAD ≥ 100 mmHg","ok":false,"why":"Ce sont les valeurs du grade 2."},{"t":"PAS ≥ 180 et/ou PAD ≥ 110 mmHg","ok":true,"why":"Le grade 3 correspond à une PAS ≥ 180 et/ou une PAD ≥ 110 mmHg."},{"t":"PAS ≥ 200 et/ou PAD ≥ 120 mmHg","ok":false,"why":"Ces valeurs dépassent le seuil du grade 3, qui est déjà atteint à 180/110 mmHg."},{"t":"PAS ≥ 135 et/ou PAD ≥ 85 mmHg","ok":false,"why":"Ce sont les valeurs définissant l'HTA en automesure, pas le grade 3 de consultation."}],"explanation":"L'HTA de grade 3 correspond à une PAS ≥ 180 et/ou une PAD ≥ 110 mmHg en consultation ; elle impose de rechercher systématiquement une urgence hypertensive.","src":"p. 86"},{"id":"224-qcm-007","type":"QRM","rank":"A","objective":"224-obj-01","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un homme de 45 ans a une PA de cabinet à 146/92 mmHg mais une automesure strictement normale (moyenne 122/78 mmHg). Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une HTA « blouse blanche »","ok":true,"why":"PA de cabinet élevée avec mesures ambulatoires normales : c'est la définition de l'HTA blouse blanche."},{"t":"Un traitement médicamenteux doit être instauré d'emblée","ok":false,"why":"Dans ce profil, il n'y a pas d'indication à un traitement médicamenteux, seulement des mesures hygiénodiététiques et une surveillance."},{"t":"Ce profil concerne environ 15 à 20 % des adultes","ok":true,"why":"C'est la prévalence rapportée pour l'HTA blouse blanche."},{"t":"Une surveillance régulière hors cabinet est recommandée en raison du risque d'HTA confirmée ultérieurement","ok":true,"why":"Ces patients doivent être surveillés car ils sont à risque de développer une HTA confirmée secondairement."},{"t":"Ce profil expose au même risque cardiovasculaire qu'une HTA confirmée","ok":false,"why":"C'est l'HTA masquée, et non l'HTA blouse blanche, qui expose au même risque que l'HTA habituelle."}],"explanation":"L'HTA blouse blanche associe une PA de cabinet élevée à des mesures ambulatoires normales ; elle ne nécessite pas de traitement mais une surveillance régulière.","trap":"Ne pas confondre HTA blouse blanche (pas de traitement) et HTA masquée (même prise en charge qu'une HTA classique).","src":"p. 86-87"},{"id":"224-qcm-008","type":"QRM","rank":"A","objective":"224-obj-02","tags":["épidémiologie"],"difficulty":1,"stem":"Parmi les données épidémiologiques suivantes concernant l'HTA en France, lesquelles sont exactes ?","options":[{"t":"17 millions d'adultes étaient hypertendus en 2023","ok":true,"why":"C'est le chiffre rapporté pour la France en 2023."},{"t":"Seuls 25 % des hypertendus sont diagnostiqués, traités et contrôlés","ok":true,"why":"C'est la conclusion de l'étude ESTEBAN."},{"t":"La prévalence de l'HTA dépasse 60 % après 70 ans","ok":true,"why":"La prévalence augmente fortement avec l'âge, dépassant 60 % après 70 ans et 70 % après 80 ans."},{"t":"L'HTA touche moins de 10 % des adultes de 18 à 74 ans","ok":false,"why":"L'étude ESTEBAN retrouve une prévalence de 30 % dans cette tranche d'âge."},{"t":"L'HTA est la deuxième cause de mortalité dans le monde","ok":false,"why":"Elle est la première cause de mortalité mondiale, avec plus de 10 millions de décès annuels."}],"explanation":"L'HTA est la maladie chronique la plus fréquente et la première cause de mortalité mondiale ; en France, seul un quart des hypertendus est correctement contrôlé.","src":"p. 87"},{"id":"224-qcm-009","type":"QRM","rank":"A","objective":"224-obj-02","tags":["épidémiologie","complications"],"difficulty":3,"stem":"Chez un patient hypertendu, comparativement à un patient normotendu, quels surrisques sont rapportés dans le chapitre ?","options":[{"t":"Un risque d'AVC multiplié par 7","ok":true,"why":"C'est le surrisque d'AVC rapporté chez l'hypertendu."},{"t":"Un risque d'insuffisance cardiaque multiplié par 4","ok":true,"why":"C'est le surrisque d'insuffisance cardiaque rapporté."},{"t":"Un risque d'insuffisance coronarienne multiplié par 3","ok":true,"why":"C'est le surrisque de maladie coronarienne rapporté, SCA inclus."},{"t":"Un risque d'artériopathie des membres inférieurs multiplié par 10","ok":false,"why":"Le surrisque d'AOMI rapporté est multiplié par 2, non par 10."},{"t":"Une mortalité cardiovasculaire doublée","ok":true,"why":"La mortalité cardiovasculaire de l'hypertendu est doublée par rapport au normotendu."}],"explanation":"L'hypertendu présente un surrisque net de complications cardiovasculaires (AVC × 7, IC × 4, coronaropathie × 3, AOMI × 2) et une mortalité cardiovasculaire doublée.","src":"p. 87-88"},{"id":"224-qcm-010","type":"QRM","rank":"B","objective":"224-obj-03","tags":["physiopathologie"],"difficulty":3,"stem":"Concernant la régulation physiologique de la pression artérielle, quelles associations horizon temporel / mécanisme sont exactes ?","options":[{"t":"Court terme : système sympathique et baroréflexe carotidien et aortique","ok":true,"why":"La régulation à court terme repose sur le système sympathique via le baroréflexe."},{"t":"Moyen terme : système rénine-angiotensine-aldostérone et peptides natriurétiques","ok":true,"why":"La régulation à moyen terme de la volémie et de la vasomotricité passe par le SRAA et les peptides natriurétiques."},{"t":"Long terme : natriurèse de pression et système arginine-vasopressine","ok":true,"why":"La régulation à long terme fait intervenir la natriurèse de pression et le système arginine-vasopressine."},{"t":"Court terme : peptides natriurétiques ANP et BNP","ok":false,"why":"Ces peptides participent à la régulation à moyen terme, pas à court terme."},{"t":"Long terme : baroréflexe carotidien","ok":false,"why":"Le baroréflexe carotidien relève de la régulation à court terme."}],"explanation":"Trois horizons régulent la PA : court terme (système sympathique, baroréflexe), moyen terme (SRAA, peptides natriurétiques) et long terme (natriurèse de pression, arginine-vasopressine).","src":"p. 88"},{"id":"224-qcm-011","type":"QRM","rank":"A","objective":"224-obj-05","tags":["clinique"],"difficulty":2,"stem":"Un homme de 38 ans hypertendu rapporte, à l'interrogatoire, des ronflements bruyants avec pauses respiratoires nocturnes constatées par sa conjointe et une prise de poids récente. Quelles propositions sont exactes ?","options":[{"t":"Ces éléments évoquent un syndrome d'apnées obstructives du sommeil","ok":true,"why":"Ronflements et pauses nocturnes rapportées par le conjoint sont les éléments d'interrogatoire orientant vers un SAOS."},{"t":"La recherche d'une prise de poids récente fait partie des facteurs aggravants recherchés à l'interrogatoire","ok":true,"why":"Le surpoids avec prise de poids récente est un facteur aggravant systématiquement recherché."},{"t":"Le tabagisme, l'alcool et la sédentarité doivent aussi être recherchés comme facteurs aggravants","ok":true,"why":"Ils font partie des facteurs pouvant aggraver l'HTA recherchés à l'interrogatoire."},{"t":"Ces symptômes ne relèvent pas de l'interrogatoire d'un patient hypertendu","ok":false,"why":"Au contraire, ils font explicitement partie des éléments à rechercher à l'interrogatoire d'un hypertendu."},{"t":"Ces symptômes suffisent à eux seuls à affirmer une HTA secondaire","ok":false,"why":"Ils orientent vers un facteur aggravant (SAOS) mais n'affirment pas, seuls, une cause secondaire précise."}],"explanation":"L'interrogatoire d'un hypertendu recherche systématiquement les facteurs aggravants : alimentation, alcool, sédentarité, surpoids, ronflements et pauses nocturnes évocateurs de SAOS.","src":"p. 91"},{"id":"224-qcm-012","type":"QRM","rank":"A","objective":"224-obj-07","tags":["complications"],"difficulty":3,"stem":"Un patient hypertendu de longue date développe une dyspnée d'effort ; l'échocardiographie montre un ventricule gauche hypertrophié, non dilaté, avec des anomalies du remplissage. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une insuffisance cardiaque à fraction d'éjection préservée","ok":true,"why":"Ce tableau (VG hypertrophié non dilaté, anomalies du remplissage) correspond à l'insuffisance cardiaque à FEVG préservée de l'hypertendu."},{"t":"L'hypertrophie ventriculaire gauche est de type concentrique","ok":true,"why":"L'HVG associée à la forme à FEVG préservée est concentrique, sur un cœur hypertrophié non dilaté."},{"t":"Il s'agit d'une hypertrophie ventriculaire gauche excentrique","ok":false,"why":"L'HVG excentrique correspond à la forme dilatée et hypertrophiée de l'insuffisance cardiaque à FEVG altérée, non à ce tableau."},{"t":"La fibrose du ventricule gauche participe aux anomalies de compliance observées","ok":true,"why":"La fibrose ventriculaire, associée à l'HVG, contribue aux troubles de la compliance et de la relaxation."},{"t":"Ce mécanisme nécessite obligatoirement un athérome coronarien associé","ok":false,"why":"Cette forme peut résulter de l'HTA seule, par anomalie du remplissage liée à l'HVG, sans athérome coronarien associé."}],"explanation":"L'insuffisance cardiaque à FEVG préservée de l'hypertendu résulte d'une HVG concentrique avec fibrose, sur un cœur hypertrophié non dilaté, à distinguer de la forme excentrique à FEVG altérée.","src":"p. 89"},{"id":"224-qcm-013","type":"QRM","rank":"A","objective":"224-obj-07","tags":["complications"],"difficulty":3,"stem":"Concernant les accidents vasculaires cérébraux (AVC) survenant chez l'hypertendu, quelles propositions sont exactes ?","options":[{"t":"Environ 80 % sont d'origine ischémique","ok":true,"why":"80 % des AVC de l'hypertendu sont des AIT ou AVC ischémiques."},{"t":"Environ 20 % sont d'origine hémorragique","ok":true,"why":"20 % des AVC de l'hypertendu sont des hémorragies cérébrales."},{"t":"L'hémorragie cérébrale est le plus souvent liée à la rupture d'un microanévrisme ou à une nécrose fibrinoïde","ok":true,"why":"Ce sont les deux mécanismes principaux de l'hémorragie intraparenchymateuse cités."},{"t":"La baisse de la pression artérielle est plus efficace sur les événements coronariens que sur les AVC","ok":false,"why":"C'est l'inverse : la réversibilité du risque par le traitement est meilleure pour les AVC que pour les accidents coronariens."},{"t":"La mortalité cardiovasculaire de l'hypertendu est multipliée par le même facteur chez l'homme et chez la femme","ok":false,"why":"Elle est multipliée par 5 chez l'homme et par 3 chez la femme, donc pas par le même facteur."}],"explanation":"Chez l'hypertendu, 80 % des AVC sont ischémiques et 20 % hémorragiques ; le bénéfice du traitement antihypertenseur est plus marqué sur les AVC que sur les événements coronariens.","src":"p. 88-90"},{"id":"224-qcm-014","type":"QRM","rank":"A","objective":"224-obj-22","tags":["pédiatrie"],"difficulty":1,"stem":"Concernant la mesure de la pression artérielle chez l'enfant, quelles propositions sont exactes ?","options":[{"t":"Elle est recommandée lors de l'examen systématique annuel après l'âge de 3 ans","ok":true,"why":"C'est l'indication de mesure systématique annuelle citée à partir de 3 ans."},{"t":"Elle doit aussi être réalisée en présence de facteurs de risque cardiovasculaire","ok":true,"why":"La mesure est également indiquée en présence de FDR, quel que soit l'âge."},{"t":"Elle nécessite un brassard adapté, la taille « enfant » étant l'une des trois tailles disponibles","ok":true,"why":"Les trois tailles de brassard sont obèse, standard et enfant."},{"t":"Les seuils diagnostiques sont identiques à ceux de l'adulte","ok":false,"why":"Il existe des normes pédiatriques spécifiques, fondées sur des abaques selon l'âge et le sexe."},{"t":"Elle n'est jamais indiquée avant l'adolescence","ok":false,"why":"Au contraire, elle est recommandée dès l'examen systématique après 3 ans."}],"explanation":"Chez l'enfant, la PA se mesure à l'examen systématique annuel après 3 ans et en cas de FDR, avec un brassard adapté et des normes pédiatriques propres à l'âge et au sexe.","src":"p. 82"},{"id":"224-qcm-015","type":"QRM","rank":"A","objective":"224-obj-08","tags":["étiologie","clinique"],"difficulty":2,"stem":"Une femme de 32 ans hypertendue prend une contraception œstroprogestative et utilise fréquemment des vasoconstricteurs nasaux pour des rhinites. Quelles propositions sont exactes ?","options":[{"t":"Ces deux traitements figurent parmi les médicaments hypertensiogènes à rechercher à l'interrogatoire","ok":true,"why":"Contraceptifs oraux et vasoconstricteurs nasaux font partie de la liste des médicaments à rechercher devant une HTA."},{"t":"Les AINS et les corticoïdes doivent également être recherchés à l'interrogatoire","ok":true,"why":"Ils figurent aussi parmi les médicaments hypertensiogènes cités."},{"t":"La consommation de réglisse (boissons anisées, tisanes) peut aussi être en cause","ok":true,"why":"Les produits contenant de la réglisse font partie des substances toxiques hypertensiogènes recherchées."},{"t":"Ces médicaments n'ont aucun lien avec le niveau de pression artérielle","ok":false,"why":"Au contraire, ils sont explicitement cités comme pouvant provoquer ou aggraver une HTA."},{"t":"Seuls les médicaments administrés par voie injectable peuvent élever la pression artérielle","ok":false,"why":"Des médicaments par voie orale ou nasale (contraceptifs, vasoconstricteurs, AINS) sont également en cause."}],"explanation":"L'interrogatoire d'un hypertendu recherche systématiquement les médicaments et toxiques hypertensiogènes : contraceptifs, vasoconstricteurs nasaux, corticoïdes, AINS, réglisse, entre autres.","src":"p. 91-92"},{"id":"224-qru-001","type":"QRU","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"stem":"Quel est le nombre minimal de mesures à réaliser lors d'une mesure de PA en consultation ?","options":[{"t":"1","ok":false,"why":"Une seule mesure ne permet pas de retenir une moyenne fiable."},{"t":"2","ok":false,"why":"Deux mesures ne suffisent pas selon les recommandations."},{"t":"3","ok":true,"why":"Au moins 3 mesures espacées de 1 à 2 minutes sont réalisées, avec la moyenne des 2 dernières."},{"t":"5","ok":false,"why":"Ce nombre n'est le minimum requis qu'en cas de discordance importante entre les 2 premières mesures."},{"t":"10","ok":false,"why":"Ce nombre est très supérieur au minimum recommandé."}],"explanation":"La mesure de consultation impose au moins 3 mesures espacées de 1 à 2 minutes, en retenant la moyenne des 2 dernières.","src":"p. 83"},{"id":"224-qru-002","type":"QRU","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"stem":"Selon la « règle des 3 » de l'automesure tensionnelle, combien de mesures sont réalisées au total ?","options":[{"t":"6","ok":false,"why":"Ce nombre correspond à une seule journée (3 le matin + 3 le soir), pas au total sur 3 jours."},{"t":"9","ok":false,"why":"Ce chiffre ne correspond pas au schéma des 3 mesures matin et soir sur 3 jours."},{"t":"12","ok":false,"why":"Ce chiffre ne correspond pas au schéma recommandé."},{"t":"18","ok":true,"why":"3 mesures le matin et 3 le soir, pendant 3 jours consécutifs, soit 18 mesures au total."},{"t":"24","ok":false,"why":"Ce chiffre dépasse le nombre de mesures recommandé par la règle des 3."}],"explanation":"La règle des 3 impose 3 mesures matin et 3 mesures soir, 3 jours consécutifs, soit 18 mesures au total.","src":"p. 84"},{"id":"224-qru-003","type":"QRU","rank":"A","objective":"224-obj-01","tags":["définition"],"difficulty":1,"stem":"Quel couple de valeurs définit l'HTA en mesure de consultation ?","options":[{"t":"PAS ≥ 130 et/ou PAD ≥ 80 mmHg","ok":false,"why":"Ce sont les seuils de la MAPA sur 24 heures, pas de la consultation."},{"t":"PAS ≥ 135 et/ou PAD ≥ 85 mmHg","ok":false,"why":"Ce sont les seuils de l'automesure tensionnelle."},{"t":"PAS ≥ 140 et/ou PAD ≥ 90 mmHg","ok":true,"why":"Ce sont les seuils définissant l'HTA en mesure de consultation."},{"t":"PAS ≥ 160 et/ou PAD ≥ 100 mmHg","ok":false,"why":"Ce sont les seuils du grade 2 de sévérité, pas la définition de l'HTA."},{"t":"PAS ≥ 120 et/ou PAD ≥ 70 mmHg","ok":false,"why":"Ce sont les seuils au-dessus desquels la PA est considérée « élevée », et non l'HTA."}],"explanation":"En consultation, l'HTA se définit par une moyenne des mesures ≥ 140/90 mmHg.","src":"p. 85"},{"id":"224-qru-004","type":"QRU","rank":"A","objective":"224-obj-02","tags":["épidémiologie"],"difficulty":1,"stem":"Quelle est la part d'HTA secondaire parmi l'ensemble des hypertensions artérielles ?","options":[{"t":"1 %","ok":false,"why":"Ce chiffre est trop faible."},{"t":"10 %","ok":true,"why":"10 % des HTA sont secondaires à une cause identifiable ; 90 % sont essentielles."},{"t":"25 %","ok":false,"why":"Ce chiffre correspond à la proportion d'hypertendus diagnostiqués, traités et contrôlés en France, pas à la part d'HTA secondaire."},{"t":"50 %","ok":false,"why":"Ce chiffre est trop élevé pour l'HTA secondaire."},{"t":"90 %","ok":false,"why":"Ce chiffre correspond à la part d'HTA essentielle, pas secondaire."}],"explanation":"L'HTA est secondaire dans 10 % des cas et essentielle dans 90 % des cas.","src":"p. 88"},{"id":"224-qru-005","type":"QRU","rank":"A","objective":"224-obj-07","tags":["complications"],"difficulty":2,"stem":"Quelle proportion des patients en fibrillation atriale sont hypertendus, selon le chapitre ?","options":[{"t":"30 %","ok":false,"why":"Ce chiffre est trop faible."},{"t":"50 %","ok":false,"why":"Ce chiffre est encore inférieur à la proportion rapportée."},{"t":"70 %","ok":true,"why":"70 % des patients en fibrillation atriale sont hypertendus, faisant de l'HTA sa première cause."},{"t":"90 %","ok":false,"why":"Ce chiffre est supérieur à celui rapporté dans le chapitre."},{"t":"100 %","ok":false,"why":"Tous les patients en FA ne sont pas hypertendus."}],"explanation":"L'HTA est la première cause de fibrillation atriale : 70 % des patients en FA sont hypertendus, et l'HTA vaut 1 point au score CHA2DS2-VASc.","src":"p. 89"},{"id":"224-qroc-001","type":"QROC","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"question":"Sur combien de mesures espacées et en retenant quelle moyenne établit-on la PA de consultation ?","answer":"Au moins 3 mesures espacées de 1 à 2 minutes, en retenant la moyenne des 2 dernières.","accept":["moyenne des 2 dernières mesures sur au moins 3 mesures"],"keywords":["moyenne","deux dernières"],"explanation":"Au moins 3 mesures sont réalisées, espacées de 1 à 2 minutes, et l'on retient la moyenne des 2 dernières.","src":"p. 83"},{"id":"224-qroc-002","type":"QROC","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":1,"question":"Quel est le seuil d'HTA en automesure tensionnelle (AMT) ?","answer":"PAS ≥ 135 et/ou PAD ≥ 85 mmHg.","accept":["135/85 mmHg"],"keywords":["135","85"],"explanation":"L'HTA en AMT est définie par une moyenne ≥ 135/85 mmHg.","src":"p. 86"},{"id":"224-qroc-003","type":"QROC","rank":"A","objective":"224-obj-04","tags":["diagnostic"],"difficulty":2,"question":"Quels sont les deux critères tensionnels définissant une hypotension orthostatique positive ?","answer":"Baisse de la PAS ≥ 20 mmHg et/ou de la PAD ≥ 10 mmHg, à 1 et/ou 3 minutes d'orthostatisme.","accept":["baisse PAS 20 et PAD 10 mmHg"],"keywords":["20","10"],"explanation":"L'hypotension orthostatique est confirmée par une baisse d'au moins 20 mmHg de PAS et/ou 10 mmHg de PAD à 1 et/ou 3 minutes debout.","src":"p. 84"},{"id":"224-qroc-004","type":"QROC","rank":"A","objective":"224-obj-01","tags":["définition"],"difficulty":1,"question":"Quel est le seuil d'HTA en MAPA sur 24 heures ?","answer":"PAS ≥ 130 et/ou PAD ≥ 80 mmHg.","accept":["130/80 mmHg"],"keywords":["130","80"],"explanation":"En MAPA sur 24 heures, l'HTA correspond à une moyenne ≥ 130/80 mmHg.","src":"p. 86"},{"id":"224-qroc-005","type":"QROC","rank":"A","objective":"224-obj-01","tags":["diagnostic"],"difficulty":2,"question":"Quel est le délai recommandé pour confirmer hors cabinet une HTA de grade 2 découverte à la première consultation ?","answer":"Dans le mois.","accept":["1 mois","sous un mois"],"keywords":["mois"],"explanation":"La confirmation ambulatoire d'une HTA de grade 2 doit être réalisée dans le mois, contre une semaine pour un grade 3 sans urgence.","src":"p. 86"},{"id":"224-qroc-006","type":"QROC","rank":"A","objective":"224-obj-01","tags":["diagnostic","pièges"],"difficulty":2,"question":"Comment nomme-t-on le profil associant une PA de cabinet élevée et des mesures ambulatoires normales ?","answer":"HTA « blouse blanche ».","accept":["effet blouse blanche","hypertension blouse blanche"],"keywords":["blouse","blanche"],"explanation":"L'HTA blouse blanche associe une PA de cabinet élevée à des mesures hors cabinet normales ; elle ne se traite pas par médicament.","src":"p. 86"},{"id":"224-qroc-007","type":"QROC","rank":"A","objective":"224-obj-02","tags":["épidémiologie"],"difficulty":1,"question":"D'après l'étude ESTEBAN, quelle proportion des hypertendus français est diagnostiquée, traitée et contrôlée ?","answer":"25 %.","accept":["un quart"],"keywords":["25"],"explanation":"Seuls 25 % des hypertendus français sont diagnostiqués, traités et contrôlés selon l'étude ESTEBAN.","src":"p. 87"},{"id":"224-qroc-008","type":"QROC","rank":"A","objective":"224-obj-02","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est la part d'HTA essentielle parmi l'ensemble des hypertensions ?","answer":"90 %.","accept":["neuf sur dix"],"keywords":["90"],"explanation":"L'HTA essentielle représente 90 % des cas, l'HTA secondaire 10 %.","src":"p. 88"},{"id":"224-qroc-009","type":"QROC","rank":"B","objective":"224-obj-03","tags":["physiopathologie"],"difficulty":2,"question":"Quel mécanisme assure la régulation à long terme de la pression artérielle par excrétion sodée ?","answer":"La natriurèse de pression.","accept":["natriurèse de pression"],"keywords":["natriurèse","pression"],"explanation":"À long terme, l'élévation de PA augmente l'excrétion urinaire de sodium : c'est la natriurèse de pression.","src":"p. 88"},{"id":"224-qroc-010","type":"QROC","rank":"A","objective":"224-obj-07","tags":["complications"],"difficulty":2,"question":"Quel score de risque thromboembolique attribue 1 point à la présence d'une HTA ?","answer":"Le score CHA2DS2-VASc.","accept":["CHA2DS2VASC","score CHA2DS2-VASc"],"keywords":["cha2ds2-vasc"],"explanation":"L'HTA est un facteur de risque thromboembolique de la fibrillation atriale, valant 1 point au score CHA2DS2-VASc.","src":"p. 89"},{"id":"224-qroc-011","type":"QROC","rank":"A","objective":"224-obj-07","tags":["complications","paraclinique"],"difficulty":2,"question":"Quel est le signe biologique précoce de la néphroangiosclérose hypertensive ?","answer":"La microalbuminurie.","accept":["micro-albuminurie"],"keywords":["microalbuminurie"],"explanation":"La néphroangiosclérose se manifeste précocement par une microalbuminurie, marquant l'atteinte glomérulaire.","src":"p. 90"},{"id":"224-qroc-012","type":"QROC","rank":"A","objective":"224-obj-08","tags":["clinique","étiologie"],"difficulty":2,"question":"Quelle triade symptomatique, survenant par crises, oriente vers un phéochromocytome à l'interrogatoire ?","answer":"Céphalées, sueurs et palpitations (triade de Ménard).","accept":["triade de Ménard"],"keywords":["céphalées","sueurs","palpitations"],"explanation":"La triade de Ménard (céphalées, sueurs, palpitations), survenant par crises brutales sans facteur déclenchant, oriente vers un phéochromocytome.","src":"p. 92"},{"id":"224-open-01","type":"OPEN","rank":"A","objective":"224-obj-04","difficulty":2,"tags":["diagnostic"],"src":"p. 83-86","prompt":"Un homme de 52 ans présente une PA mesurée à 148/92 mmHg lors d'une première consultation, dans des conditions standardisées. Décrivez la démarche de confirmation diagnostique de l'HTA, en précisant les méthodes possibles et leurs seuils respectifs.","rubric":[{"point":"Rappeler que la PA de consultation ≥ 140/90 mmHg fait suspecter une HTA sans l'affirmer","weight":2},{"point":"Indiquer que la confirmation hors cabinet est nécessaire avant traitement, sauf urgence hypertensive","weight":2},{"point":"Citer l'AMT comme méthode de confirmation préférentielle avec son seuil (≥ 135/85 mmHg) et son protocole (règle des 3)","weight":3},{"point":"Citer la MAPA comme alternative en cas d'AMT impossible ou peu fiable, avec son seuil (≥ 130/80 mmHg sur 24 h)","weight":2},{"point":"Préciser le délai de confirmation selon le grade (1 mois en grade 2, 1 semaine en grade 3 sans urgence)","weight":1}],"model":"Une PA de cabinet à 148/92 mmHg fait suspecter une HTA de grade 1, mais ne permet pas d'affirmer le diagnostic. Il faut confirmer par une mesure hors cabinet, préférentiellement une automesure tensionnelle selon la règle des 3 (3 mesures matin et soir, 3 jours, moyenne des 2 dernières de chaque série) : le diagnostic d'HTA est confirmé si la moyenne est ≥ 135/85 mmHg. En cas d'AMT impossible ou peu fiable, une MAPA sur 24 heures peut être proposée, avec un seuil de confirmation à 130/80 mmHg. Cette confirmation doit être obtenue avant tout traitement, sauf en présence d'une urgence hypertensive."},{"id":"224-open-02","type":"OPEN","rank":"A","objective":"224-obj-02","difficulty":2,"tags":["épidémiologie","prévention"],"src":"p. 87-88","prompt":"Expliquez, à l'aide des données épidémiologiques du chapitre, pourquoi un dépistage systématique et régulier de l'HTA est recommandé en population générale.","rubric":[{"point":"Rappeler que l'HTA est la maladie chronique la plus fréquente et la première cause de mortalité mondiale","weight":2},{"point":"Souligner qu'elle est le plus souvent totalement latente, sans symptôme spécifique fiable","weight":2},{"point":"Citer le faible taux de contrôle en France (seuls 25 % diagnostiqués, traités et contrôlés)","weight":2},{"point":"Mentionner le bénéfice démontré du contrôle tensionnel sur les complications et la mortalité","weight":2},{"point":"Préciser le rythme de dépistage recommandé (tous les 3 ans avant 40 ans, annuel après 40 ans)","weight":2}],"model":"L'HTA est la maladie chronique la plus fréquente au monde et la première cause de mortalité, avec plus de 10 millions de décès annuels ; en France, 17 millions d'adultes sont concernés mais seuls 25 % sont diagnostiqués, traités et contrôlés. Elle reste le plus souvent totalement asymptomatique, découverte fortuitement à l'examen systématique, ce qui explique ce faible taux de contrôle. Or, un traitement adapté réduit nettement les complications cardiovasculaires et rénales et la mortalité associée. C'est pourquoi un dépistage systématique et régulier est recommandé : au moins tous les 3 ans avant 40 ans, et au moins une fois par an à partir de 40 ans, par tout professionnel de santé impliqué dans le suivi du patient."},{"id":"224-open-03","type":"OPEN","rank":"A","objective":"224-obj-07","difficulty":3,"tags":["complications"],"src":"p. 89","prompt":"Décrivez les deux mécanismes par lesquels l'HTA peut conduire à une insuffisance cardiaque, en précisant le type d'hypertrophie ventriculaire gauche associé à chacun.","rubric":[{"point":"Décrire l'insuffisance cardiaque à FEVG altérée d'origine ischémique (coronaropathie, avec ou sans infarctus)","weight":2},{"point":"Décrire l'insuffisance cardiaque à FEVG altérée liée à l'augmentation de postcharge, avec HVG excentrique (VG dilaté et hypertrophié)","weight":3},{"point":"Décrire l'insuffisance cardiaque à FEVG préservée par anomalie du remplissage, liée à l'HVG et à la fibrose, cœur hypertrophié non dilaté","weight":3},{"point":"Préciser que l'angor de l'hypertendu peut relever de l'athérome, de la baisse de réserve coronarienne liée à l'HVG, ou des deux","weight":2}],"model":"L'HTA peut conduire à une insuffisance cardiaque à fraction d'éjection altérée par deux voies : une atteinte ischémique (maladie coronarienne, avec ou sans infarctus), ou l'élévation permanente de la postcharge propre à l'HTA sévère, qui aboutit à un ventricule gauche dilaté et hypertrophié, réalisant une HVG excentrique. Elle peut aussi conduire à une insuffisance cardiaque à fraction d'éjection préservée, par anomalie du remplissage (troubles de la compliance et de la relaxation) liée à l'HVG et à la fibrose ventriculaire, sur un cœur hypertrophié mais non dilaté. Par ailleurs, l'angor de l'hypertendu peut relever d'un athérome coronarien, d'une baisse de la réserve coronarienne due à l'HVG, ou de l'association des deux mécanismes."},{"id":"224-open-04","type":"OPEN","rank":"A","objective":"224-obj-05","difficulty":2,"tags":["clinique","diagnostic"],"src":"p. 91","prompt":"Une HTA vient d'être confirmée chez un patient. Détaillez les objectifs de l'évaluation initiale qui doit alors être conduite.","rubric":[{"point":"Préciser le niveau de PA du patient","weight":1},{"point":"Évaluer le risque cardiovasculaire global en identifiant les facteurs de risque associés","weight":2},{"point":"Rechercher une atteinte des organes cibles, clinique ou infraclinique (vasculaire, cardiaque, cérébrale, rénale)","weight":2},{"point":"Rechercher des facteurs aggravant la maladie","weight":1},{"point":"Rechercher des arguments orientant vers une HTA secondaire","weight":1},{"point":"Conclure par une consultation d'annonce de l'HTA","weight":1}],"model":"Une fois l'HTA confirmée, l'évaluation initiale poursuit cinq objectifs : préciser le niveau de PA ; évaluer le risque cardiovasculaire global du patient en identifiant les facteurs de risque associés ; rechercher une atteinte des organes cibles, clinique ou infraclinique, aux niveaux vasculaire, cardiaque, cérébral et rénal ; rechercher des facteurs susceptibles d'aggraver l'HTA ; et rechercher des arguments orientant vers une HTA secondaire. Cette démarche se conclut par une consultation d'annonce, qui informe le patient et permet de fixer conjointement les objectifs de la prise en charge."},{"id":"224-qcm-101","type":"QRM","rank":"A","objective":"224-obj-06","tags":["paraclinique","biologie"],"difficulty":1,"stem":"Concernant le bilan systématique proposé à tout patient hypertendu, quels examens en font partie ?","options":[{"t":"Glycémie à jeun et HbA1c","ok":true,"why":"Ces deux dosages font partie du bilan minimal systématique."},{"t":"Bilan lipidique complet (cholestérol total, HDL-C, triglycérides, LDL-C calculé)","ok":true,"why":"Le bilan lipidique complet fait partie du bilan minimal."},{"t":"Créatininémie avec estimation du débit de filtration glomérulaire par la formule CKD-EPI","ok":true,"why":"L'estimation du DFG par CKD-EPI est systématique dans le bilan minimal."},{"t":"Dosage systématique des dérivés méthoxylés urinaires","ok":false,"why":"Ce dosage n'est réalisé qu'en cas de suspicion d'HTA secondaire, pas de façon systématique."},{"t":"Échocardiographie systématique","ok":false,"why":"Elle n'est indiquée qu'en présence d'une anomalie ECG ou de symptômes cardiaques, jamais de façon systématique."}],"explanation":"Le bilan minimal systématique comprend glycémie/HbA1c, bilan lipidique, ionogramme, hémoglobine, créatininémie avec DFG, protéinurie et ECG de repos.","src":"p. 92"},{"id":"224-qcm-102","type":"QRM","rank":"A","objective":"224-obj-06","tags":["paraclinique"],"difficulty":2,"stem":"Un hypertendu de 60 ans est asymptomatique, sans souffle vasculaire, avec un ECG de repos normal. Quels examens ne sont pas indiqués chez lui selon le chapitre ?","options":[{"t":"L'échocardiographie","ok":true,"why":"Elle n'est pas réalisée chez le sujet asymptomatique avec un ECG normal."},{"t":"L'index de pression systolique et l'échodoppler des membres inférieurs","ok":true,"why":"Ces examens ne sont pas indiqués chez le sujet asymptomatique sans souffle vasculaire."},{"t":"Le fond d'œil, en l'absence de grade 3","ok":true,"why":"Le fond d'œil n'est recommandé que dans l'HTA de grade 3, pas chez ce patient de grade non précisé et asymptomatique."},{"t":"Le rapport protéinurie/créatininurie sur échantillon d'urine","ok":false,"why":"Ce dosage fait partie du bilan systématique et reste indiqué, quel que soit le statut symptomatique."},{"t":"La créatininémie avec estimation du DFG","ok":false,"why":"Elle fait partie du bilan systématique et reste indiquée chez tout hypertendu."}],"explanation":"Échocardiographie, IPS/échodoppler et fond d'œil ne sont réalisés que s'ils modifient la prise en charge (anomalie ECG, symptômes, souffle, grade 3) ; le bilan biologique minimal reste systématique.","src":"p. 93-94"},{"id":"224-qcm-103","type":"QRM","rank":"A","objective":"224-obj-06","tags":["ECG","paraclinique"],"difficulty":2,"stem":"Concernant l'ECG de repos systématique de l'hypertendu, quelles propositions sont exactes ?","options":[{"t":"Il peut mettre en évidence des signes électriques d'hypertrophie ventriculaire gauche (Sokolow, Cornell, Lewis)","ok":true,"why":"Ces indices sont utilisés pour rechercher une HVG électrique."},{"t":"Un ECG initial normal peut servir de référence pour l'avenir","ok":true,"why":"Un ECG normal initial constitue un repère utile en cas d'anomalies ultérieures."},{"t":"Il permet de détecter une séquelle d'infarctus du myocarde méconnu","ok":true,"why":"L'ECG peut révéler une séquelle d'infarctus passé inaperçu."},{"t":"Sa sensibilité pour détecter une HVG est excellente","ok":false,"why":"L'ECG est au contraire peu sensible : des signes électriques traduisent surtout une HVG déjà marquée."},{"t":"Il est réalisé uniquement en cas de symptômes cardiaques","ok":false,"why":"Il fait partie du bilan systématique, réalisé chez tout hypertendu et non uniquement en cas de symptômes."}],"explanation":"L'ECG de repos systématique recherche HVG, séquelle d'infarctus, troubles de repolarisation et du rythme, mais reste peu sensible pour l'HVG.","src":"p. 93"},{"id":"224-qcm-104","type":"QRM","rank":"A","objective":"224-obj-06","tags":["imagerie","paraclinique"],"difficulty":2,"stem":"Concernant l'échocardiographie du patient hypertendu, quelles propositions sont exactes ?","options":[{"t":"L'hypertrophie ventriculaire gauche est définie par une masse VG supérieure à 115 g/m² chez l'homme et 95 g/m² chez la femme","ok":true,"why":"Ce sont les seuils échocardiographiques d'HVG cités dans le chapitre."},{"t":"Elle permet d'étudier la fonction systolique et diastolique du ventricule gauche","ok":true,"why":"L'échocardiographie recherche des troubles de cinétique segmentaire et des anomalies du remplissage."},{"t":"Elle peut mettre en évidence un anévrisme de l'aorte ascendante ou abdominale","ok":true,"why":"L'échocardiographie recherche notamment un anévrisme de l'aorte."},{"t":"Elle doit être réalisée systématiquement chez tout hypertendu, même asymptomatique avec un ECG normal","ok":false,"why":"Elle n'est pas indiquée chez le sujet asymptomatique à ECG normal."},{"t":"Un remodelage concentrique du ventricule gauche n'a aucune valeur pronostique","ok":false,"why":"Au contraire, le remodelage concentrique est associé à un pronostic altéré."}],"explanation":"L'échocardiographie, si indiquée, recherche une HVG (masse VG > 115 g/m² homme, > 95 g/m² femme), étudie la fonction VG et dépiste un anévrisme aortique.","src":"p. 93"},{"id":"224-qcm-105","type":"QRM","rank":"A","objective":"224-obj-08","tags":["clinique"],"difficulty":1,"stem":"À l'examen clinique d'un patient hypertendu, quels signes évoquent une atteinte des organes cibles ?","options":[{"t":"Un souffle carotidien ou un déficit neurologique focal","ok":true,"why":"Ces signes évoquent une atteinte vasculaire cérébrale."},{"t":"Une tachycardie, une arythmie ou un galop","ok":true,"why":"Ces signes évoquent une atteinte cardiaque."},{"t":"Des pouls fémoraux abolis ou asymétriques, un souffle abdominal, une masse battante","ok":true,"why":"Ces signes évoquent une atteinte des artères périphériques."},{"t":"Une tension musculaire abdominale isolée sans autre anomalie","ok":false,"why":"Ce signe n'est pas cité comme évocateur d'une atteinte d'organe cible dans le chapitre."},{"t":"Une fréquence cardiaque strictement normale au repos","ok":false,"why":"Une fréquence cardiaque normale n'est pas un signe d'atteinte d'organe cible, c'est un examen normal."}],"explanation":"L'examen clinique de l'hypertendu recherche des signes d'atteinte neurovasculaire, cardiaque et artérielle périphérique.","src":"p. 92"},{"id":"224-qcm-106","type":"QRM","rank":"A","objective":"224-obj-08","tags":["clinique","étiologie"],"difficulty":2,"stem":"Chez un patient hypertendu, quels signes d'examen clinique orientent vers une HTA secondaire ?","options":[{"t":"Un souffle précordial avec diminution ou abolition des pouls fémoraux","ok":true,"why":"Ce signe oriente vers une coarctation de l'aorte."},{"t":"Un souffle aortique abdominal","ok":true,"why":"Ce signe oriente vers une HTA rénovasculaire."},{"t":"Des gros reins palpables","ok":true,"why":"Ce signe oriente vers une polykystose rénale."},{"t":"Des signes cutanés de neurofibromatose","ok":true,"why":"Ce signe oriente vers un phéochromocytome."},{"t":"Une amyotrophie proximale isolée sans autre signe évocateur suffit à elle seule à poser le diagnostic de Cushing","ok":false,"why":"L'amyotrophie proximale n'est qu'un des éléments du syndrome de Cushing, qui associe aussi peau fine, vergetures pourpres, érythrose et bosse de bison."}],"explanation":"L'examen clinique recherche des signes orientant vers une cause secondaire : coarctation (pouls fémoraux), rénovasculaire (souffle abdominal), polykystose (gros reins), phéochromocytome (neurofibromatose) et Cushing (ensemble de signes cutanés et morphologiques).","src":"p. 92"},{"id":"224-qcm-107","type":"QRM","rank":"A","objective":"224-obj-08","tags":["diagnostic"],"difficulty":2,"stem":"Dans quelles situations un avis spécialisé d'emblée s'impose-t-il chez un patient hypertendu ?","options":[{"t":"HTA sévère d'emblée, de grade 3","ok":true,"why":"C'est une des situations imposant un avis spécialisé d'emblée."},{"t":"HTA découverte avant l'âge de 40 ans, hors contexte d'obésité","ok":true,"why":"L'âge < 40 ans impose un avis spécialisé, sauf obésité où l'on dépiste d'abord un SAOS."},{"t":"HTA résistante","ok":true,"why":"L'HTA résistante impose un avis spécialisé après avoir éliminé une fausse résistance."},{"t":"Situation clinique ou biologique évocatrice d'HTA secondaire, comme une hypokaliémie associée","ok":true,"why":"L'association HTA et hypokaliémie est un exemple explicite d'indication à un avis spécialisé."},{"t":"Toute HTA de grade 1 bien contrôlée par les mesures hygiénodiététiques","ok":false,"why":"Ce profil ne relève pas d'un avis spécialisé d'emblée, contrairement aux situations précédentes."}],"explanation":"Un avis spécialisé d'emblée s'impose en cas de grade 3, d'âge < 40 ans (hors obésité), d'HTA résistante, ou de contexte évocateur d'HTA secondaire.","src":"p. 94"},{"id":"224-qcm-108","type":"QRM","rank":"A","objective":"224-obj-13","tags":["traitement"],"difficulty":1,"stem":"Quels sont les objectifs de la consultation d'annonce chez un patient dont l'HTA vient d'être confirmée ?","options":[{"t":"Informer sur la maladie et les risques de complications aiguës et chroniques","ok":true,"why":"C'est un objectif explicite de la consultation d'annonce."},{"t":"Expliquer les bénéfices démontrés du traitement antihypertenseur","ok":true,"why":"Cet objectif fait partie de la consultation d'annonce."},{"t":"Fixer les objectifs du traitement, dont la cible de PA, et établir un plan de soins","ok":true,"why":"La fixation des objectifs et du plan de soins est un objectif central de cette consultation."},{"t":"Aboutir à une décision médicale partagée avec le patient","ok":true,"why":"Le recueil du point de vue du patient vise une décision médicale partagée."},{"t":"Prescrire d'emblée une trithérapie chez tous les patients","ok":false,"why":"La consultation d'annonce ne prescrit pas systématiquement une trithérapie : la stratégie dépend du niveau de PA et du risque."}],"explanation":"La consultation d'annonce informe, explique les bénéfices du traitement, fixe les objectifs et le plan de soins, et vise une décision médicale partagée.","src":"p. 94"},{"id":"224-qcm-109","type":"QRM","rank":"A","objective":"224-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant la stratégie thérapeutique selon le niveau de PA de consultation et le risque cardiovasculaire, quelles propositions sont exactes ?","options":[{"t":"Une HTA confirmée impose un traitement pharmacologique d'emblée chez tous les patients","ok":true,"why":"C'est la règle pour toute HTA confirmée, quel que soit le niveau de risque."},{"t":"Une PA élevée (130-139/70-89 mmHg) sans risque cardiovasculaire élevé ne nécessite pas de traitement médicamenteux d'emblée","ok":true,"why":"Dans ce cas, seule une surveillance régulière et une réévaluation annuelle du risque sont recommandées."},{"t":"Une PA élevée avec risque cardiovasculaire élevé peut nécessiter un traitement après 3 mois de mesures hygiénodiététiques si la cible n'est pas atteinte","ok":true,"why":"Le traitement pharmacologique est démarré après 3 mois de MHD inefficaces, si la PA reste ≥ 130/80 mmHg."},{"t":"Les mesures hygiénodiététiques ne sont proposées qu'en cas d'HTA confirmée","ok":false,"why":"Elles sont proposées dans toutes les situations du tableau, y compris pour une PA élevée sans HTA confirmée."},{"t":"Une PA entre 120 et 129 mmHg de PAS nécessite un traitement pharmacologique","ok":false,"why":"Dans cette situation, seules des mesures hygiénodiététiques sont recommandées, sans traitement pharmacologique."}],"explanation":"La stratégie thérapeutique dépend du niveau de PA et du risque cardiovasculaire global ; seule l'HTA confirmée impose un traitement médicamenteux immédiat chez tous.","src":"p. 95"},{"id":"224-qcm-110","type":"QRM","rank":"A","objective":"224-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant l'initiation du traitement médicamenteux de l'HTA, quelles propositions sont exactes ?","options":[{"t":"La bithérapie d'emblée, à faible dose et en association fixe, est recommandée pour la majorité des patients","ok":true,"why":"C'est la stratégie initiale recommandée sauf cas particulier."},{"t":"L'association IEC ou ARA2 avec un inhibiteur calcique dihydropyridine est une association privilégiée","ok":true,"why":"C'est l'une des deux associations privilégiées en bithérapie initiale."},{"t":"L'association IEC ou ARA2 avec un diurétique thiazidique est également privilégiée","ok":true,"why":"C'est la seconde association privilégiée en bithérapie initiale."},{"t":"L'association d'un IEC et d'un ARA2 est recommandée pour renforcer le blocage du système rénine-angiotensine","ok":false,"why":"Il ne faut jamais associer IEC et ARA2, quelle que soit la situation."},{"t":"Le choix privilégie une monoprise quotidienne avec des molécules à demi-vie longue","ok":true,"why":"La monoprise avec demi-vie longue favorise l'observance et fait partie des recommandations d'initiation."}],"explanation":"L'initiation privilégie une bithérapie fixe à faible dose, en monoprise, associant IEC/ARA2 à un IC dihydropyridine ou à un thiazidique ; l'association IEC + ARA2 est proscrite.","src":"p. 96-97"},{"id":"224-qcm-111","type":"QRM","rank":"A","objective":"224-obj-14","tags":["traitement"],"difficulty":2,"stem":"Chez quels patients une monothérapie initiale est-elle recommandée pour traiter l'HTA ?","options":[{"t":"PA élevée (120-139/70-89 mmHg) avec indication de traitement pharmacologique","ok":true,"why":"C'est l'un des critères justifiant une monothérapie initiale."},{"t":"Fragilité gériatrique modérée ou sévère","ok":true,"why":"La fragilité modérée ou sévère justifie de débuter par une monothérapie."},{"t":"Hypotension orthostatique préexistante avant le traitement","ok":true,"why":"C'est un critère explicite de monothérapie initiale."},{"t":"Âge supérieur à 85 ans","ok":true,"why":"L'âge > 85 ans est un critère de monothérapie initiale."},{"t":"Tout patient présentant une HTA confirmée de grade 1, quel que soit son âge","ok":false,"why":"Une HTA confirmée relève en général d'une bithérapie d'emblée, sauf si l'un des critères de monothérapie est présent."}],"explanation":"La monothérapie initiale est réservée à la PA élevée à traiter, à la fragilité, à l'hypotension orthostatique préexistante et à l'âge > 85 ans ; en dehors de ces situations, la bithérapie d'emblée est privilégiée.","src":"p. 97"},{"id":"224-qcm-112","type":"QRM","rank":"A","objective":"224-obj-15","tags":["traitement"],"difficulty":2,"stem":"Concernant les contre-indications absolues des antihypertenseurs, quelles associations sont exactes ?","options":[{"t":"IEC et ARA2 : la grossesse","ok":true,"why":"La grossesse est une contre-indication absolue commune aux IEC et aux ARA2."},{"t":"Bêtabloquants : l'asthme et le bloc atrioventriculaire de 2e ou 3e degré","ok":true,"why":"Ce sont les deux contre-indications absolues des bêtabloquants citées."},{"t":"Thiazidiques : la goutte et l'hypokaliémie","ok":true,"why":"Goutte, hypokaliémie, hypercalcémie et grossesse sont des contre-indications absolues des thiazidiques."},{"t":"Inhibiteurs calciques non dihydropyridiniques (bradycardisants) : le BAV de 2e ou 3e degré","ok":true,"why":"Ces molécules bradycardisantes sont contre-indiquées en cas de BAV 2 ou 3, et dans l'insuffisance cardiaque à FEVG altérée."},{"t":"Inhibiteurs calciques dihydropyridiniques : le BAV de 2e ou 3e degré","ok":false,"why":"Cette contre-indication concerne les inhibiteurs calciques non dihydropyridiniques (bradycardisants), pas les dihydropyridines."}],"explanation":"Chaque classe a ses contre-indications absolues propres ; il ne faut pas confondre inhibiteurs calciques dihydropyridiniques et non dihydropyridiniques, ces derniers seuls étant contre-indiqués en cas de trouble de conduction.","trap":"Les inhibiteurs calciques dihydropyridiniques sont contre-indiqués en cas d'insuffisance cardiaque non contrôlée, pas en cas de BAV.","src":"p. 98"},{"id":"224-qcm-113","type":"QRM","rank":"A","objective":"224-obj-15","tags":["traitement"],"difficulty":2,"stem":"Concernant les effets indésirables typiques des antihypertenseurs, quelles associations sont exactes ?","options":[{"t":"IEC : toux","ok":true,"why":"La toux est l'effet indésirable classique des IEC."},{"t":"Inhibiteurs calciques dihydropyridiniques : œdèmes des membres inférieurs, céphalées, flushs","ok":true,"why":"Ce sont les effets indésirables typiques des dihydropyridines."},{"t":"Diurétiques thiazidiques : hypokaliémie, hyperglycémie, hyperuricémie","ok":true,"why":"Ce sont les troubles métaboliques classiques des thiazidiques."},{"t":"Bêtabloquants : dysfonction érectile et bradycardie sinusale","ok":true,"why":"Ces effets indésirables figurent parmi ceux des bêtabloquants."},{"t":"ARA2 : toux fréquente comparable aux IEC","ok":false,"why":"Les ARA2 exposent surtout à l'hyperkaliémie et à l'insuffisance rénale fonctionnelle, pas à la toux caractéristique des IEC."}],"explanation":"Chaque classe a un profil d'effets indésirables propre ; la toux distingue spécifiquement les IEC des ARA2, qui n'en sont pas responsables.","src":"p. 100"},{"id":"224-qcm-114","type":"QRM","rank":"B","objective":"224-obj-16","tags":["traitement"],"difficulty":2,"stem":"Un patient hypertendu a un antécédent d'infarctus du myocarde. Quelles classes d'antihypertenseurs sont à privilégier selon le chapitre ?","options":[{"t":"Les IEC","ok":true,"why":"Les IEC font partie des classes à privilégier après un infarctus du myocarde."},{"t":"Les ARA2","ok":true,"why":"Les ARA2 sont également à privilégier dans ce contexte."},{"t":"Les bêtabloquants","ok":true,"why":"Les bêtabloquants sont à privilégier après un antécédent d'infarctus."},{"t":"Les diurétiques thiazidiques en première intention systématique","ok":false,"why":"Ce n'est pas la classe préférentiellement citée pour l'antécédent d'infarctus dans le tableau des comorbidités."},{"t":"Les inhibiteurs calciques non dihydropyridiniques en première intention systématique","ok":false,"why":"Ce n'est pas la classe préférentiellement citée pour l'antécédent d'infarctus."}],"explanation":"En cas d'antécédent d'infarctus, IEC, ARA2 et bêtabloquants sont les classes à privilégier selon le tableau des comorbidités orientant le choix du traitement.","src":"p. 98"},{"id":"224-qcm-115","type":"QRM","rank":"A","objective":"224-obj-17","tags":["traitement"],"difficulty":2,"stem":"Concernant l'adaptation du traitement antihypertenseur chez le sujet âgé fragile de plus de 85 ans, quelles propositions sont exactes ?","options":[{"t":"Le traitement est initié en monothérapie","ok":true,"why":"C'est la première adaptation recommandée chez le sujet âgé fragile."},{"t":"Les inhibiteurs calciques dihydropyridiniques et/ou les IEC/ARA2 sont privilégiés en 1re intention","ok":true,"why":"Ce sont les classes privilégiées en 1re intention chez le sujet âgé fragile."},{"t":"Les bêtabloquants sont évités, sauf indication formelle","ok":true,"why":"Les bêtabloquants et les alphabloquants sont à éviter chez le sujet âgé fragile."},{"t":"On peut dépasser une trithérapie si la cible n'est pas atteinte","ok":false,"why":"Chez le sujet âgé fragile, il ne faut pas dépasser une trithérapie antihypertensive."},{"t":"La cible tensionnelle doit être individualisée, sans hypotension orthostatique","ok":true,"why":"La cible est adaptée à la tolérance clinique et paraclinique, en évitant toute hypotension orthostatique."}],"explanation":"Chez le sujet âgé fragile ou de plus de 85 ans : monothérapie initiale, IC dihydropyridines et/ou IEC/ARA2 privilégiés, pas de bêtabloquant ni d'alphabloquant, pas plus d'une trithérapie, cible individualisée.","src":"p. 99-100"},{"id":"224-qru-101","type":"QRU","rank":"A","objective":"224-obj-06","tags":["paraclinique"],"difficulty":1,"stem":"À partir de quelle valeur du rapport protéinurie/créatininurie (RAC) parle-t-on de protéinurie franche ?","options":[{"t":"> 30 mg/g","ok":false,"why":"Cette valeur est déjà considérée comme pathologique, mais la protéinurie franche est définie au-delà de 300 mg/g."},{"t":"> 100 mg/g","ok":false,"why":"Ce chiffre n'est pas le seuil retenu pour la protéinurie franche."},{"t":"> 300 mg/g","ok":true,"why":"On parle de protéinurie au-delà de 300 mg/g, des valeurs supérieures à 30 mg/g étant déjà pathologiques."},{"t":"> 1 000 mg/g","ok":false,"why":"Ce chiffre est supérieur au seuil retenu dans le chapitre."},{"t":"> 3 000 mg/g","ok":false,"why":"Ce chiffre correspond à un niveau néphrotique, très supérieur au seuil défini ici."}],"explanation":"Le rapport protéinurie/créatininurie définit la protéinurie au-delà de 300 mg/g, des valeurs > 30 mg/g étant déjà pathologiques.","src":"p. 93-94"},{"id":"224-qru-102","type":"QRU","rank":"A","objective":"224-obj-06","tags":["imagerie"],"difficulty":1,"stem":"Quel seuil de masse ventriculaire gauche échographique définit l'hypertrophie ventriculaire gauche chez l'homme ?","options":[{"t":"> 95 g/m²","ok":false,"why":"Ce seuil est celui retenu chez la femme."},{"t":"> 105 g/m²","ok":false,"why":"Ce chiffre ne correspond pas au seuil cité dans le chapitre."},{"t":"> 115 g/m²","ok":true,"why":"Le seuil d'HVG échographique chez l'homme est une masse VG > 115 g/m²."},{"t":"> 135 g/m²","ok":false,"why":"Ce chiffre est supérieur au seuil retenu."},{"t":"> 150 g/m²","ok":false,"why":"Ce chiffre est trop élevé par rapport au seuil du chapitre."}],"explanation":"L'HVG échographique est définie par une masse VG > 115 g/m² chez l'homme et > 95 g/m² chez la femme.","src":"p. 93"},{"id":"224-qru-103","type":"QRU","rank":"A","objective":"224-obj-14","tags":["traitement","suivi"],"difficulty":1,"stem":"En combien de temps la cible de PA doit-elle idéalement être atteinte après l'instauration du traitement ?","options":[{"t":"1 mois","ok":false,"why":"Ce délai correspond à la réévaluation après chaque adaptation, pas au délai d'atteinte de la cible."},{"t":"3 mois","ok":true,"why":"La cible de PA doit idéalement être atteinte à 3 mois de l'initiation du traitement."},{"t":"6 mois","ok":false,"why":"Ce délai est trop long par rapport à l'objectif recommandé."},{"t":"1 an","ok":false,"why":"Ce délai est très supérieur à celui recommandé."},{"t":"Il n'y a pas de délai fixé","ok":false,"why":"Un délai précis de 3 mois est bien recommandé par l'ESC 2024."}],"explanation":"Le patient est revu fréquemment (tous les mois si besoin) jusqu'à atteindre la cible, idéalement à 3 mois de l'initiation du traitement.","src":"p. 95"},{"id":"224-qru-104","type":"QRU","rank":"A","objective":"224-obj-14","tags":["traitement"],"difficulty":2,"stem":"Quelle est la cible tensionnelle générale recommandée par l'ESC 2024 chez l'hypertendu ?","options":[{"t":"PAS < 140 et PAD < 90 mmHg","ok":false,"why":"C'est le seuil définissant l'HTA, pas la cible thérapeutique recommandée."},{"t":"PAS 130-139 et PAD 80-89 mmHg","ok":false,"why":"Cette fourchette ne correspond pas à la cible générale recommandée."},{"t":"PAS 120-129 et PAD 70-79 mmHg","ok":true,"why":"C'est la cible générale recommandée, en visant si possible 120/70 mmHg."},{"t":"PAS < 100 et PAD < 60 mmHg","ok":false,"why":"Cette cible est trop basse et expose à l'hypotension."},{"t":"Il n'existe pas de cible chiffrée générale","ok":false,"why":"Une cible chiffrée précise est bien définie par l'ESC 2024."}],"explanation":"La cible générale recommandée est une PAS entre 120 et 129 mmHg et une PAD entre 70 et 79 mmHg, en visant si possible 120/70 mmHg.","src":"p. 95"},{"id":"224-qru-105","type":"QRU","rank":"B","objective":"224-obj-12","tags":["traitement","diagnostic"],"difficulty":2,"stem":"Combien de classes d'antihypertenseurs à dose optimale, dont un diurétique thiazidique, définissent une HTA résistante ?","options":[{"t":"1","ok":false,"why":"Une seule classe ne suffit pas à définir une résistance thérapeutique."},{"t":"2","ok":false,"why":"Deux classes ne suffisent pas à parler d'HTA résistante."},{"t":"3","ok":true,"why":"L'HTA résistante se définit par une PA au-dessus de la cible malgré au moins 3 classes à dose optimale, dont un thiazidique."},{"t":"4","ok":false,"why":"Ce nombre est supérieur au minimum requis pour parler d'HTA résistante."},{"t":"5","ok":false,"why":"Ce nombre est très supérieur au minimum requis."}],"explanation":"L'HTA résistante se définit par une PA supérieure à la cible malgré les MHD et au moins 3 classes médicamenteuses à dose optimale, dont un diurétique thiazidique, confirmée par AMT.","src":"p. 101-102"},{"id":"224-qroc-101","type":"QROC","rank":"A","objective":"224-obj-06","tags":["paraclinique"],"difficulty":1,"question":"Quelle formule est utilisée pour estimer le débit de filtration glomérulaire dans le bilan de l'hypertendu ?","answer":"La formule CKD-EPI.","accept":["CKD-EPI"],"keywords":["ckd-epi"],"explanation":"Le DFG est estimé par la formule CKD-EPI à partir de la créatininémie.","src":"p. 92"},{"id":"224-qroc-102","type":"QROC","rank":"A","objective":"224-obj-06","tags":["imagerie"],"difficulty":2,"question":"Dans quel grade de sévérité d'HTA le fond d'œil est-il recommandé ?","answer":"Dans l'HTA de grade 3.","accept":["grade 3"],"keywords":["grade","3"],"explanation":"Le fond d'œil est recommandé dans les HTA de grade 3, à la recherche notamment d'une rétinopathie de stade 4 évocatrice d'HTA maligne.","src":"p. 94"},{"id":"224-qroc-103","type":"QROC","rank":"A","objective":"224-obj-13","difficulty":1,"tags":["traitement"],"question":"Comment appelle-t-on le type de décision recherché à l'issue de la consultation d'annonce de l'HTA ?","answer":"Une décision médicale partagée.","accept":["décision partagée"],"keywords":["décision","partagée"],"explanation":"La consultation d'annonce vise, après recueil du point de vue du patient, une décision médicale partagée entre le médecin et son patient.","src":"p. 94"},{"id":"224-qroc-104","type":"QROC","rank":"A","objective":"224-obj-14","difficulty":1,"tags":["traitement"],"question":"Quelles sont les cinq classes thérapeutiques ayant démontré leur efficacité sur la morbi-mortalité cardiovasculaire de l'HTA ?","answer":"Inhibiteurs calciques, IEC, ARA2, bêtabloquants, diurétiques thiazidiques (ou apparentés).","accept":["IC, IEC, ARA2, BB, thiazidiques"],"keywords":["calciques","iec","ara2","bêtabloquants","thiazidiques"],"explanation":"Cinq classes ont démontré leur efficacité : inhibiteurs calciques, IEC, ARA2, bêtabloquants et diurétiques thiazidiques ou apparentés.","src":"p. 96"},{"id":"224-qroc-105","type":"QROC","rank":"A","objective":"224-obj-14","difficulty":2,"tags":["traitement","pièges"],"question":"Quelle association médicamenteuse de deux bloqueurs du système rénine-angiotensine est formellement proscrite dans l'HTA ?","answer":"L'association d'un IEC et d'un ARA2.","accept":["IEC + ARA2"],"keywords":["iec","ara2"],"explanation":"Il ne faut jamais associer un IEC et un ARA2 chez un même patient hypertendu.","src":"p. 97"},{"id":"224-qroc-106","type":"QROC","rank":"A","objective":"224-obj-15","difficulty":1,"tags":["traitement"],"question":"Quel effet indésirable est caractéristique des inhibiteurs de l'enzyme de conversion et le plus souvent absent sous ARA2 ?","answer":"La toux.","accept":["toux sèche"],"keywords":["toux"],"explanation":"La toux est l'effet indésirable typique des IEC, généralement absent sous ARA2.","src":"p. 100"},{"id":"224-qroc-107","type":"QROC","rank":"A","objective":"224-obj-14","difficulty":2,"tags":["traitement","suivi"],"question":"Quel contrôle biologique doit être réalisé après toute introduction ou adaptation posologique d'un IEC/ARA2 ou d'un diurétique ?","answer":"Un ionogramme sanguin et un contrôle de la fonction rénale (créatininémie, DFG estimé).","accept":["ionogramme et créatininémie"],"keywords":["ionogramme","créatininémie"],"explanation":"Après toute introduction ou modification de dose d'IEC/ARA2 ou de diurétique, il faut réévaluer le ionogramme sanguin et la fonction rénale.","src":"p. 100"},{"id":"224-qroc-108","type":"QROC","rank":"A","objective":"224-obj-19","difficulty":2,"tags":["suivi"],"question":"Chez un patient hypertendu contrôlé à faible risque et de grade 1, à quel rythme les consultations de suivi sont-elles recommandées ?","answer":"Tous les 6 mois.","accept":["consultation semestrielle"],"keywords":["6","mois"],"explanation":"Chez le patient à faible risque ou de grade 1 dont la cible est atteinte, une consultation est prévue tous les 6 mois, contre 3 mois en cas de risque élevé.","src":"p. 101"},{"id":"224-qroc-109","type":"QROC","rank":"A","objective":"224-obj-19","difficulty":2,"tags":["suivi","paraclinique"],"question":"À quel rythme l'ECG de suivi est-il recommandé chez l'hypertendu contrôlé, en l'absence de cardiopathie ou de symptôme ?","answer":"Tous les 3 à 5 ans.","accept":["3-5 ans"],"keywords":["3","5","ans"],"explanation":"En l'absence de cardiopathie sous-jacente ou de symptôme cardiaque, l'ECG de suivi est réalisé tous les 3 à 5 ans.","src":"p. 101"},{"id":"224-qroc-110","type":"QROC","rank":"B","objective":"224-obj-12","difficulty":2,"tags":["diagnostic","traitement"],"question":"Quelle classe médicamenteuse doit obligatoirement faire partie de la trithérapie pour pouvoir parler d'HTA résistante ?","answer":"Un diurétique thiazidique (ou apparenté).","accept":["diurétique thiazidique"],"keywords":["thiazidique"],"explanation":"On ne peut évoquer une HTA résistante que chez un patient traité par un diurétique thiazidique ou apparenté, en plus des deux autres classes.","src":"p. 101"},{"id":"224-qroc-111","type":"QROC","rank":"B","objective":"224-obj-12","difficulty":2,"tags":["traitement"],"question":"Quelle classe médicamenteuse est ajoutée en 1re intention à la trithérapie optimale en cas d'HTA résistante vraie ?","answer":"Un antagoniste des récepteurs minéralocorticoïdes, la spironolactone.","accept":["spironolactone","ARM"],"keywords":["spironolactone"],"explanation":"En l'absence de cause curable, on ajoute à la trithérapie un antagoniste des récepteurs minéralocorticoïdes, la spironolactone en 1re intention (éplérénone si intolérance).","src":"p. 102"},{"id":"224-qroc-112","type":"QROC","rank":"A","objective":"224-obj-08","difficulty":2,"tags":["étiologie","diagnostic"],"question":"Citer deux circonstances, autres que l'hypokaliémie, imposant de dépister une HTA secondaire.","answer":"HTA sévère (> 180/110 mmHg) brutale ou s'aggravant rapidement, et HTA résistante (ou âge < 40 ans).","accept":["HTA sévère et résistante","grade 3 et âge jeune"],"keywords":["résistante","sévère"],"explanation":"Le dépistage d'une HTA secondaire est justifié devant une HTA sévère d'apparition brutale ou s'aggravant, une HTA résistante, un âge inférieur à 40 ans, une hypokaliémie, ou tout autre point d'appel.","src":"p. 102"},{"id":"224-open-11","type":"OPEN","rank":"A","objective":"224-obj-14","difficulty":2,"tags":["traitement"],"src":"p. 96-98","prompt":"Une HTA est confirmée chez une femme de 58 ans sans comorbidité particulière ni contre-indication médicamenteuse connue. Décrivez la stratégie d'initiation du traitement pharmacologique recommandée, en justifiant vos choix de classes.","rubric":[{"point":"Indiquer que la bithérapie d'emblée, à faible dose et en association fixe, est recommandée pour la majorité des patients","weight":2},{"point":"Préciser la monoprise quotidienne avec molécules à demi-vie longue","weight":1},{"point":"Citer les deux associations privilégiées : IEC/ARA2 + IC dihydropyridine, ou IEC/ARA2 + thiazidique","weight":3},{"point":"Rappeler que l'association IEC + ARA2 est proscrite","weight":2},{"point":"Préciser que les bêtabloquants ne sont utilisés à l'initiation qu'en présence d'une autre indication","weight":2}],"model":"Chez cette patiente sans comorbidité ni contre-indication, il est recommandé de débuter d'emblée par une bithérapie à faible dose, sous forme d'association fixe en un seul comprimé, en monoprise quotidienne avec des molécules à demi-vie longue. Le traitement associe deux des classes suivantes : IEC, ARA2, inhibiteur calcique ou diurétique thiazidique. En pratique, on privilégie soit un IEC ou un ARA2 associé à un inhibiteur calcique dihydropyridine, soit un IEC ou un ARA2 associé à un diurétique thiazidique, en n'associant jamais IEC et ARA2 entre eux. Les bêtabloquants ne sont pas utilisés à l'initiation, sauf s'il existe une autre indication à leur prescription."},{"id":"224-open-12","type":"OPEN","rank":"A","objective":"224-obj-17","difficulty":2,"tags":["traitement","suivi"],"src":"p. 99-100","prompt":"Un patient de 88 ans hypertendu, présentant une fragilité gériatrique modérée, doit voir son traitement adapté. Décrivez les principes de l'adaptation thérapeutique recommandée chez ce patient.","rubric":[{"point":"Rappeler que l'âge seul ne suffit pas et qu'il faut rechercher fragilité et espérance de vie limitée","weight":2},{"point":"Indiquer l'initiation en monothérapie","weight":2},{"point":"Citer les classes privilégiées : IC dihydropyridines et/ou IEC/ARA2, puis thiazidique à faible dose en 2e intention","weight":2},{"point":"Préciser d'éviter les bêtabloquants et les alphabloquants","weight":2},{"point":"Indiquer de ne pas dépasser une trithérapie et d'individualiser la cible sans hypotension orthostatique","weight":2}],"model":"Chez ce patient de 88 ans avec fragilité modérée, la prise en charge doit être adaptée : au moins un critère (âge > 85 ans, fragilité modérée/sévère ou espérance de vie limitée) impose de modifier la stratégie habituelle. Le traitement est initié en monothérapie, en privilégiant un inhibiteur calcique dihydropyridine et/ou un IEC/ARA2 en 1re intention, un diurétique thiazidique à faible dose pouvant être ajouté en 2e intention. Les bêtabloquants et les alphabloquants sont évités sauf indication formelle. On ne dépasse pas une trithérapie, et la cible tensionnelle est individualisée selon la tolérance clinique et paraclinique, le patient devant rester exempt d'hypotension orthostatique à cette cible."},{"id":"224-open-13","type":"OPEN","rank":"B","objective":"224-obj-12","difficulty":3,"tags":["traitement","diagnostic"],"src":"p. 101-102","prompt":"Un patient reste au-dessus de sa cible tensionnelle malgré une trithérapie associant IEC, inhibiteur calcique et diurétique thiazidique à doses optimales, avec une bonne observance rapportée. Décrivez la démarche diagnostique et thérapeutique à conduire.","rubric":[{"point":"Confirmer le déséquilibre tensionnel par AMT ou MAPA","weight":2},{"point":"Réévaluer l'observance et la tolérance réelles du traitement","weight":1},{"point":"Éliminer une fausse résistance (blouse blanche, brassard inadapté, MHD non suivies)","weight":2},{"point":"Rechercher des facteurs de résistance (sel, poids, alcool, médicaments hypertensiogènes, SAOS, HTA secondaire méconnue)","weight":2},{"point":"Poser le diagnostic d'HTA résistante et proposer l'avis spécialisé puis l'ajout d'un ARM (spironolactone)","weight":3}],"model":"La première étape consiste à confirmer le déséquilibre tensionnel par une AMT, voire une MAPA. Il faut ensuite réévaluer l'observance réelle et la tolérance du traitement, et éliminer une fausse résistance : effet blouse blanche, brassard inadapté, mesures hygiénodiététiques mal suivies (sel, poids, alcool). Une fois ces éléments écartés, on recherche des facteurs de résistance : substances hypertensiogènes, syndrome d'apnées du sommeil, HTA secondaire méconnue, surcharge volémique. Si la trithérapie est confirmée optimale (IEC/ARA2 + inhibiteur calcique + thiazidique à doses optimales) et qu'aucune cause curable n'est retrouvée, il s'agit d'une HTA résistante, justifiant un avis spécialisé et l'ajout d'un antagoniste des récepteurs minéralocorticoïdes, la spironolactone en 1re intention."},{"id":"224-open-14","type":"OPEN","rank":"A","objective":"224-obj-06","difficulty":2,"tags":["paraclinique","diagnostic"],"src":"p. 92-94","prompt":"Détaillez le bilan systématique à réaliser chez tout patient chez qui une HTA vient d'être confirmée, en précisant son objectif général.","rubric":[{"point":"Préciser l'objectif : dépister d'autres FDR CV, une atteinte infraclinique et des arguments pour une HTA secondaire","weight":2},{"point":"Citer le bilan biologique : glycémie à jeun, HbA1c, bilan lipidique, natrémie, kaliémie","weight":3},{"point":"Citer hémoglobine/hématocrite, créatininémie avec DFG (CKD-EPI), rapport protéinurie/créatininurie","weight":3},{"point":"Citer l'ECG de repos systématique","weight":1},{"point":"Préciser que les autres examens (échographie, fond d'œil, IPS…) ne sont demandés que selon le contexte","weight":1}],"model":"Le bilan systématique vise à rechercher d'autres facteurs de risque cardiovasculaire, une atteinte infraclinique des organes cibles et des arguments pour une HTA secondaire. Il comprend une glycémie à jeun et une HbA1c, un bilan lipidique complet (cholestérol total, HDL-C, triglycérides, LDL-C calculé), une natrémie et une kaliémie, un dosage de l'hémoglobine et de l'hématocrite, une créatininémie avec estimation du DFG par la formule CKD-EPI, un rapport protéinurie/créatininurie sur échantillon urinaire, et un ECG de repos. Les autres examens (échocardiographie, IPS et échodoppler, fond d'œil, β-hCG) ne sont demandés qu'en fonction du contexte clinique, lorsqu'ils sont susceptibles de modifier la prise en charge."},{"id":"224-qcm-201","type":"QRM","rank":"A","objective":"224-obj-09","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Une femme de 34 ans, hypertendue, présente à l'échographie abdominale des reins augmentés de volume truffés de kystes bilatéraux. Parmi les propositions suivantes, lesquelles sont exactes ?","options":[{"t":"Il s'agit d'une polykystose rénale, l'une des causes rénales les plus fréquentes d'HTA secondaire","ok":true,"why":"Avec les glomérulopathies chroniques, la polykystose rénale est citée comme cause rénale la plus fréquente d'HTA secondaire."},{"t":"Ce diagnostic est classiquement évoqué chez l'adolescent ou l'adulte jeune","ok":true,"why":"Le diagnostic de polykystose est évoqué devant une HTA de l'adolescent ou de l'adulte jeune."},{"t":"La présence d'une protéinurie ou d'une hématurie oriente vers ce diagnostic","ok":true,"why":"Une protéinurie, une hématurie et une insuffisance rénale orientent vers le diagnostic de néphropathie parenchymateuse."},{"t":"Le scanner abdominal injecté est l'examen de première intention pour ce diagnostic","ok":false,"why":"C'est l'échographie abdominale qui mesure la taille des reins, leur contour et recherche un obstacle, pas le scanner injecté en première intention."},{"t":"La prise en charge dépend uniquement de l'introduction d'un traitement antihypertenseur","ok":false,"why":"La prise en charge est adaptée au diagnostic précis de la néphropathie, pas seulement au traitement antihypertenseur."}],"explanation":"La polykystose rénale et les glomérulopathies chroniques sont les causes rénales parenchymateuses les plus fréquentes d'HTA secondaire. Elles sont évoquées chez le sujet jeune, avec des masses abdominales bilatérales à la palpation pour la polykystose, une protéinurie, une hématurie ou une insuffisance rénale à l'examen. L'échographie abdominale précise la morphologie rénale.","trap":"Le scanner injecté n'est pas l'examen de première intention devant une suspicion de néphropathie parenchymateuse : c'est l'échographie.","src":"p. 103"},{"id":"224-qcm-202","type":"QRM","rank":"B","objective":"224-obj-08","tags":["diagnostic","clinique"],"difficulty":3,"stem":"Un homme de 60 ans, hypertendu et polyathéromateux, développe un œdème aigu pulmonaire récidivant malgré une fonction ventriculaire gauche normale. Quels éléments, s'ils sont présents, orientent vers une HTA rénovasculaire ?","options":[{"t":"Un souffle abdominal latéralisé à l'auscultation","ok":true,"why":"Le diagnostic d'HTA rénovasculaire est évoqué devant un souffle abdominal latéralisé."},{"t":"Un œdème aigu pulmonaire récidivant sans cause cardiaque retrouvée","ok":true,"why":"C'est l'une des circonstances cliniques évocatrices citées par le référentiel."},{"t":"Une hyperkaliémie associée à un hypoaldostéronisme","ok":false,"why":"Le référentiel décrit au contraire une hypokaliémie associée à un hyperaldostéronisme secondaire (rénine et aldostérone augmentées)."},{"t":"Une diminution de la taille du rein du côté de la sténose","ok":true,"why":"Une diminution de la taille du rein concerné par la sténose est un signe évocateur."},{"t":"Une dégradation de la fonction rénale après introduction d'un IEC ou d'un ARA2","ok":true,"why":"Une insuffisance rénale compliquant parfois l'introduction d'un IEC/ARA2 est évocatrice de sténose des artères rénales."}],"explanation":"Le diagnostic d'HTA rénovasculaire repose sur un faisceau d'arguments : souffle abdominal latéralisé, OAP récidivant sans cardiopathie, hypokaliémie avec hyperaldostéronisme secondaire, insuffisance rénale sous IEC/ARA2, et asymétrie de taille rénale. L'échodoppler et l'angioscanner confirment le diagnostic.","src":"p. 103"},{"id":"224-qcm-203","type":"QRM","rank":"A","objective":"224-obj-09","tags":["étiologie","clinique"],"difficulty":2,"stem":"Un homme de 45 ans présente des accès paroxystiques associant céphalées, sueurs profuses et palpitations, avec des chiffres tensionnels très fluctuants. Parmi les propositions suivantes concernant le phéochromocytome, lesquelles sont exactes ?","options":[{"t":"Il s'agit d'une tumeur le plus souvent bénigne de la médullosurrénale","ok":true,"why":"Le phéochromocytome est une pathologie endocrinienne tumorale rare de la médullosurrénale, le plus souvent bénigne."},{"t":"Il est associé à une HTA dans environ 70 % des cas","ok":true,"why":"Le référentiel indique une association à une HTA dans 70 % des cas."},{"t":"Il peut s'intégrer dans une néoplasie endocrinienne multiple de type 2","ok":true,"why":"La NEM2 fait partie des contextes familiaux génétiques associés au phéochromocytome."},{"t":"Le diagnostic positif repose en première intention sur le scanner surrénalien","ok":false,"why":"Le diagnostic positif repose sur le dosage des dérivés méthoxylés des catécholamines ; l'imagerie sert à localiser la tumeur, pas à poser le diagnostic."},{"t":"Il peut être révélé par une cardiomyopathie de stress","ok":true,"why":"Le référentiel cite la cardiomyopathie de stress comme mode de révélation possible."}],"explanation":"Le phéochromocytome est une tumeur médullosurrénalienne rare, le plus souvent bénigne, responsable d'une sécrétion pulsatile de catécholamines. L'HTA est permanente ou paroxystique, associée à la triade de Ménard (céphalées, sueurs, palpitations). Des contextes familiaux (NEM2, von Hippel-Lindau, neurofibromatose de type 1) doivent être recherchés.","src":"p. 103-104"},{"id":"224-qcm-204","type":"QRM","rank":"A","objective":"224-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant la prise en charge thérapeutique d'un phéochromocytome confirmé, quelles propositions sont exactes ?","options":[{"t":"Le traitement curatif repose sur l'exérèse chirurgicale de la tumeur","ok":true,"why":"Le traitement consiste en l'exérèse chirurgicale de la tumeur."},{"t":"Un traitement par alpha-bloquants est débuté à petites doses puis augmenté progressivement avant la chirurgie","ok":true,"why":"Un traitement préalable par alpha-bloquants débutés à petites doses puis augmentés progressivement est recommandé."},{"t":"Des bêta-bloquants sont associés aux alpha-bloquants avant la chirurgie","ok":true,"why":"Les bêta-bloquants sont associés aux alpha-bloquants pour limiter le risque de complications opératoires."},{"t":"Les bêta-bloquants doivent toujours être introduits avant les alpha-bloquants","ok":false,"why":"C'est l'inverse : les alpha-bloquants sont débutés en premier, puis associés aux bêta-bloquants."},{"t":"Cette préparation vise à limiter le risque de poussée hypertensive et d'hypotension par déplétion volémique peropératoires","ok":true,"why":"La préparation médicamenteuse limite le risque de poussée hypertensive et/ou de déplétion volémique avec hypotension sévère à la chirurgie."}],"explanation":"Le traitement du phéochromocytome est chirurgical, précédé d'une préparation par alpha-bloquants à doses croissantes, complétée par des bêta-bloquants, afin de sécuriser l'intervention en limitant les à-coups tensionnels et l'hypotension liée à la déplétion volémique.","trap":"L'ordre d'introduction est essentiel : alpha-bloquant d'abord, bêta-bloquant ensuite, jamais l'inverse (risque de poussée hypertensive sur effet alpha non antagonisé).","src":"p. 104"},{"id":"224-qcm-205","type":"QRM","rank":"B","objective":"224-obj-09","tags":["étiologie","biologie","diagnostic"],"difficulty":3,"stem":"Chez un patient hypertendu, on suspecte un hyperaldostéronisme primaire (syndrome de Conn). Parmi les propositions suivantes, lesquelles sont exactes ?","options":[{"t":"Une hypokaliémie inférieure à 3,7 mmol/L est constamment retrouvée","ok":false,"why":"L'hypokaliémie est évocatrice mais n'est pas systématiquement présente selon le référentiel."},{"t":"La découverte fortuite d'un nodule surrénalien chez un hypertendu doit faire évoquer le diagnostic","ok":true,"why":"La découverte fortuite d'un nodule surrénalien chez un hypertendu fait partie des situations évocatrices citées."},{"t":"La biologie retrouve typiquement une rénine plasmatique basse avec un rapport aldostérone/rénine élevé","ok":true,"why":"La biologie montre une augmentation de l'aldostéronémie, une baisse de la rénine plasmatique et un rapport aldostérone/rénine très élevé."},{"t":"Les dosages hormonaux doivent être réalisés après arrêt des IEC, des ARA2 et des diurétiques depuis au moins deux semaines","ok":true,"why":"Ces dosages doivent être réalisés après arrêt des IEC, ARA2, diurétiques et bêtabloquants depuis 2 semaines (et des antagonistes des minéralocorticoïdes depuis 6 semaines)."},{"t":"L'adénome surrénalien unilatéral est la cause la plus fréquente, devant l'hyperplasie bilatérale","ok":false,"why":"C'est l'inverse : l'hyperplasie bilatérale des surrénales représente 70 % des cas contre 30 % pour l'adénome."}],"explanation":"L'hyperaldostéronisme primaire est évoqué devant une HTA sévère, résistante, du sujet jeune, ou un nodule surrénalien fortuit ; l'hypokaliémie n'est pas constante. La biologie associe hyperaldostéronémie, rénine basse et rapport élevé, dosés dans des conditions standardisées après arrêt des traitements interférents.","trap":"L'hyperplasie bilatérale des surrénales (70 %) est plus fréquente que l'adénome de Conn unilatéral (30 %), contrairement à une idée reçue.","src":"p. 104"},{"id":"224-qcm-206","type":"QRM","rank":"A","objective":"224-obj-09","tags":["étiologie","clinique","pédiatrie"],"difficulty":1,"stem":"Un adolescent de 15 ans est hypertendu aux membres supérieurs, avec des pouls fémoraux difficilement perçus. Parmi les propositions suivantes concernant la coarctation aortique, lesquelles sont exactes ?","options":[{"t":"Elle résulte d'une fermeture anormale du canal artériel entraînant une sténose de l'isthme aortique","ok":true,"why":"La fermeture anormale du canal artériel provoque une lésion sténosante de l'aorte au niveau de l'isthme."},{"t":"Le souffle est majoré en décubitus dorsal, signe spécifique de la maladie","ok":false,"why":"Ce critère positionnel n'est pas décrit par le référentiel ; le souffle typique est mésosystolique, parasternal gauche et irradiant dans le dos."},{"t":"La pression artérielle est habituellement basse aux membres inférieurs par rapport aux membres supérieurs","ok":true,"why":"Le référentiel décrit une HTA aux membres supérieurs associée à une PA basse aux membres inférieurs."},{"t":"L'artériographie systématique est l'examen qui confirme le diagnostic","ok":false,"why":"Le diagnostic est confirmé par l'échocardiographie et l'IRM, pas par une artériographie systématique."},{"t":"Le traitement repose exclusivement sur les antihypertenseurs, à vie","ok":false,"why":"Le traitement est chirurgical ou endoluminal (dilatation avec pose d'endoprothèse), pas uniquement médicamenteux."}],"explanation":"La coarctation aortique touche l'enfant et l'adulte jeune. Elle associe souffle mésosystolique parasternal gauche irradiant dans le dos, abolition des pouls fémoraux et gradient tensionnel entre membres supérieurs (élevés) et inférieurs (bas). Le diagnostic est échocardiographique et IRM, le traitement chirurgical ou endoluminal.","src":"p. 104-105"},{"id":"224-qcm-207","type":"QRM","rank":"A","objective":"224-obj-09","tags":["étiologie","pièges"],"difficulty":1,"stem":"Parmi les médicaments ou substances suivants, lesquels sont cités comme pouvant induire ou aggraver une HTA par une action vasopressive directe ?","options":[{"t":"Les corticoïdes","ok":true,"why":"Les corticoïdes figurent dans la liste des substances à action vasopressive."},{"t":"La réglisse","ok":true,"why":"La réglisse figure dans la liste des substances à action vasopressive."},{"t":"Les contraceptifs oraux","ok":true,"why":"Les contraceptifs oraux figurent dans la liste des substances à action vasopressive."},{"t":"Les inhibiteurs calciques","ok":false,"why":"Les inhibiteurs calciques sont des antihypertenseurs, pas des substances vasopressives."},{"t":"La ciclosporine","ok":true,"why":"La ciclosporine (et le tacrolimus) figurent dans la liste des substances à action vasopressive."}],"explanation":"Le référentiel liste plusieurs médicaments ou substances vasopresseurs à rechercher devant une HTA mal contrôlée : antiangiogéniques, alcool, ciclosporine/tacrolimus, cocaïne et amphétamines, contraceptifs oraux, corticoïdes, érythropoïétine, réglisse, sympathomimétiques, entre autres.","trap":"Ne pas confondre avec les classes antihypertensives elles-mêmes : les inhibiteurs calciques abaissent la PA, ils ne l'augmentent pas.","src":"p. 105"},{"id":"224-qcm-208","type":"QRM","rank":"B","objective":"224-obj-09","tags":["pièges","traitement"],"difficulty":2,"stem":"Parmi les propositions suivantes, lesquelles concernent des médicaments ou substances pouvant interférer avec le métabolisme ou l'action des traitements antihypertenseurs ?","options":[{"t":"Les anti-inflammatoires non stéroïdiens (AINS)","ok":true,"why":"Les AINS figurent parmi les médicaments interférant avec le métabolisme et/ou l'action des antihypertenseurs."},{"t":"La nicardipine, même en cas d'insuffisance cardiaque","ok":false,"why":"La nicardipine est elle-même un antihypertenseur, contre-indiqué en cas d'insuffisance cardiaque ; elle n'est pas une substance interférente."},{"t":"Les antirétroviraux","ok":false,"why":"Les antirétroviraux ne figurent pas dans cette liste précise du référentiel pour ce chunk (piège de distracteur plausible mais non cité ici) ; seuls AINS, jus de pamplemousse, macrolides et antifongiques azolés sont mentionnés dans ce paragraphe."},{"t":"Le jus de pamplemousse (inhibiteur du CYP17A1)","ok":true,"why":"Le jus de pamplemousse est cité comme inhibiteur de CYP17A1 interférant avec les traitements."},{"t":"Les antifongiques azolés","ok":true,"why":"Les antifongiques azolés sont cités comme inhibiteurs de CYP17A1 interférant avec les traitements."}],"explanation":"Les AINS, les inhibiteurs du CYP17A1 (jus de pamplemousse, macrolides, antifongiques azolés) peuvent interférer avec le métabolisme ou l'action des antihypertenseurs et doivent être recherchés devant une HTA mal contrôlée.","src":"p. 105"},{"id":"224-qcm-209","type":"QRM","rank":"A","objective":"224-obj-11","tags":["urgence"],"difficulty":2,"stem":"Parmi les situations suivantes, lesquelles constituent une urgence hypertensive selon le référentiel ?","options":[{"t":"Une HTA associée à une dissection aortique","ok":true,"why":"La dissection aortique fait partie des principales urgences hypertensives listées."},{"t":"Une HTA avec œdème aigu du poumon","ok":true,"why":"L'insuffisance ventriculaire gauche (OAP hypertensif) fait partie des principales urgences hypertensives."},{"t":"Une HTA de grade 3 isolée, sans atteinte viscérale","ok":false,"why":"Il s'agit alors d'une simple crise hypertensive, qui n'est pas une urgence par définition."},{"t":"Une prééclampsie sévère nécessitant une extraction fœtale en urgence","ok":true,"why":"La prééclampsie sévère ou l'éclampsie figurent parmi les urgences hypertensives listées."},{"t":"Une HTA blouse blanche découverte en MAPA","ok":false,"why":"L'HTA blouse blanche n'est pas une urgence hypertensive, c'est un artefact de mesure au cabinet."}],"explanation":"L'urgence hypertensive associe une HTA sévère à une atteinte aiguë d'un organe cible engageant le pronostic vital (SCA, OAP, dissection aortique, encéphalopathie hypertensive, PRES, AVC/hémorragie méningée, phéochromocytome, causes toxiques, prééclampsie sévère/éclampsie). Une HTA de grade 3 isolée sans souffrance viscérale est une crise hypertensive, non une urgence.","trap":"Ne pas confondre urgence hypertensive et crise hypertensive : seule l'atteinte aiguë d'un organe cible définit l'urgence.","src":"p. 106"},{"id":"224-qcm-210","type":"QRM","rank":"A","objective":"224-obj-11","tags":["paraclinique","urgence"],"difficulty":2,"stem":"Devant une urgence hypertensive, quels examens complémentaires, à adapter au contexte clinique, sont pertinents ?","options":[{"t":"Un fond d'œil, à la recherche d'une occlusion de la veine centrale de la rétine ou d'une rétinopathie stade 4","ok":true,"why":"Le fond d'œil recherche une occlusion de la veine centrale de la rétine ou une rétinopathie stade 4."},{"t":"Un dosage systématique de la CRP en première intention","ok":false,"why":"La CRP ne figure pas dans la liste des examens cités par le référentiel pour l'urgence hypertensive."},{"t":"Un scanner cérébral en cas de suspicion d'hémorragie ou d'AVC","ok":true,"why":"Le scanner cérébral est indiqué en cas de suspicion d'hémorragie ou d'AVC."},{"t":"Une IRM médullaire systématique","ok":false,"why":"Cet examen n'est pas cité dans le bilan de l'urgence hypertensive."},{"t":"Une échocardiographie à la recherche d'un trouble de cinétique ou de pressions de remplissage élevées","ok":true,"why":"L'échocardiographie évalue la fonction systolique et diastolique et recherche un trouble de cinétique."}],"explanation":"Le bilan d'une urgence hypertensive est adapté à l'organe cible suspecté : biologie (créatinine, protéinurie, plaquettes, coagulation, troponine, toxiques), ECG, radiographie thoracique, échocardiographie, fond d'œil, scanner cérébral (point d'appel neurologique) et imagerie aortique (suspicion de dissection).","src":"p. 106"},{"id":"224-qcm-211","type":"QRM","rank":"A","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":2,"stem":"Concernant les objectifs tensionnels dans la prise en charge générale d'une urgence hypertensive (hors dissection aortique et cas particuliers neurovasculaires), quelles propositions sont exactes ?","options":[{"t":"L'objectif est une baisse de la PA de 20 à 25 % en 2 heures","ok":true,"why":"Le traitement vise une baisse de la PA de 20 à 25 % en 2 heures."},{"t":"La cible est d'environ 160/110 mmHg atteinte en 2 à 6 heures","ok":true,"why":"La cible générale est d'atteindre 160/110 mmHg dans les 2 à 6 heures."},{"t":"Il faut normaliser la PA en dessous de 130/80 mmHg dès la première heure","ok":false,"why":"Une normalisation trop rapide est au contraire déconseillée, car elle expose à une hypoperfusion d'organe."},{"t":"Une baisse trop rapide de la PA expose à un risque d'aggravation cérébrale, rénale ou cardiaque","ok":true,"why":"Les anomalies de l'autorégulation chez l'hypertendu exposent, en cas de baisse trop rapide, à une hypoperfusion cérébrale, une ischémie myocardique ou rénale."},{"t":"La surveillance de la PA doit être réalisée toutes les 15 minutes","ok":true,"why":"La surveillance de la PA toutes les 15 minutes fait partie de la prise en charge en unité de soins intensifs."}],"explanation":"Hors dissection aortique, la baisse tensionnelle dans l'urgence hypertensive doit être progressive : 20-25 % en 2 heures, cible de 160/110 mmHg en 2 à 6 heures, sous surveillance rapprochée en soins intensifs ou réanimation, pour éviter une hypoperfusion d'organe.","src":"p. 106"},{"id":"224-qcm-212","type":"QRM","rank":"A","objective":"224-obj-18","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant les traitements antihypertenseurs intraveineux utilisés dans l'urgence hypertensive, quelles propositions sont exactes ?","options":[{"t":"L'urapidil (alphabloquant) est utilisé en première intention dans le cas général","ok":true,"why":"L'urapidil IV est prescrit en première intention dans le cas général."},{"t":"La nicardipine peut être utilisée même en cas d'insuffisance cardiaque","ok":false,"why":"La nicardipine est au contraire contre-indiquée en cas d'insuffisance cardiaque."},{"t":"Les diurétiques de l'anse sont le traitement de première intention du syndrome coronarien aigu hypertensif","ok":false,"why":"Ce sont les dérivés nitrés IV qui sont utilisés en première intention dans les SCA ou l'OAP, pas les diurétiques de l'anse."},{"t":"Le labétalol IV est utilisé en première intention en cas de phéochromocytome","ok":true,"why":"Dans le phéochromocytome, le labétalol IV (alpha et bêtabloquant) est employé."},{"t":"Les diurétiques thiazidiques oraux sont le traitement de référence de l'urgence hypertensive","ok":false,"why":"Les diurétiques thiazidiques oraux relèvent du traitement de fond de l'HTA chronique, pas de l'urgence hypertensive qui nécessite un traitement IV."}],"explanation":"Le traitement IV de l'urgence hypertensive repose en première intention sur l'urapidil et/ou un inhibiteur calcique IV comme la nicardipine (contre-indiquée en cas d'insuffisance cardiaque), avec des situations particulières : labétalol dans le phéochromocytome, dérivés nitrés dans le SCA ou l'OAP.","trap":"La nicardipine est contre-indiquée dans l'insuffisance cardiaque : un piège classique consiste à la proposer chez un patient en OAP.","src":"p. 106-107"},{"id":"224-qcm-213","type":"QRM","rank":"B","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":3,"stem":"Chez un patient traité par thrombolyse intraveineuse pour un AVC ischémique aigu, quels objectifs de pression artérielle doivent être respectés ?","options":[{"t":"PA < 185/110 mmHg avant le traitement","ok":true,"why":"Il faut abaisser la PA en dessous de 185/110 mmHg avant la thrombolyse IV."},{"t":"PA < 180/105 mmHg maintenue pendant les 24 heures suivant le traitement","ok":true,"why":"Cette cible doit être maintenue pendant 24 heures après la thrombolyse."},{"t":"Aucune limite de PA n'est requise avant de débuter la thrombolyse","ok":false,"why":"Au contraire, un seuil précis (< 185/110 mmHg) doit être atteint avant le traitement thrombolytique."},{"t":"La cible est identique à celle de la dissection aortique (PAS < 120 mmHg)","ok":false,"why":"La cible de la dissection aortique est spécifique et plus stricte, elle ne s'applique pas à l'AVC thrombolysé."},{"t":"La réduction active de la PA n'est jamais recommandée dans ce contexte","ok":false,"why":"À l'inverse, des objectifs de PA plus bas sont nécessaires chez les patients traités par thrombolyse ou thrombectomie, pour prévenir les complications de reperfusion."}],"explanation":"Chez les patients traités par thrombolyse IV (ou thrombectomie mécanique), des objectifs tensionnels plus stricts sont requis : PA < 185/110 mmHg avant le traitement, puis < 180/105 mmHg maintenue pendant 24 heures, afin de prévenir les complications hémorragiques de reperfusion.","src":"p. 107"},{"id":"224-qcm-214","type":"QRM","rank":"A","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":3,"stem":"Concernant la prise en charge tensionnelle d'une hémorragie intracérébrale, quelles propositions sont exactes selon le référentiel ?","options":[{"t":"Une baisse de la PA est envisagée dans les 6 heures suivant l'apparition des symptômes","ok":true,"why":"Une baisse immédiate de la PA dans les 6 heures suivant les symptômes doit être envisagée."},{"t":"La cible est une PA systolique comprise entre 140 et 160 mmHg","ok":true,"why":"La valeur cible systolique retenue est de 140-160 mmHg."},{"t":"Les diminutions aiguës de la PA systolique de plus de 70 mmHg doivent être évitées","ok":true,"why":"Des diminutions aiguës excessives de la PAS (> 70 mmHg) peuvent être associées à des lésions rénales aiguës et une détérioration neurologique et doivent être évitées."},{"t":"Cette baisse tensionnelle n'apporte aucun bénéfice démontré","ok":false,"why":"Elle vise au contraire à prévenir l'expansion de l'hématome et à améliorer les résultats fonctionnels."},{"t":"Aucune cible tensionnelle spécifique n'est proposée dans ce contexte","ok":false,"why":"Une cible précise (PAS 140-160 mmHg) est au contraire recommandée."}],"explanation":"En cas d'hémorragie intracérébrale, une baisse précoce (dans les 6 heures) de la PA systolique vers 140-160 mmHg est recommandée pour limiter l'expansion de l'hématome, en évitant toutefois les baisses brutales de plus de 70 mmHg de PAS, délétères sur le plan rénal et neurologique.","src":"p. 107"},{"id":"224-qcm-215","type":"QRM","rank":"A","objective":"224-obj-11","tags":["complications","urgence"],"difficulty":2,"stem":"Parmi les manifestations suivantes, lesquelles peuvent compliquer une HTA maligne ?","options":[{"t":"Une anémie hémolytique mécanique avec thrombopénie","ok":true,"why":"La microangiopathie thrombotique (anémie hémolytique mécanique, thrombopénie) fait partie des complications possibles de l'HTA maligne."},{"t":"Une insuffisance rénale aiguë avec protéinurie abondante","ok":true,"why":"L'atteinte rénale aiguë avec créatininémie élevée, protéinurie abondante et hématurie fréquente est citée."},{"t":"Une hypokaliémie constante et sévère","ok":false,"why":"L'hypokaliémie n'est pas décrite comme un signe constitutif de l'HTA maligne dans ce paragraphe (elle est plutôt évocatrice d'une cause endocrinienne comme le Conn)."},{"t":"Un syndrome d'encéphalopathie postérieure réversible (PRES) ou une encéphalopathie hypertensive","ok":true,"why":"Les atteintes neurologiques (PRES, encéphalopathie hypertensive, coma) sont citées parmi les complications."},{"t":"Un œdème papillaire (rétinopathie stade 4) au fond d'œil","ok":true,"why":"Le diagnostic d'HTA maligne repose notamment sur un œdème papillaire au fond d'œil (stade 4)."}],"explanation":"L'HTA maligne associe une PA élevée à un œdème papillaire (fond d'œil stade 4) et peut se compliquer d'atteintes cardiaques, rénales, neurologiques et d'une microangiopathie thrombotique. Son évolution spontanée conduit en quelques mois à une insuffisance rénale sévère et mortelle.","src":"p. 107"},{"id":"224-qru-201","type":"QRU","rank":"A","objective":"224-obj-09","tags":["étiologie"],"difficulty":1,"stem":"Laquelle de ces causes d'HTA rénovasculaire touche préférentiellement l'ostium et le tiers proximal de l'artère rénale, chez un patient porteur d'autres localisations athéromateuses ?","options":[{"t":"La dysplasie fibromusculaire","ok":false,"why":"La dysplasie fibromusculaire touche plutôt la femme jeune et les deux tiers distaux de l'artère."},{"t":"La sténose des artères rénales d'origine athéromateuse","ok":true,"why":"Les sténoses athéromateuses, les plus fréquentes, touchent l'ostium et le tiers proximal de l'artère rénale."},{"t":"La glomérulopathie chronique","ok":false,"why":"Il s'agit d'une atteinte parenchymateuse diffuse, pas d'une sténose artérielle."},{"t":"Le phéochromocytome","ok":false,"why":"C'est une tumeur sécrétante de la médullosurrénale, sans rapport avec une sténose artérielle rénale."},{"t":"La coarctation aortique","ok":false,"why":"Il s'agit d'une sténose de l'isthme aortique, pas des artères rénales."}],"explanation":"Les deux causes principales d'HTA rénovasculaire sont la sténose athéromateuse (ostium/tiers proximal, sujet avec athérome diffus) et la dysplasie fibromusculaire (femme jeune, deux tiers distaux de l'artère).","src":"p. 103"},{"id":"224-qru-202","type":"QRU","rank":"A","objective":"224-obj-09","tags":["paraclinique","diagnostic"],"difficulty":1,"stem":"Quel dosage biologique permet le diagnostic positif d'un phéochromocytome ?","options":[{"t":"Le dosage urinaire et/ou sanguin des dérivés méthoxylés des catécholamines","ok":true,"why":"Le diagnostic est posé sur le dosage des dérivés méthoxylés des catécholamines (métanéphrines, normétanéphrines)."},{"t":"Le rapport aldostérone/rénine","ok":false,"why":"Ce dosage est utilisé pour le diagnostic d'hyperaldostéronisme primaire, pas de phéochromocytome."},{"t":"Le cortisol libre urinaire","ok":false,"why":"Ce dosage oriente vers un syndrome de Cushing, pas vers un phéochromocytome."},{"t":"La scintigraphie à la MIBG isolée","ok":false,"why":"La scintigraphie à la MIBG sert à localiser la tumeur et confirmer sa nature fonctionnelle, mais n'est pas le dosage diagnostique de première intention."},{"t":"La rénine plasmatique seule","ok":false,"why":"Ce dosage n'est pas spécifique du phéochromocytome."}],"explanation":"Le diagnostic positif du phéochromocytome repose sur le dosage urinaire et/ou sanguin des dérivés méthoxylés des catécholamines. La localisation tumorale est ensuite précisée par un scanner couplé à une scintigraphie à la MIBG.","src":"p. 104"},{"id":"224-qru-203","type":"QRU","rank":"A","objective":"224-obj-20","tags":["traitement"],"difficulty":1,"stem":"Quel traitement médicamenteux est proposé en première intention en cas d'hyperaldostéronisme primaire ne relevant pas d'une chirurgie ?","options":[{"t":"La spironolactone","ok":true,"why":"Un antagoniste des récepteurs aux minéralocorticoïdes, la spironolactone en première intention, est introduit dans les autres cas que la chirurgie."},{"t":"Un inhibiteur de l'enzyme de conversion","ok":false,"why":"L'IEC n'est pas le traitement spécifique de l'hyperaldostéronisme primaire."},{"t":"Un bêtabloquant","ok":false,"why":"Le bêtabloquant n'est pas le traitement spécifique de l'hyperaldostéronisme primaire."},{"t":"Un diurétique thiazidique","ok":false,"why":"Le diurétique thiazidique n'est pas le traitement spécifique de cette étiologie et peut aggraver l'hypokaliémie."},{"t":"Un inhibiteur calcique","ok":false,"why":"L'inhibiteur calcique n'est pas le traitement spécifique de l'hyperaldostéronisme primaire."}],"explanation":"En l'absence de lésion unilatérale opérable (ou chez un patient non candidat à la chirurgie), un antagoniste des récepteurs aux minéralocorticoïdes, la spironolactone, est le traitement médicamenteux de première intention de l'hyperaldostéronisme primaire.","src":"p. 104"},{"id":"224-qru-204","type":"QRU","rank":"A","objective":"224-obj-09","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Chez quel profil de patient hypertendu le syndrome d'apnées du sommeil doit-il être particulièrement évoqué ?","options":[{"t":"Un patient obèse, avec une HTA résistante et un profil « non dipper » en MAPA","ok":true,"why":"Le SAOS est évoqué chez les patients obèses, surtout si l'HTA est résistante, ainsi que chez les patients « non dippers » en MAPA."},{"t":"Un patient mince avec une HTA blouse blanche","ok":false,"why":"Ce profil n'est pas celui évocateur d'un SAOS."},{"t":"Un patient jeune avec une hypokaliémie isolée","ok":false,"why":"Ce profil oriente plutôt vers un hyperaldostéronisme primaire."},{"t":"Un patient avec un souffle abdominal latéralisé","ok":false,"why":"Ce signe oriente vers une HTA rénovasculaire, pas vers un SAOS."},{"t":"Un patient avec une triade céphalées-sueurs-palpitations","ok":false,"why":"Cette triade (de Ménard) oriente vers un phéochromocytome."}],"explanation":"Le syndrome d'apnées du sommeil doit être recherché chez le patient hypertendu obèse, notamment en cas d'HTA résistante ou de profil « non dipper » (absence de baisse nocturne de la PA en MAPA). Le diagnostic repose sur la polygraphie ou la polysomnographie, le traitement sur la pression positive continue nocturne.","src":"p. 105"},{"id":"224-qru-205","type":"QRU","rank":"A","objective":"224-obj-11","tags":["urgence","définition"],"difficulty":1,"stem":"Comment distingue-t-on une urgence hypertensive d'une simple crise hypertensive ?","options":[{"t":"Par la présence d'une atteinte aiguë d'un organe cible associée à l'HTA sévère","ok":true,"why":"L'urgence hypertensive se définit par une HTA sévère associée à une atteinte aiguë des organes cibles, mettant en jeu le pronostic vital ; la crise hypertensive n'a pas de souffrance viscérale."},{"t":"Par le seul niveau de la pression artérielle systolique","ok":false,"why":"Le chiffre de PA seul (même de grade 3) ne suffit pas à définir une urgence en l'absence d'atteinte viscérale."},{"t":"Par l'âge du patient","ok":false,"why":"L'âge n'intervient pas dans cette distinction."},{"t":"Par la durée d'évolution connue de l'HTA","ok":false,"why":"L'ancienneté de l'HTA n'intervient pas dans cette distinction."},{"t":"Par la présence d'une hypokaliémie associée","ok":false,"why":"L'hypokaliémie n'est pas un critère de définition de l'urgence hypertensive."}],"explanation":"La crise hypertensive correspond à une HTA de grade 3 sans souffrance viscérale : elle n'est pas une urgence. L'urgence hypertensive, elle, associe une HTA sévère à une atteinte aiguë d'un organe cible engageant le pronostic vital.","src":"p. 105-106"},{"id":"224-qru-206","type":"QRU","rank":"B","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":3,"stem":"Chez un patient présentant un AVC ischémique aigu, sans traitement de reperfusion (ni thrombolyse ni thrombectomie), à partir de quel seuil tensionnel une réduction modérée de la PA est-elle recommandée ?","options":[{"t":"PA > 220/120 mmHg","ok":true,"why":"La réduction active de la PA n'est pas recommandée sauf si elle est extrêmement élevée, supérieure à 220/120 mmHg."},{"t":"PA > 180/110 mmHg","ok":false,"why":"Ce seuil, plus bas, n'est pas celui retenu chez le patient non reperfusé."},{"t":"PA > 140/90 mmHg","ok":false,"why":"Ce seuil correspond plutôt au seuil de réintroduction d'un traitement chez un patient stable à distance de l'AVC, pas au seuil de réduction en phase aiguë."},{"t":"PA > 160/100 mmHg","ok":false,"why":"Ce seuil n'est pas celui retenu par le référentiel pour ce contexte."},{"t":"Dès que la PA dépasse 140/90 mmHg dès la phase aiguë","ok":false,"why":"Ce niveau n'impose aucune réduction active en phase aiguë chez un patient non reperfusé."}],"explanation":"Chez le patient présentant un AVC ischémique aigu sans traitement de reperfusion, la réduction active de la PA n'est pas recommandée sauf si elle est extrêmement élevée (> 220/120 mmHg), où une réduction modérée de 10-15 % sur quelques heures est alors proposée pour éviter une hypoperfusion cérébrale.","src":"p. 107"},{"id":"224-qroc-201","type":"QROC","rank":"A","objective":"224-obj-09","tags":["étiologie"],"difficulty":1,"question":"Citez les deux principales causes d'HTA rénovasculaire décrites dans le référentiel.","answer":"Sténose athéromateuse des artères rénales et dysplasie fibromusculaire.","accept":["athérome et fibrodysplasie","sténose athéromateuse et dysplasie fibromusculaire des artères rénales"],"keywords":["athéromateuse","fibromusculaire"],"explanation":"La sténose athéromateuse (sujet âgé, ostium/tiers proximal, contexte polyathéromateux) et la dysplasie fibromusculaire (femme jeune, deux tiers distaux) sont les deux causes principales d'HTA rénovasculaire.","src":"p. 103"},{"id":"224-qroc-202","type":"QROC","rank":"A","objective":"224-obj-09","tags":["paraclinique"],"difficulty":1,"question":"Quels examens d'imagerie confirment une sténose des artères rénales suspectée cliniquement ?","answer":"L'écho-Doppler des artères rénales et l'angioscanner abdominal.","accept":["échodoppler rénal et angioscanner","doppler des artères rénales + angioscanner"],"keywords":["échodoppler","angioscanner"],"explanation":"L'échodoppler des artères rénales et l'angioscanner abdominal confirment le diagnostic de sténose et en quantifient la sévérité.","src":"p. 103"},{"id":"224-qroc-203","type":"QROC","rank":"A","objective":"224-obj-09","tags":["clinique"],"difficulty":1,"question":"Quelle triade clinique classique évoque un phéochromocytome ?","answer":"Céphalées, sueurs et palpitations (triade de Ménard).","accept":["triade de ménard","céphalées-sueurs-palpitations"],"keywords":["céphalées","sueurs","palpitations"],"explanation":"L'HTA paroxystique du phéochromocytome s'accompagne classiquement de la triade de Ménard : céphalées, sueurs, palpitations.","src":"p. 104"},{"id":"224-qroc-204","type":"QROC","rank":"A","objective":"224-obj-09","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Sur quel dosage repose le diagnostic positif du phéochromocytome ?","answer":"Le dosage urinaire et/ou sanguin des dérivés méthoxylés des catécholamines (métanéphrines, normétanéphrines).","accept":["métanéphrines et normétanéphrines","dérivés méthoxylés des catécholamines"],"keywords":["métanéphrines","catécholamines"],"explanation":"Le diagnostic biologique positif repose sur le dosage des dérivés méthoxylés des catécholamines ; l'imagerie (scanner + MIBG) sert ensuite à localiser la tumeur.","src":"p. 104"},{"id":"224-qroc-205","type":"QROC","rank":"A","objective":"224-obj-09","tags":["épidémiologie","étiologie"],"difficulty":2,"question":"Quelle est la cause la plus fréquente d'hyperaldostéronisme primaire, en proportion, parmi les deux principales décrites ?","answer":"L'hyperplasie bilatérale des surrénales (environ 70 % des cas), devant l'adénome surrénalien (environ 30 %).","accept":["hyperplasie bilatérale à 70 %"],"keywords":["hyperplasie","70"],"explanation":"Contrairement à une idée reçue, l'hyperaldostéronisme primaire est dû le plus souvent à une hyperplasie bilatérale des surrénales (70 %), et non à un adénome unilatéral (30 %).","src":"p. 104"},{"id":"224-qroc-206","type":"QROC","rank":"A","objective":"224-obj-20","tags":["traitement"],"difficulty":1,"question":"Quel traitement médicamenteux de première intention est proposé dans l'hyperaldostéronisme primaire lorsqu'une chirurgie n'est pas indiquée ?","answer":"Un antagoniste des récepteurs aux minéralocorticoïdes, la spironolactone.","accept":["spironolactone"],"keywords":["spironolactone"],"explanation":"En dehors des situations relevant d'une surrénalectomie, la spironolactone est le traitement médicamenteux de première intention.","src":"p. 104"},{"id":"224-qroc-207","type":"QROC","rank":"A","objective":"224-obj-09","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Quel signe est classiquement recherché à la palpation des pouls devant une suspicion de coarctation aortique ?","answer":"L'abolition ou la diminution des pouls fémoraux.","accept":["pouls fémoraux abolis ou diminués","abolition des pouls fémoraux"],"keywords":["pouls","fémoraux"],"explanation":"L'abolition des pouls fémoraux, associée à une HTA des membres supérieurs contrastant avec une PA basse aux membres inférieurs, est très évocatrice de coarctation aortique.","src":"p. 105"},{"id":"224-qroc-208","type":"QROC","rank":"A","objective":"224-obj-20","tags":["traitement"],"difficulty":1,"question":"Par quel traitement le syndrome d'apnées du sommeil associé à une HTA est-il pris en charge ?","answer":"Un appareillage par pression positive continue (PPC) nocturne.","accept":["PPC nocturne","pression positive continue"],"keywords":["ppc","pression positive"],"explanation":"Après confirmation par polygraphie ou polysomnographie, le traitement du SAOS repose sur un appareillage par pression positive continue (PPC) nocturne.","src":"p. 105"},{"id":"224-qroc-209","type":"QROC","rank":"B","objective":"224-obj-12","tags":["définition"],"difficulty":2,"question":"Comment définit-on une HTA résistante ?","answer":"Une PA restant au-delà de la cible malgré une trithérapie antihypertensive à doses optimales incluant un diurétique.","accept":["PA non contrôlée sous trithérapie optimale avec diurétique"],"keywords":["trithérapie","diurétique","cible"],"explanation":"On parle d'HTA résistante quand la PA ne redescend pas sous la cible malgré trois classes d'antihypertenseurs bien dosées, dont un diurétique ; ce constat doit conduire à demander l'avis d'un spécialiste.","src":"p. 109"},{"id":"224-qroc-210","type":"QROC","rank":"A","objective":"224-obj-11","tags":["diagnostic"],"difficulty":1,"question":"Quel signe au fond d'œil caractérise le stade 4 de la rétinopathie hypertensive et définit, avec l'HTA, l'HTA maligne ?","answer":"L'œdème papillaire.","accept":["œdème papillaire bilatéral"],"keywords":["oedème","papillaire"],"explanation":"Le diagnostic d'HTA maligne repose sur l'association d'une PA élevée et d'un œdème papillaire au fond d'œil (stade 4).","src":"p. 107"},{"id":"224-qroc-211","type":"QROC","rank":"A","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":2,"question":"Quelle cible de pression artérielle systolique doit être atteinte le plus rapidement possible en cas de dissection aortique ?","answer":"Une PAS inférieure à 120 mmHg.","accept":["PAS < 120 mmHg"],"keywords":["120"],"explanation":"Contrairement à la cible générale plus progressive des autres urgences hypertensives, la dissection aortique impose d'atteindre une PAS inférieure à 120 mmHg le plus rapidement possible.","src":"p. 106"},{"id":"224-qroc-212","type":"QROC","rank":"A","objective":"224-obj-18","tags":["traitement","urgence"],"difficulty":1,"question":"Quels sont les deux traitements antihypertenseurs intraveineux utilisés en première intention dans le cas général d'une urgence hypertensive ?","answer":"L'urapidil (alphabloquant) et/ou un inhibiteur calcique IV comme la nicardipine.","accept":["urapidil et nicardipine"],"keywords":["urapidil","nicardipine"],"explanation":"En dehors des situations particulières (phéochromocytome, SCA/OAP, dissection), le traitement IV de première intention repose sur l'urapidil et/ou la nicardipine, cette dernière étant contre-indiquée en cas d'insuffisance cardiaque.","src":"p. 106"},{"id":"224-open-21","type":"OPEN","rank":"B","objective":"224-obj-12","tags":["définition","diagnostic","traitement"],"difficulty":3,"prompt":"Un patient de 58 ans, suivi pour HTA depuis 5 ans, est sous trithérapie à doses optimales incluant un diurétique thiazidique. Une mesure ambulatoire de PA confirme des chiffres restant à 158/96 mmHg. Décrivez votre démarche diagnostique et thérapeutique face à cette situation.","rubric":[{"point":"Reconnaître une HTA résistante (PA au-delà de la cible sous trithérapie optimale incluant un diurétique)","weight":2},{"point":"Vérifier l'observance médicamenteuse et le respect des mesures hygiénodiététiques","weight":1},{"point":"Confirmer que la mesure hors cabinet élimine bien un effet blouse blanche persistant","weight":1},{"point":"Rechercher une cause secondaire ou un facteur aggravant surajouté (médicamenteux, toxique, SAOS, endocrinien)","weight":2},{"point":"Demander un avis spécialisé, comme l'impose la définition de l'HTA résistante","weight":2},{"point":"Réévaluer et adapter le traitement (vérifier les posologies optimales, discuter un renforcement thérapeutique)","weight":1}],"model":"Cette situation correspond à une **HTA résistante** : PA restant au-delà de la cible sous trithérapie à doses optimales incluant un diurétique, confirmée hors cabinet. La démarche associe : (1) vérification de l'observance et des règles hygiénodiététiques (sel, alcool, activité physique) ; (2) recherche d'un facteur aggravant ou d'une cause secondaire surajoutée (médicaments/toxiques vasopresseurs, syndrome d'apnées du sommeil, cause endocrinienne) ; (3) avis spécialisé, imposé par la définition même de l'HTA résistante ; (4) réévaluation et optimisation du traitement antihypertenseur.","src":"p. 109"},{"id":"224-open-22","type":"OPEN","rank":"A","objective":"224-obj-18","tags":["urgence","traitement"],"difficulty":2,"prompt":"Un patient hypertendu connu se présente aux urgences avec une PA à 200/115 mmHg et un tableau d'œdème aigu du poumon. Décrivez les grandes lignes de sa prise en charge.","rubric":[{"point":"Hospitalisation en unité de soins intensifs adaptée à la souffrance viscérale, ou en réanimation","weight":2},{"point":"Surveillance rapprochée de la PA (toutes les 15 minutes)","weight":1},{"point":"Objectif tensionnel progressif : baisse de 20-25 % en 2 heures pour atteindre 160/110 mmHg en 2 à 6 heures","weight":2},{"point":"Traitement antihypertenseur IV de première intention adapté au contexte : dérivés nitrés IV dans l'OAP","weight":2},{"point":"Bilan associé (ECG, radiographie thoracique, échocardiographie, biologie)","weight":1},{"point":"Éviter une baisse trop rapide de la PA, source d'hypoperfusion d'organe","weight":1}],"model":"Il s'agit d'une **urgence hypertensive** (HTA avec atteinte aiguë d'organe cible, ici un OAP hypertensif). La prise en charge comprend : hospitalisation en soins intensifs, surveillance de la PA toutes les 15 minutes, bilan (ECG, radiographie de thorax, échocardiographie, biologie), et traitement IV de première intention par dérivés nitrés dans ce contexte d'OAP. L'objectif est une baisse progressive de 20-25 % en 2 heures, pour atteindre 160/110 mmHg en 2 à 6 heures, en évitant toute chute brutale exposant à une hypoperfusion cérébrale, myocardique ou rénale.","src":"p. 106-107"},{"id":"224-open-23","type":"OPEN","rank":"B","objective":"224-obj-09","tags":["étiologie","diagnostic","biologie"],"difficulty":3,"prompt":"Un homme de 40 ans hypertendu présente une hypokaliémie à 3,2 mmol/L découverte fortuitement sur un bilan systématique. Quelles hypothèses diagnostiques évoquez-vous parmi les causes secondaires d'HTA, et comment les explorez-vous ?","rubric":[{"point":"Évoquer un hyperaldostéronisme primaire (syndrome de Conn)","weight":2},{"point":"Évoquer une HTA rénovasculaire avec hyperaldostéronisme secondaire","weight":2},{"point":"Bilan hormonal (rénine, aldostérone, rapport aldostérone/rénine) réalisé dans des conditions standardisées, après arrêt des traitements interférents","weight":2},{"point":"Imagerie orientée : scanner surrénalien (Conn) ou échodoppler des artères rénales/angioscanner (rénovasculaire)","weight":2},{"point":"Discuter, en cas de lésion surrénalienne unilatérale et de projet chirurgical, un cathétérisme des veines surrénaliennes pour vérifier la latéralisation","weight":1}],"model":"Devant une HTA associée à une hypokaliémie, deux causes secondaires sont à évoquer en priorité : l'**hyperaldostéronisme primaire** (adénome ou hyperplasie bilatérale des surrénales) et l'**HTA rénovasculaire** (hyperaldostéronisme secondaire par activation du système rénine-angiotensine). Le bilan comprend un dosage de la rénine et de l'aldostérone (rapport aldostérone/rénine), réalisé le matin, en normokaliémie, après arrêt des traitements interférents (antagonistes des minéralocorticoïdes 6 semaines, IEC/ARA2/diurétiques/bêtabloquants 2 semaines). L'imagerie est orientée : scanner surrénalien en cas de suspicion de Conn, échodoppler des artères rénales et angioscanner en cas de suspicion rénovasculaire. Si une lésion surrénalienne unilatérale est retrouvée chez un patient candidat à la chirurgie, un cathétérisme des veines surrénaliennes confirme la latéralisation avant surrénalectomie.","src":"p. 103-104"},{"id":"224-open-24","type":"OPEN","rank":"A","objective":"224-obj-18","tags":["urgence","physiopathologie"],"difficulty":2,"prompt":"Expliquez pourquoi il faut éviter une baisse trop rapide de la pression artérielle au cours d'une urgence hypertensive, et précisez l'exception représentée par la dissection aortique.","rubric":[{"point":"Anomalies de l'autorégulation de la PA chez l'hypertendu chronique","weight":2},{"point":"Risque d'hypoperfusion cérébrale, d'ischémie myocardique ou rénale en cas de baisse trop rapide","weight":2},{"point":"Cible habituellement progressive : 20-25 % en 2 heures puis 160/110 mmHg en 2-6 heures","weight":2},{"point":"Exception de la dissection aortique : cible de PAS < 120 mmHg atteinte le plus vite possible pour limiter le risque évolutif aortique","weight":2}],"model":"Chez le patient hypertendu chronique, les mécanismes d'autorégulation de la perfusion d'organe sont déplacés vers des niveaux de PA plus élevés. Une baisse trop brutale de la PA peut alors provoquer une hypoperfusion cérébrale, une ischémie myocardique ou une ischémie rénale. C'est pourquoi la cible de l'urgence hypertensive est en général progressive (baisse de 20-25 % en 2 heures, puis 160/110 mmHg en 2 à 6 heures). La **dissection aortique** fait exception : il est au contraire impératif d'atteindre le plus rapidement possible une PAS inférieure à 120 mmHg, afin de limiter la contrainte pariétale aortique et le risque d'extension ou de rupture.","src":"p. 106"}],"edn":[{"id":"224-kfp-01","type":"KFP","rank":"A","objective":"224-obj-04","difficulty":2,"scenario":"M. R., 54 ans, sans antécédent notable, consulte pour un renouvellement d'ordonnance. La pression artérielle mesurée à trois reprises en fin de consultation, dans des conditions correctement respectées, est en moyenne de 152/94 mmHg. Il est totalement asymptomatique. Il fume 10 cigarettes par jour et son père est traité pour une hypertension artérielle depuis l'âge de 45 ans.","questions":[{"stem":"Quelle(s) démarche(s) proposez-vous en première intention pour confirmer le diagnostic d'HTA ?","max":2,"options":["Automesure tensionnelle selon la règle des 3","Mesure ambulatoire de la pression artérielle (MAPA)","Traiter d'emblée sans confirmation, la valeur étant élevée","Renouveler une seule mesure lors du prochain rendez-vous","Rechercher une hypotension orthostatique de principe","Doser les dérivés méthoxylés urinaires d'emblée","Réaliser un scanner surrénalien systématique","Proposer un dosage de rénine et d'aldostérone d'emblée"],"correct":[0,1],"explanation":"L'AMT est l'examen recommandé en 1re intention en France pour confirmer une HTA suspectée en consultation ; la MAPA est une alternative si l'AMT n'est pas réalisable."},{"stem":"Quel bilan de première intention demandez-vous une fois l'HTA confirmée ?","max":6,"options":["Glycémie à jeun et HbA1c","Bilan lipidique complet","Natrémie et kaliémie","Créatininémie avec DFG (CKD-EPI)","Rapport protéinurie/créatininurie","ECG de repos","Échocardiographie systématique","Dosage de la rénine et de l'aldostérone","Fond d'œil systématique","IRM cérébrale"],"correct":[0,1,2,3,4,5],"explanation":"Le bilan minimal systématique comprend glycémie/HbA1c, bilan lipidique, ionogramme, créatininémie avec DFG, protéinurie et ECG ; échocardiographie, fond d'œil et dosages hormonaux ne sont demandés que selon le contexte."},{"stem":"Après confirmation de l'HTA par AMT (moyenne 148/92 mmHg) et un bilan initial normal, quelle stratégie thérapeutique proposez-vous ?","max":2,"options":["Bithérapie fixe à faible dose en monoprise associant IEC/ARA2 et inhibiteur calcique ou thiazidique","Monothérapie par bêtabloquant","Trithérapie d'emblée à doses optimales","Association d'un IEC et d'un ARA2","Mesures hygiénodiététiques associées au traitement médicamenteux","Traitement médicamenteux différé de principe pendant 6 mois","Cible théorique de 160/100 mmHg","Dosage systématique de rénine et d'aldostérone avant tout traitement"],"correct":[0,4],"explanation":"L'HTA confirmée impose un traitement médicamenteux d'emblée (bithérapie fixe privilégiée) associé, dès le départ, aux mesures hygiénodiététiques."}],"src":"p. 83-97"},{"id":"224-kfp-02","type":"KFP","rank":"B","objective":"224-obj-09","difficulty":3,"scenario":"Mme L., 29 ans, sans antécédent particulier, est adressée en consultation pour une hypertension artérielle sévère découverte à 178/108 mmHg en cabinet, confirmée par MAPA. Elle ne prend ni traitement ni contraception hormonale. L'examen retrouve un souffle abdominal latéralisé à droite, sans souffle précordial ni anomalie des pouls périphériques. Le bilan biologique initial montre une kaliémie à 3,2 mmol/L et une créatininémie normale.","questions":[{"stem":"Quels éléments de cette observation orientent vers une HTA secondaire ?","max":4,"options":["L'âge jeune de la patiente","Le caractère sévère de l'HTA (grade 3)","L'hypokaliémie associée","Le souffle abdominal latéralisé","La normalité de la créatininémie","L'absence de contraception hormonale","La présence d'un souffle précordial","Des pouls fémoraux abolis","Un antécédent familial isolé d'HTA"],"correct":[0,1,2,3],"explanation":"L'âge < 40 ans, la sévérité de l'HTA, l'hypokaliémie et le souffle abdominal latéralisé sont autant de points d'appel imposant de rechercher une HTA secondaire."},{"stem":"Quelle est l'hypothèse diagnostique la plus probable devant ce souffle abdominal latéralisé associé à une hypokaliémie chez cette femme jeune ?","max":1,"options":["Sténose de l'artère rénale par dysplasie fibromusculaire","Sténose de l'artère rénale d'origine athéromateuse","Syndrome de Conn (hyperaldostéronisme primaire)","Phéochromocytome","Coarctation de l'aorte","Glomérulopathie chronique","Polykystose rénale","Syndrome de Cushing"],"correct":[0],"explanation":"La dysplasie fibromusculaire touche typiquement la femme jeune ; elle se manifeste par un souffle abdominal latéralisé et une hypokaliémie par hyperaldostéronisme secondaire (rénine et aldostérone augmentées)."},{"stem":"Quels examens permettent de confirmer et de quantifier cette hypothèse ?","max":2,"options":["Échodoppler des artères rénales","Angioscanner abdominal","Cathétérisme des veines surrénaliennes","Scintigraphie à la MIBG","Polygraphie ventilatoire nocturne","IRM cérébrale","Test de freinage minute","Dosage du cortisol libre urinaire"],"correct":[0,1],"explanation":"L'échodoppler des artères rénales et l'angioscanner abdominal confirment et quantifient une sténose de l'artère rénale."}],"src":"p. 102-103"},{"id":"224-kfp-03","type":"KFP","rank":"A","objective":"224-obj-18","difficulty":3,"scenario":"M. B., 68 ans, hypertendu connu mais peu observant, est amené aux urgences pour une douleur thoracique constrictive apparue depuis une heure, associée à une dyspnée. La pression artérielle est mesurée à 210/118 mmHg aux deux bras, la fréquence cardiaque à 98/min. L'auscultation retrouve des râles crépitants bilatéraux. L'ECG montre un sus-décalage du segment ST en antérieur.","questions":[{"stem":"Quel diagnostic retenez-vous concernant le contexte tensionnel ?","max":1,"options":["Crise hypertensive simple","Urgence hypertensive avec syndrome coronarien aigu et œdème pulmonaire","HTA blouse blanche","HTA résistante non compliquée","Manœuvre d'Osler isolée","HTA masquée","Encéphalopathie hypertensive isolée","HTA maligne isolée sans atteinte cardiaque"],"correct":[1],"explanation":"L'association d'une HTA sévère et d'une atteinte aiguë d'organe cible (SCA, œdème pulmonaire) définit une urgence hypertensive engageant le pronostic vital."},{"stem":"Quels examens complémentaires demandez-vous en urgence ?","max":4,"options":["Troponine","Radiographie thoracique","Échocardiographie","Ionogramme et créatininémie","Bilan de coagulation et plaquettes","Fond d'œil avant tout geste","Scanner cérébral systématique en l'absence de signe neurologique","NFS avec recherche de schizocytes","Dosage de rénine et d'aldostérone en urgence","Angioscanner abdominal en urgence"],"correct":[0,1,2,3],"explanation":"Devant ce tableau de SCA et d'OAP, troponine, radiographie thoracique, échocardiographie et bilan rénal sont les examens de première intention adaptés au contexte."},{"stem":"Quelle prise en charge tensionnelle initiale proposez-vous ?","max":2,"options":["Dérivés nitrés IV en 1re intention (SCA et OAP)","Nicardipine IV, contre-indiquée ici en raison du contexte d'insuffisance cardiaque","Normalisation rapide de la PA sous 120/80 mmHg","Baisse de la PA de 20 à 25 % en 2 heures vers 160/110 mmHg","Labétalol IV systématique quel que soit le contexte","Urapidil IV en 1re intention pour tous les patients hypertendus","Attendre 24 heures avant tout traitement antihypertenseur","Traitement antihypertenseur oral ambulatoire seul"],"correct":[0,3],"explanation":"Dans le SCA avec OAP, les dérivés nitrés IV sont utilisés en 1re intention, avec pour objectif une baisse progressive de la PA de 20 à 25 % en 2 heures vers 160/110 mmHg, sans normalisation brutale."}],"src":"p. 105-107"},{"id":"224-tcs-01","type":"TCS","rank":"A","objective":"224-obj-01","difficulty":2,"vignette":"Vous voyez un homme de 50 ans pour une pression artérielle de cabinet à 148/92 mmHg, retrouvée de façon concordante à deux consultations successives, dans des conditions de mesure correctes. Il est asymptomatique, sans antécédent cardiovasculaire connu.","items":[{"hypothesis":"Si vous pensiez à une HTA « blouse blanche »,","newInfo":"et que vous constatez que l'automesure tensionnelle à domicile est strictement normale (moyenne 122/76 mmHg),","panel":[0,1,2,4,8],"explanation":"Une AMT normale malgré une PA de cabinet élevée confirme l'hypothèse d'HTA blouse blanche."},{"hypothesis":"Si vous pensiez à une HTA confirmée nécessitant un traitement médicamenteux,","newInfo":"et que cette même automesure est strictement normale,","panel":[8,4,2,1,0],"explanation":"Une AMT normale élimine le diagnostic d'HTA confirmée ; il s'agit alors d'une HTA blouse blanche, sans indication médicamenteuse."},{"hypothesis":"Si vous pensiez à une hypotension orthostatique associée,","newInfo":"et que sa recherche systématique lors de la consultation est négative (pas de chute de PA au passage debout),","panel":[7,5,2,1,0],"explanation":"L'absence de baisse tensionnelle à 1 et 3 minutes debout rend une hypotension orthostatique très peu probable."},{"hypothesis":"Si vous pensiez que ce patient nécessite un traitement médicamenteux,","newInfo":"et que l'AMT confirme finalement une moyenne à 138/88 mmHg, au-dessus du seuil de l'automesure,","panel":[0,1,2,4,8],"explanation":"Une AMT ≥ 135/85 mmHg confirme l'HTA : un traitement médicamenteux associé aux mesures hygiénodiététiques devient alors indiqué."}],"src":"p. 85-87"},{"id":"224-tcs-02","type":"TCS","rank":"B","objective":"224-obj-09","difficulty":3,"vignette":"Une femme de 34 ans consulte pour une hypertension artérielle récemment découverte à 172/106 mmHg. Elle ne prend aucun traitement connu et signale des céphalées avec sueurs profuses.","items":[{"hypothesis":"Si vous pensiez à un phéochromocytome,","newInfo":"et que ces céphalées et sueurs surviennent par crises brèves, associées à des palpitations,","panel":[0,1,2,4,8],"explanation":"La triade de Ménard (céphalées, sueurs, palpitations) survenant par crises brutales est très évocatrice de phéochromocytome."},{"hypothesis":"Si vous pensiez à un hyperaldostéronisme primaire (syndrome de Conn),","newInfo":"et que la kaliémie revient à 4,2 mmol/L, strictement normale,","panel":[2,4,3,4,2],"explanation":"L'hypokaliémie n'est présente que de façon inconstante dans l'hyperaldostéronisme primaire : une kaliémie normale ne permet ni de confirmer ni d'éliminer franchement le diagnostic."},{"hypothesis":"Si vous pensiez à une sténose de l'artère rénale par dysplasie fibromusculaire,","newInfo":"et que vous retrouvez un souffle abdominal latéralisé à l'auscultation,","panel":[0,1,2,4,8],"explanation":"Le souffle abdominal latéralisé est un signe évocateur de sténose de l'artère rénale."},{"hypothesis":"Si vous pensiez à une origine médicamenteuse (contraception œstroprogestative),","newInfo":"et que la patiente confirme ne prendre aucune contraception hormonale ni aucun autre traitement,","panel":[8,4,2,1,0],"explanation":"L'absence de tout traitement hypertensiogène rend cette hypothèse très peu probable chez cette patiente."}],"src":"p. 103-104"},{"id":"224-tcs-03","type":"TCS","rank":"A","objective":"224-obj-11","difficulty":3,"vignette":"Un homme de 60 ans, hypertendu connu, consulte aux urgences pour des céphalées intenses et des troubles visuels d'apparition brutale. La pression artérielle est mesurée à 220/125 mmHg.","items":[{"hypothesis":"Si vous pensiez à une simple crise hypertensive sans urgence,","newInfo":"et que le fond d'œil retrouve un œdème papillaire bilatéral,","panel":[8,4,2,1,0],"explanation":"L'œdème papillaire (stade 4) signe une atteinte aiguë d'organe cible et exclut la simple crise hypertensive : il s'agit d'une urgence hypertensive, voire d'une HTA maligne."},{"hypothesis":"Si vous pensiez à un accident vasculaire cérébral associé,","newInfo":"et que le scanner cérébral réalisé en urgence est normal, sans hémorragie ni ischémie visible,","panel":[4,6,3,1,1],"explanation":"Un scanner normal rend un AVC hémorragique très improbable mais n'élimine pas totalement un AVC ischémique très précoce, d'où une baisse seulement modérée de la probabilité."},{"hypothesis":"Si vous pensiez à une encéphalopathie hypertensive,","newInfo":"et que les troubles visuels et les céphalées s'améliorent rapidement après une baisse contrôlée et progressive de la PA,","panel":[0,1,2,4,8],"explanation":"L'amélioration rapide des symptômes neurologiques après contrôle tensionnel progressif est en faveur d'une encéphalopathie hypertensive."},{"hypothesis":"Si vous pensiez qu'un traitement par nicardipine IV est licite en 1re intention chez ce patient,","newInfo":"et que l'échocardiographie révèle une insuffisance cardiaque avec fraction d'éjection sévèrement altérée,","panel":[8,4,2,1,0],"explanation":"La nicardipine est contre-indiquée en cas d'insuffisance cardiaque ; il faut alors privilégier l'urapidil ou les dérivés nitrés IV."}],"src":"p. 105-107"},{"id":"224-tcs-04","type":"TCS","rank":"B","objective":"224-obj-12","difficulty":3,"vignette":"Un homme de 62 ans, hypertendu depuis 5 ans, reste à 158/96 mmHg malgré une trithérapie associant IEC, inhibiteur calcique et diurétique thiazidique à doses optimales depuis 3 mois, avec une bonne observance rapportée.","items":[{"hypothesis":"Si vous pensiez à une HTA résistante vraie,","newInfo":"et que l'automesure tensionnelle confirme des valeurs élevées, concordantes avec la mesure de cabinet,","panel":[0,1,2,4,8],"explanation":"La confirmation ambulatoire de chiffres élevés malgré une trithérapie optimale et une bonne observance est en faveur d'une HTA résistante vraie."},{"hypothesis":"Si vous pensiez à un simple effet blouse blanche expliquant ce déséquilibre,","newInfo":"et que l'automesure tensionnelle confirme des valeurs élevées, concordantes avec la mesure de cabinet,","panel":[8,4,2,1,0],"explanation":"Une AMT concordante avec la mesure de cabinet élimine un simple effet blouse blanche."},{"hypothesis":"Si vous pensiez à un syndrome d'apnées du sommeil sous-jacent,","newInfo":"et que le patient est obèse et rapporte des ronflements avec somnolence diurne,","panel":[0,1,2,4,8],"explanation":"Obésité, ronflements et somnolence diurne chez un hypertendu résistant sont évocateurs d'un SAOS, cause classique de résistance au traitement."},{"hypothesis":"Si vous pensiez qu'il faille proposer d'emblée une dénervation rénale,","newInfo":"et qu'aucun traitement par antagoniste des récepteurs minéralocorticoïdes n'a encore été essayé,","panel":[8,4,2,1,0],"explanation":"La spironolactone doit être proposée avant d'envisager la dénervation rénale, réservée aux échecs après ajout d'un ARM puis d'un bêtabloquant."}],"src":"p. 101-102"}],"trees":[{"id":"224-tree-01","title":"Confirmer le diagnostic d'HTA","rank":"A","objective":"224-obj-04","intro":"La démarche diagnostique part toujours d'une mesure de consultation, à confirmer hors cabinet avant toute décision thérapeutique, sauf urgence.","root":"n1","nodes":{"n1":{"type":"question","text":"PA de consultation (≥ 3 mesures, moyenne des 2 dernières) ≥ 140/90 mmHg ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e_normale"}]},"n2":{"type":"question","text":"Signes d'urgence hypertensive (atteinte aiguë d'un organe cible) ?","options":[{"label":"Oui","to":"e_urgence"},{"label":"Non","to":"n3"}]},"n3":{"type":"action","text":"Confirmer hors cabinet : AMT (règle des 3, en 1re intention) ou MAPA si AMT impossible ou peu fiable","to":"n4","note":"Délai : dans le mois si grade 2, dans la semaine si grade 3 sans urgence."},"n4":{"type":"question","text":"PA hors cabinet élevée (AMT ≥ 135/85 ou MAPA 24 h ≥ 130/80) ?","options":[{"label":"Oui","to":"e_confirmee"},{"label":"Non","to":"e_blouseblanche"}]},"e_normale":{"type":"end","tone":"ok","text":"Pas d'HTA ; réévaluer selon le niveau de risque et le dépistage habituel"},"e_urgence":{"type":"end","tone":"danger","text":"Urgence hypertensive : prise en charge immédiate, ne pas attendre la confirmation ambulatoire"},"e_blouseblanche":{"type":"end","tone":"info","text":"HTA « blouse blanche » : pas de traitement médicamenteux, mesures hygiénodiététiques et surveillance régulière hors cabinet"},"e_confirmee":{"type":"end","tone":"warn","text":"HTA confirmée : évaluation initiale complète puis stratégie thérapeutique"}},"src":"p. 85-87"},{"id":"224-tree-02","title":"Évaluation initiale d'un patient hypertendu confirmé","rank":"A","objective":"224-obj-05","intro":"Après confirmation, l'évaluation vise cinq objectifs avant la consultation d'annonce : niveau de PA, risque cardiovasculaire, organes cibles, facteurs aggravants et signes d'HTA secondaire.","root":"r1","nodes":{"r1":{"type":"action","text":"Interrogatoire complet (ancienneté, FDR, facteurs aggravants, grossesses, médicaments et toxiques hypertensiogènes) et examen clinique","to":"r2"},"r2":{"type":"action","text":"Bilan systématique : glycémie à jeun + HbA1c, bilan lipidique, Na/K, Hb/Ht, créatininémie avec DFG, protéinurie/créatininurie, ECG de repos","to":"r3"},"r3":{"type":"question","text":"Point d'appel pour une HTA secondaire (PA > 180/110 brutale, résistance, âge < 40 ans, hypokaliémie…) ?","options":[{"label":"Oui","to":"e_secondaire"},{"label":"Non","to":"r4"}]},"r4":{"type":"question","text":"ECG anormal ou symptômes cardiaques ?","options":[{"label":"Oui","to":"r5"},{"label":"Non","to":"r6"}]},"r5":{"type":"action","text":"Compléter par une échocardiographie (recherche d'HVG, fonction VG)","to":"r6","note":"L'échocardiographie n'est pas systématique chez l'asymptomatique à ECG normal."},"r6":{"type":"question","text":"Autre indication ciblée : souffle/symptômes d'AOMI, grade 3, grossesse possible ?","options":[{"label":"Oui","to":"r7"},{"label":"Non","to":"e_risque"}]},"r7":{"type":"action","text":"Selon le point d'appel : IPS/échodoppler des membres inférieurs ou des TSA, fond d'œil (recommandé en grade 3), β-hCG","to":"e_risque"},"e_secondaire":{"type":"end","tone":"warn","text":"Orienter vers la démarche de recherche d'une HTA secondaire et avis spécialisé"},"e_risque":{"type":"end","tone":"info","text":"Déterminer le risque CV global (élevé d'emblée, SCORE2/SCORE2-OP, SCORE2-Diabetes) puis consultation d'annonce"}},"src":"p. 90-94"},{"id":"224-tree-03","title":"Stratégie thérapeutique médicamenteuse initiale","rank":"A","objective":"224-obj-14","intro":"Le choix entre mesures hygiénodiététiques seules et traitement médicamenteux dépend du niveau de PA et du risque cardiovasculaire global.","root":"s1","nodes":{"s1":{"type":"action","text":"Débuter les mesures hygiénodiététiques chez tout patient (PA élevée ou HTA)","to":"s2"},"s2":{"type":"question","text":"HTA confirmée (et non simple PA élevée) ?","options":[{"label":"Oui","to":"e_traitement"},{"label":"Non","to":"s3"}]},"s3":{"type":"question","text":"PA élevée 130-139/70-89 avec risque cardiovasculaire élevé ?","options":[{"label":"Oui","to":"s4"},{"label":"Non","to":"e_surveillance"}]},"s4":{"type":"action","text":"Réévaluer après 3 mois de MHD seules","to":"s5","note":"Cible : PAS 120-129 et PAD 70-79 mmHg, idéalement 120/70."},"s5":{"type":"question","text":"PA toujours ≥ 130/80 mmHg à 3 mois ?","options":[{"label":"Oui","to":"e_monotherapie"},{"label":"Non","to":"e_surveillance"}]},"e_surveillance":{"type":"end","tone":"ok","text":"MHD seules ; réévaluation annuelle du risque cardiovasculaire"},"e_monotherapie":{"type":"end","tone":"info","text":"Introduire une monothérapie (IEC, ARA2, thiazidique ou IC dihydropyridine)"},"e_traitement":{"type":"end","tone":"warn","text":"Traitement médicamenteux d'emblée pour tous : bithérapie fixe à faible dose en monoprise (sauf critère de monothérapie initiale)"}},"src":"p. 95-97"},{"id":"224-tree-04","title":"Choix de la bithérapie ou de la monothérapie initiale","rank":"A","objective":"224-obj-14","intro":"Chez l'hypertendu confirmé nécessitant un traitement immédiat, la bithérapie fixe à faible dose est la règle, sauf situations particulières justifiant une monothérapie.","root":"m1","nodes":{"m1":{"type":"question","text":"Fragilité modérée/sévère, hypotension orthostatique préexistante ou âge > 85 ans ?","options":[{"label":"Oui","to":"e_mono"},{"label":"Non","to":"m2"}]},"m2":{"type":"action","text":"Choisir une bithérapie fixe à faible dose en monoprise associant deux classes parmi IEC/ARA2, IC, thiazidique","to":"m3","note":"Jamais IEC + ARA2 ensemble."},"m3":{"type":"question","text":"Comorbidité orientant le choix (diabète, insuffisance rénale, ATCD coronarien, angor, IC à FEVG altérée) ?","options":[{"label":"Oui","to":"e_oriente"},{"label":"Non","to":"e_standard"}]},"e_mono":{"type":"end","tone":"info","text":"Monothérapie initiale : IEC, ARA2, thiazidique ou IC dihydropyridine"},"e_oriente":{"type":"end","tone":"info","text":"Association orientée par la comorbidité (ex. IEC/ARA2 privilégiés si néphropathie ou diabète, BB si angor ou post-infarctus)"},"e_standard":{"type":"end","tone":"ok","text":"IEC ou ARA2 + inhibiteur calcique dihydropyridine, ou IEC/ARA2 + thiazidique"}},"src":"p. 96-98"},{"id":"224-tree-05","title":"Suivi et adaptation du traitement","rank":"A","objective":"224-obj-19","intro":"Le suivi rapproché des premiers mois vise à atteindre la cible tensionnelle sans dépasser la trithérapie sans avoir renforcé au préalable MHD et observance.","root":"f1","nodes":{"f1":{"type":"action","text":"AMT à 1 mois après toute adaptation ; ionogramme et créatininémie si IEC/ARA2 ou diurétique modifiés","to":"f2"},"f2":{"type":"question","text":"Cible tensionnelle atteinte à 1 mois ?","options":[{"label":"Oui","to":"e_cible"},{"label":"Non","to":"f3"}]},"f3":{"type":"action","text":"Renforcer l'adhésion aux MHD et l'observance médicamenteuse","to":"f4"},"f4":{"type":"action","text":"Passer en trithérapie (idéalement IEC/ARA2 + IC + thiazidique) avant d'augmenter les doses, puis revoir à 1 mois avec AMT","to":"f5"},"f5":{"type":"question","text":"Cible toujours non atteinte sous trithérapie optimale (3 classes dont un thiazidique, à dose optimale) ?","options":[{"label":"Oui","to":"e_resistante"},{"label":"Non","to":"e_cible"}]},"e_cible":{"type":"end","tone":"ok","text":"Patient à la cible : consultation tous les 3 à 6 mois, bilan biologique annuel, ECG tous les 3 à 5 ans"},"e_resistante":{"type":"end","tone":"warn","text":"HTA résistante confirmée par AMT/MAPA après élimination d'une fausse résistance : avis spécialisé"}},"src":"p. 100-102"},{"id":"224-tree-06","title":"Prise en charge de l'HTA résistante","rank":"B","objective":"224-obj-12","intro":"L'HTA résistante ne se retient que chez un patient recevant un diurétique thiazidique, après avoir écarté une fausse résistance et une cause curable.","root":"h1","nodes":{"h1":{"type":"question","text":"Trithérapie à dose optimale comprenant un diurétique thiazidique et MHD suivies ?","options":[{"label":"Oui","to":"h2"},{"label":"Non","to":"e_optimiser"}]},"h2":{"type":"action","text":"Confirmer par AMT (souvent MAPA) et éliminer une fausse résistance (blouse blanche, brassard, observance)","to":"h3"},"h3":{"type":"question","text":"Facteur de résistance identifié (SAOS, substances hypertensiogènes, HTA secondaire méconnue, surcharge volémique) ?","options":[{"label":"Oui","to":"e_causale"},{"label":"Non","to":"h4"}]},"h4":{"type":"action","text":"Ajouter un antagoniste des récepteurs minéralocorticoïdes (spironolactone en 1re intention, éplérénone si intolérance)","to":"h5"},"h5":{"type":"question","text":"Cible toujours non atteinte sous quadrithérapie avec ARM ?","options":[{"label":"Oui","to":"e_escalade"},{"label":"Non","to":"e_cible"}]},"e_optimiser":{"type":"end","tone":"info","text":"Ce n'est pas une HTA résistante vraie : optimiser d'abord la trithérapie et les MHD"},"e_causale":{"type":"end","tone":"warn","text":"Traiter la cause identifiée (ex. masque nocturne pour un SAOS, arrêt d'un médicament hypertensiogène)"},"e_escalade":{"type":"end","tone":"danger","text":"Ajouter un bêtabloquant (si non déjà indiqué), puis un alphabloquant ou un antihypertenseur central ; discuter la dénervation rénale au cas par cas"},"e_cible":{"type":"end","tone":"ok","text":"Cible atteinte sous quadrithérapie avec ARM : poursuivre la surveillance"}},"src":"p. 101-102"},{"id":"224-tree-07","title":"Devant une urgence hypertensive","rank":"A","objective":"224-obj-18","intro":"Toute HTA sévère avec atteinte aiguë d'un organe cible impose une prise en charge en urgence, avec une baisse tensionnelle progressive sauf exceptions.","root":"u1","nodes":{"u1":{"type":"question","text":"PA sévère avec signe neurologique focal ?","options":[{"label":"Oui","to":"u2"},{"label":"Non","to":"u3"}]},"u2":{"type":"action","text":"Scanner cérébral avant tout antihypertenseur (éliminer une hémorragie)","to":"u3"},"u3":{"type":"question","text":"Suspicion de dissection aortique ?","options":[{"label":"Oui","to":"e_dissection"},{"label":"Non","to":"u4"}]},"u4":{"type":"question","text":"Contexte évocateur de phéochromocytome (triade de Ménard, poussées) ?","options":[{"label":"Oui","to":"e_pheo"},{"label":"Non","to":"u5"}]},"u5":{"type":"question","text":"SCA ou œdème aigu du poumon ?","options":[{"label":"Oui","to":"e_nitres"},{"label":"Non","to":"e_general"}]},"e_dissection":{"type":"end","tone":"danger","text":"Baisser la PAS sous 120 mmHg le plus vite possible"},"e_pheo":{"type":"end","tone":"danger","text":"Labétalol IV (alpha- et bêtabloquant)"},"e_nitres":{"type":"end","tone":"warn","text":"Dérivés nitrés IV en 1re intention (nicardipine contre-indiquée en insuffisance cardiaque)"},"e_general":{"type":"end","tone":"warn","text":"Urapidil IV et/ou nicardipine IV : baisse de 20-25 % en 2 h, cible 160/110 mmHg en 2 à 6 h, soins intensifs, PA toutes les 15 min"}},"src":"p. 105-107"},{"id":"224-tree-08","title":"Suspicion d'HTA secondaire : orientation étiologique","rank":"A","objective":"224-obj-09","intro":"Un point d'appel de dépistage d'HTA secondaire oriente vers un bilan spécialisé ciblé selon les signes cliniques et biologiques.","root":"o1","nodes":{"o1":{"type":"question","text":"Hypokaliémie associée à l'HTA ?","options":[{"label":"Oui","to":"o2"},{"label":"Non","to":"o3"}]},"o2":{"type":"action","text":"Doser rénine et aldostérone (conditions strictes) : recherche d'un hyperaldostéronisme primaire ou d'une cause rénovasculaire","to":"e_endocrine"},"o3":{"type":"question","text":"Souffle abdominal, OAP flash récidivant ou IRA sous IEC/ARA2 ?","options":[{"label":"Oui","to":"e_renovasculaire"},{"label":"Non","to":"o4"}]},"o4":{"type":"question","text":"Triade de Ménard (céphalées, sueurs, palpitations en crises) ?","options":[{"label":"Oui","to":"e_pheochromocytome"},{"label":"Non","to":"o5"}]},"o5":{"type":"question","text":"Souffle mésosystolique parasternal gauche et dorsal avec pouls fémoraux abolis chez un sujet jeune ?","options":[{"label":"Oui","to":"e_coarctation"},{"label":"Non","to":"e_parenchymateuse"}]},"e_endocrine":{"type":"end","tone":"info","text":"Orienter vers un hyperaldostéronisme primaire (aldostérone haute, rénine basse) après élimination d'une cause rénovasculaire (rénine et aldostérone toutes deux hautes)"},"e_renovasculaire":{"type":"end","tone":"warn","text":"Échodoppler des artères rénales et angioscanner abdominal : sténose athéromateuse (ostium, tiers proximal) ou dysplasie fibromusculaire (femme jeune, deux tiers distaux)"},"e_pheochromocytome":{"type":"end","tone":"warn","text":"Doser les dérivés méthoxylés urinaires et/ou plasmatiques, puis localiser par scanner et scintigraphie à la MIBG"},"e_coarctation":{"type":"end","tone":"warn","text":"Confirmer par échocardiographie puis IRM ; traitement chirurgical ou endoluminal"},"e_parenchymateuse":{"type":"end","tone":"info","text":"Rechercher une néphropathie parenchymateuse (glomérulopathie, polykystose) par échographie rénale et bilan urinaire"}},"src":"p. 102-105"}],"treatments":{"data":[{"id":"224-tx-01","rank":"A","class":"Inhibiteurs de l'enzyme de conversion (IEC)","molecules":[],"context":"Une des cinq classes de 1re intention dans l'HTA, souvent utilisée dès le début en bithérapie","indications":["Bithérapie initiale avec un inhibiteur calcique dihydropyridine ou un thiazidique","Monothérapie initiale dans certaines situations (PA élevée à traiter, fragilité, hypotension orthostatique, âge > 85 ans)","Diabète avec microalbuminurie ou insuffisance rénale","Insuffisance rénale et/ou protéinurie","Antécédent d'AVC ou d'infarctus","Insuffisance cardiaque à FEVG altérée"],"contraindications":["Grossesse","Angio-œdème sous IEC (contre-indication absolue et définitive)","Hyperkaliémie","Femme en âge de procréer sans contraception (relative)","Sténose bilatérale des artères rénales (relative)","Insuffisance rénale sévère (relative)"],"sideEffects":["Toux","Hyperkaliémie","Insuffisance rénale fonctionnelle"],"monitoring":["Ionogramme sanguin et créatininémie/DFG après toute introduction ou changement de dose","AMT à 1 mois après adaptation"],"interactions":["Jamais associé à un ARA2","AINS : risque de déséquilibre tensionnel et d'insuffisance rénale"],"pearls":["Suspendre transitoirement en cas de risque d'hypovolémie (diarrhée, vomissements, fièvre, canicule), surtout chez l'âgé, avec contrôle biologique","Une insuffisance rénale apparaissant sous IEC doit faire évoquer une sténose des artères rénales"],"src":"p. 96-100"},{"id":"224-tx-02","rank":"A","class":"Antagonistes des récepteurs de l'angiotensine II (ARA2)","molecules":[],"context":"Une des cinq classes de 1re intention, alternative aux IEC notamment en cas d'intolérance","indications":["Bithérapie initiale avec un inhibiteur calcique dihydropyridine ou un thiazidique","Monothérapie initiale (mêmes situations que l'IEC)","Diabète avec microalbuminurie ou insuffisance rénale","Insuffisance rénale et/ou protéinurie","Antécédent d'AVC ou d'infarctus","Insuffisance cardiaque à FEVG altérée en cas d'intolérance aux IEC"],"contraindications":["Grossesse","Hyperkaliémie (relative)","Femme en âge de procréer sans contraception (relative)","Sténose bilatérale des artères rénales (relative)","Insuffisance rénale sévère (relative)"],"sideEffects":["Hyperkaliémie","Insuffisance rénale fonctionnelle"],"monitoring":["Ionogramme sanguin et créatininémie/DFG après toute introduction ou changement de dose","AMT à 1 mois après adaptation"],"interactions":["Jamais associé à un IEC","AINS : risque de déséquilibre tensionnel et d'insuffisance rénale"],"pearls":["Suspendre transitoirement en cas de risque d'hypovolémie, surtout chez l'âgé, avec contrôle biologique"],"src":"p. 96-100"},{"id":"224-tx-03","rank":"A","class":"Inhibiteurs calciques (dihydropyridines)","molecules":[],"context":"Une des cinq classes de 1re intention ; composante habituelle de la bithérapie initiale et de la trithérapie","indications":["Bithérapie initiale avec un IEC ou un ARA2","Monothérapie initiale (mêmes situations que l'IEC/ARA2)","Antécédent d'AVC","Angor (avec ou sans bêtabloquant)","Sujet âgé fragile ou > 85 ans, en 1re intention"],"contraindications":[],"sideEffects":["Œdèmes des membres inférieurs","Céphalées","Flushs (bouffées vasomotrices)"],"monitoring":[],"interactions":[],"pearls":["Molécule habituellement privilégiée en 1re intention chez le sujet âgé de plus de 85 ans"],"src":"p. 96-100"},{"id":"224-tx-04","rank":"A","class":"Inhibiteurs calciques non dihydropyridiniques (bradycardisants)","molecules":[],"context":"Inhibiteurs calciques à effet bradycardisant, à distinguer des dihydropyridines pour leurs contre-indications","indications":[],"contraindications":["Bloc auriculoventriculaire de 2e ou 3e degré","Insuffisance cardiaque à FEVG altérée"],"sideEffects":["Œdèmes des membres inférieurs","Céphalées","Flushs","Bradycardie","Troubles de conduction","Constipation"],"monitoring":[],"interactions":["Association aux bêtabloquants déconseillée (risque de bradycardie et de trouble de conduction)"],"pearls":["Contrairement aux dihydropyridines, ils sont contre-indiqués en cas de BAV 2-3 ou d'insuffisance cardiaque à FEVG altérée"],"src":"p. 98-100"},{"id":"224-tx-05","rank":"A","class":"Diurétiques thiazidiques ou apparentés (indapamide)","molecules":["indapamide"],"context":"Une des cinq classes de 1re intention ; indispensables à la définition de l'HTA résistante","indications":["Bithérapie initiale avec un IEC ou un ARA2","Monothérapie initiale (mêmes situations que l'IEC/ARA2)","Composante de la trithérapie optimale (IEC/ARA2 + IC + thiazidique)","2e intention chez le sujet âgé fragile, à faible dose","Antécédent d'AVC","Insuffisance cardiaque à FEVG altérée"],"contraindications":["Goutte","Hypokaliémie","Hypercalcémie","Grossesse"],"sideEffects":["Hypokaliémie","Hyponatrémie","Hyperglycémie","Hyperuricémie","Insuffisance rénale fonctionnelle"],"monitoring":["Ionogramme sanguin et créatininémie/DFG après toute introduction ou changement de dose"],"interactions":[],"pearls":["On ne parle d'HTA résistante que chez un patient recevant un diurétique thiazidique","Persistance thérapeutique plus faible qu'avec les bloqueurs du SRA ou les inhibiteurs calciques","Suspendre transitoirement en cas de risque d'hypovolémie (déshydratation, canicule)"],"src":"p. 96-102"},{"id":"224-tx-06","rank":"A","class":"Bêtabloquants","molecules":[],"context":"Une des cinq classes de 1re intention, mais moins efficace sur la prévention des AVC : réservés à une indication associée","indications":["Antécédent d'infarctus","Angor (avec ou sans inhibiteur calcique)","Insuffisance cardiaque à FEVG altérée","Traitement pré-opératoire du phéochromocytome, associés à un alphabloquant"],"contraindications":["Asthme","Bloc auriculoventriculaire de 2e ou 3e degré"],"sideEffects":["Asthénie au début du traitement","Bradycardie sinusale","Acrosyndrome (syndrome de Raynaud)","Hypoglycémie","Baisse de la libido","Dysfonction érectile","Prise de poids"],"monitoring":[],"interactions":["Association aux inhibiteurs calciques bradycardisants déconseillée"],"pearls":["Jamais en monothérapie initiale dans l'HTA","À n'introduire qu'en présence d'une autre indication","Éviter chez le sujet âgé fragile (sauf indication formelle)","Persistance thérapeutique parmi les plus faibles"],"src":"p. 96-102"},{"id":"224-tx-07","rank":"B","class":"Antagonistes des récepteurs minéralocorticoïdes (ARM)","molecules":["spironolactone","éplérénone"],"context":"4e ligne dans l'HTA résistante vraie, après confirmation et élimination des causes curables","indications":["HTA résistante confirmée sous trithérapie optimale dont un thiazidique","Traitement médical de l'hyperaldostéronisme primaire sans indication ou sans possibilité de chirurgie"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Spironolactone en 1re intention, éplérénone en cas d'intolérance","Doit être arrêtée depuis 6 semaines avant un dosage de rénine et d'aldostérone"],"src":"p. 102, 104"},{"id":"224-tx-08","rank":"B","class":"Alphabloquants et antihypertenseurs centraux","molecules":[],"context":"Options d'escalade dans l'HTA résistante vraie ou traitement pré-opératoire du phéochromocytome","indications":["HTA résistante vraie, après ARM puis bêtabloquant si non déjà utilisé","Alphabloquant en préparation pré-opératoire du phéochromocytome, à doses progressives, avant chirurgie"],"contraindications":["Alphabloquant à éviter chez le sujet âgé fragile"],"sideEffects":[],"monitoring":[],"interactions":["Alphabloquant associé au bêtabloquant dans le phéochromocytome pour limiter la poussée hypertensive et l'hypotension peropératoires"],"pearls":[],"src":"p. 99-104"},{"id":"224-tx-09","rank":"B","class":"Dénervation rénale","molecules":[],"context":"Procédure interventionnelle discutée au cas par cas dans l'HTA résistante vraie","indications":["HTA résistante persistant malgré une quadrithérapie optimale incluant un ARM, au cas par cas"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 102"},{"id":"224-tx-10","rank":"A","class":"Vasodilatateurs IV de l'urgence hypertensive","molecules":["urapidil","nicardipine","labétalol","dérivés nitrés"],"context":"Traitement de l'urgence hypertensive en soins intensifs ou en réanimation","indications":["Urapidil IV et/ou nicardipine IV en 1re intention dans le cas général","Labétalol IV en cas de phéochromocytome","Dérivés nitrés IV en 1re intention dans le SCA ou l'œdème aigu du poumon"],"contraindications":["Nicardipine contre-indiquée en cas d'insuffisance cardiaque"],"sideEffects":[],"monitoring":["Surveillance de la PA toutes les 15 minutes","Scanner cérébral avant tout traitement en cas de signe neurologique"],"interactions":[],"pearls":["Baisse progressive : 20-25 % en 2 h puis 160/110 mmHg en 2 à 6 h, sauf dissection aortique où la PAS doit être abaissée sous 120 mmHg le plus vite possible","Une chute trop brutale de la PA expose à une hypoperfusion cérébrale, myocardique ou rénale"],"src":"p. 106"},{"id":"224-tx-11","rank":"A","class":"Mesures hygiénodiététiques","molecules":[],"context":"Premier pilier de la prise en charge, indiqué chez tout patient (PA élevée ou HTA), avec ou sans traitement médicamenteux","indications":["PA élevée","HTA confirmée, en association systématique au traitement médicamenteux"],"contraindications":["Augmentation de l'apport en potassium contre-indiquée en cas de maladie rénale chronique avancée"],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Réduction attendue de la PAS de 5 à 10 mmHg","Sel 5-6 g/j, alcool < 10 unités/semaine, IMC cible 20-25 kg/m², tour de taille < 94 cm (homme) et < 80 cm (femme), arrêt du tabac, activité physique régulière, alimentation de type méditerranéen","Le café n'est pas à limiter ; ce sont les boissons à la taurine et à la caféine qui sont déconseillées"],"src":"p. 95-96"},{"id":"224-tx-12","rank":"A","class":"Traitement de l'hyperaldostéronisme primaire","molecules":["spironolactone"],"context":"Prise en charge du syndrome de Conn selon la latéralisation de la lésion","indications":["Cathétérisme des veines surrénaliennes en cas de lésion unilatérale au scanner chez un patient demandeur, puis surrénalectomie si latéralisation confirmée","Spironolactone en 1re intention si pas de chirurgie envisagée ou hyperplasie bilatérale"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 104"},{"id":"224-tx-13","rank":"A","class":"Traitement chirurgical du phéochromocytome","molecules":[],"context":"Exérèse de la tumeur après préparation médicamenteuse pour prévenir les à-coups tensionnels peropératoires","indications":["Exérèse chirurgicale après alphabloquants à doses progressives associés à des bêtabloquants"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["La préparation alpha puis bêtabloquante limite la poussée hypertensive et l'hypotension par déplétion volémique peropératoires"],"src":"p. 104"},{"id":"224-tx-14","rank":"A","class":"Revascularisation d'une sténose des artères rénales","molecules":[],"context":"Procédure endovasculaire selon la cause de la sténose rénovasculaire","indications":["Angioplastie avec endoprothèse pour une sténose athéromateuse, discutée uniquement en cas de souffrance du rein homolatéral (HTA résistante, dégradation de la fonction rénale, protéinurie importante) et si le rein reste fonctionnel","Angioplastie sans endoprothèse, plus largement utilisée, pour une dysplasie fibromusculaire"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Traitement médical associé systématique : MHD, aspirine, statine si athérome, antihypertenseurs"],"src":"p. 103"},{"id":"224-tx-15","rank":"B","class":"Traitement de la coarctation aortique","molecules":[],"context":"Correction mécanique de la sténose de l'isthme aortique","indications":["Traitement chirurgical ou endoluminal (dilatation avec endoprothèse) après confirmation par échocardiographie et IRM"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 104"},{"id":"224-tx-16","rank":"B","class":"Traitement du syndrome d'apnées du sommeil chez l'hypertendu","molecules":[],"context":"Mesure non médicamenteuse ciblant un facteur de résistance fréquent chez l'obèse","indications":["Masque de pression positive nocturne après confirmation par polygraphie ou polysomnographie"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["À évoquer devant une HTA résistante ou un profil « non dipper » en MAPA"],"src":"p. 104"}],"strategies":[{"id":"224-strat-01","rank":"A","title":"Stratégie thérapeutique générale de l'HTA de l'adulte","content":"**Quatre piliers** : mesures hygiénodiététiques, traitement des autres facteurs de risque cardiovasculaire, traitement médicamenteux, éducation thérapeutique. Aucune limite d'âge pour envisager un traitement.\n\n1. **PA élevée sans risque CV élevé** : MHD seules, réévaluation annuelle du risque.\n2. **PA élevée 130-139/70-89 avec risque CV élevé** : MHD 3 mois, puis monothérapie si la PA reste ≥ 130/80 mmHg.\n3. **HTA confirmée (≥ 140/90 en consultation)** : traitement médicamenteux d'emblée chez tous, associé aux MHD.\n\n**Initiation** : bithérapie fixe à faible dose en monoprise (IEC ou ARA2 + inhibiteur calcique dihydropyridine, ou IEC/ARA2 + thiazidique) sauf critère de monothérapie initiale (PA élevée à traiter, fragilité modérée/sévère, hypotension orthostatique préexistante, âge > 85 ans). Jamais IEC + ARA2. Bêtabloquant réservé à une autre indication associée.\n\n**Cible** : PAS 120-129 mmHg et PAD 70-79 mmHg, idéalement 120/70, à atteindre en 3 mois ; cible adaptée d'emblée ou en cours de suivi selon la tolérance (hypotension orthostatique, fragilité, âge > 85 ans, espérance de vie limitée) ; sinon viser la PA la plus basse tolérée et < 140/90 mmHg.\n\n**Non atteinte à 1 mois** : renforcer MHD et observance, puis passer en trithérapie (IEC/ARA2 + IC + thiazidique) avant de majorer les doses, revoir à 1 mois avec AMT.\n\n**Suivi** : consultation tous les 3 à 6 mois selon le risque une fois la cible atteinte, ionogramme et créatininémie après tout changement d'IEC/ARA2 ou de diurétique, bilan biologique annuel, glycémie et lipides tous les 3 ans, ECG tous les 3 à 5 ans.","src":"p. 95-101"},{"id":"224-strat-02","rank":"B","title":"Prise en charge de l'HTA résistante","content":"**Définition** : PA au-dessus de la cible malgré les MHD et au moins 3 classes à dose optimale dont un diurétique thiazidique, confirmée par AMT (souvent complétée par une MAPA).\n\n**Étape 1** : éliminer une fausse résistance : effet blouse blanche, brassard inadapté, doses insuffisantes ou absence de diurétique, inobservance, MHD non suivies (sel, poids, alcool).\n\n**Étape 2** : rechercher une cause : substances hypertensiogènes (AINS, corticoïdes, vasoconstricteurs, œstrogènes, cannabis, cocaïne, amphétamines), SAOS, HTA secondaire méconnue, surcharge volémique (diurétique insuffisant, insuffisance rénale) ; avis spécialisé.\n\n**Étape 3, escalade thérapeutique** (sans cause curable identifiée) : ajouter à la trithérapie optimale, dans l'ordre, un antagoniste des récepteurs minéralocorticoïdes (spironolactone en 1re intention, éplérénone si intolérance), puis un bêtabloquant s'il n'est pas déjà indiqué, puis un alphabloquant ou un antihypertenseur central ; la dénervation rénale se discute au cas par cas.","src":"p. 101-102"},{"id":"224-strat-03","rank":"A","title":"Adaptation du traitement chez le sujet âgé","content":"L'âge seul ne guide pas le traitement : rechercher une fragilité gériatrique modérée ou sévère et des arguments pour une espérance de vie limitée.\n\n- Avant 85 ans, sans fragilité ni facteur limitant l'espérance de vie : pas d'adaptation par rapport à l'adulte plus jeune.\n- Un traitement bien toléré ne doit pas être arrêté ou allégé systématiquement au passage de 85 ans.\n- Adapter la prise en charge si au moins un critère : fragilité modérée/sévère, âge > 85 ans, espérance de vie < 3 ans.\n\n**Adaptations** : débuter en monothérapie ; privilégier les inhibiteurs calciques dihydropyridines et/ou les IEC/ARA2 en 1re intention, les thiazidiques à faible dose en 2e intention ; éviter les bêtabloquants (sauf indication formelle) et les alphabloquants ; ne pas dépasser une trithérapie ; individualiser la cible tensionnelle selon la tolérance clinique et paraclinique, le patient devant rester exempt d'hypotension orthostatique à cette cible. En cas d'hypovolémie (diarrhée, vomissements, fièvre, canicule), savoir réduire ou suspendre transitoirement diurétiques, IEC et ARA2, avec contrôle du ionogramme et de la fonction rénale.","src":"p. 99-100"},{"id":"224-strat-04","rank":"A","title":"Prise en charge d'une urgence hypertensive","content":"**Bilan** : biologie (créatinine, protéinurie, plaquettes, coagulation, troponine, recherche de toxiques, NFS avec schizocytes, bilirubine libre, haptoglobine, LDH), ECG, radio thoracique, échocardiographie, fond d'œil, scanner cérébral en cas de signe neurologique, imagerie aortique en cas de suspicion de dissection.\n\n**Prise en charge** : soins intensifs adaptés à l'organe atteint ou réanimation, surveillance de la PA toutes les 15 minutes. Devant un déficit neurologique, aucun antihypertenseur avant le scanner cérébral (hémorragie vs ischémie).\n\n**Objectif tensionnel du cas général** : baisse de 20 à 25 % en 2 heures, puis 160/110 mmHg en 2 à 6 heures, sans chute brutale (risque d'hypoperfusion cérébrale, myocardique ou rénale par altération de l'autorégulation).\n\n**Exception** : dissection aortique, où la PAS doit être abaissée sous 120 mmHg le plus vite possible.\n\n**Traitement** : urapidil IV et/ou nicardipine IV en 1re intention (nicardipine contre-indiquée en insuffisance cardiaque) ; labétalol IV pour le phéochromocytome ; dérivés nitrés IV en 1re intention pour le SCA ou l'OAP.\n\n**AVC (ESC 2024)** : hémorragie intracérébrale, baisse immédiate en moins de 6 h vers une PAS de 140-160 mmHg sans chute de plus de 70 mmHg ; AVC ischémique sans reperfusion, pas de baisse active sauf PA > 220/120 (alors − 10 à 15 % sur quelques heures) ; avant thrombolyse IV, PA < 185/110 puis < 180/105 pendant 24 h ; avant thrombectomie, PA < 180/105 avant et pendant les 24 h suivantes ; si la PA reste > 140/90 au moins 3 jours après un AVC ischémique stable, débuter ou reprendre un antihypertenseur.","src":"p. 105-107"}]},"cases":[{"id":"224-case-01","title":"M. Lefranc, 54 ans, découverte fortuite d'une PA élevée en médecine du travail","rank":"A","summary":"Cadre sédentaire, surpoids, tabagique, chez qui une PA élevée en médecine du travail conduit à la confirmation, au bilan et à l'instauration d'un traitement.","difficulty":2,"timeline":["Découverte","Confirmation ambulatoire","Bilan initial et annonce","Traitement","Adaptation à 1 mois","Suivi au long cours"],"steps":[{"id":"224-case-01-s01","phase":0,"narrative":"M. Lefranc, 54 ans, cadre commercial, tabagique à 15 paquets-années, sédentaire, consulte la médecine du travail pour la visite annuelle. Aucun symptôme. La PA mesurée deux fois est à 152/94 mmHg.","question":{"type":"QRM","stem":"Quelles sont les règles à respecter pour valider une mesure de PA de consultation fiable ?","options":[{"t":"Au moins 3 mesures espacées de 1 à 2 minutes, moyenne des 2 dernières","ok":true,"why":"C'est la méthode recommandée pour la mesure de consultation."},{"t":"Patient assis, au calme, après plus de 5 minutes de repos","ok":true,"why":"Le repos préalable est indispensable pour éviter une surestimation."},{"t":"Mesure aux deux bras à la première consultation","ok":true,"why":"Une asymétrie fait suspecter une sténose de l'artère subclavière."},{"t":"Une seule mesure suffit si le patient est stressé","ok":false,"why":"Une mesure unique n'est jamais suffisante, surtout en cas de stress (effet blouse blanche)."},{"t":"Le stéthoscope doit toujours être préféré à l'appareil électronique","ok":false,"why":"L'appareil électronique validé est la méthode de 1re intention, sauf en fibrillation atriale."}],"explanation":"La mesure de consultation impose des conditions standardisées : repos, plusieurs mesures, moyenne des 2 dernières, et un contrôle aux deux bras lors de la première consultation."},"reveal":"Le médecin du travail reprend 3 mesures aux deux bras après 5 minutes de repos : moyenne à 148/92 mmHg, sans asymétrie. Il adresse le patient à son médecin traitant.","src":"p. 83-85"},{"id":"224-case-01-s02","phase":1,"narrative":"Le médecin traitant retrouve une PA de consultation à 146/90 mmHg (moyenne de 3 mesures). Le patient n'a pas d'antécédent connu, pas de symptôme, pas de facteur d'urgence.","question":{"type":"QRU","stem":"Quelle est la conduite à tenir avant d'envisager un traitement antihypertenseur ?","options":[{"t":"Débuter d'emblée une bithérapie sur la seule mesure de cabinet","ok":false,"why":"Aucun traitement ne doit être débuté sur les seules mesures de cabinet, hors urgence."},{"t":"Confirmer le diagnostic hors cabinet, de préférence par automesure tensionnelle (AMT)","ok":true,"why":"L'AMT est l'examen recommandé en France pour confirmer l'HTA avant traitement."},{"t":"Réaliser une IRM cérébrale systématique","ok":false,"why":"Aucune indication d'imagerie cérébrale systématique devant une simple découverte d'HTA non compliquée."},{"t":"Attendre un an avant toute nouvelle mesure","ok":false,"why":"Un tel délai n'est pas recommandé face à une PA de cabinet élevée à deux reprises."},{"t":"Doser d'emblée la rénine et l'aldostérone","ok":false,"why":"Ce dosage n'est indiqué qu'en cas de point d'appel pour une HTA secondaire, non systématique ici."}],"explanation":"Le diagnostic d'HTA posé au cabinet doit être confirmé hors cabinet, préférentiellement par AMT, avant toute décision thérapeutique en l'absence d'urgence."},"reveal":"Le patient est éduqué à la règle des 3 : 3 mesures le matin et 3 le soir pendant 3 jours consécutifs, avec un appareil huméral validé.","src":"p. 85-86"},{"id":"224-case-01-s03","phase":1,"narrative":"Le relevé d'AMT rapporte une moyenne de 142/91 mmHg sur les 18 mesures.","question":{"type":"QROC","question":"À partir de quel seuil de PA moyenne en AMT retient-on le diagnostic d'HTA ?","answer":"≥ 135/85 mmHg","accept":["135/85","PAS ≥ 135 et/ou PAD ≥ 85"],"keywords":["135","85"],"explanation":"Le seuil d'HTA en automesure est plus bas qu'au cabinet (140/90), car les mesures ambulatoires sont mieux corrélées au risque cardiovasculaire."},"reveal":"Le diagnostic d'HTA confirmée est posé : PA en AMT à 142/91 mmHg, au-dessus du seuil de 135/85 mmHg.","src":"p. 86"},{"id":"224-case-01-s04","phase":2,"narrative":"L'interrogatoire retrouve un tabagisme actif, une sédentarité, un père hypertendu et coronarien à 58 ans. L'examen note un tour de taille à 102 cm, une auscultation cardiaque normale, des pouls périphériques présents et symétriques.","question":{"type":"QRM","stem":"Quels éléments doivent être recherchés lors de l'évaluation initiale de ce patient hypertendu ?","options":[{"t":"Le niveau de risque cardiovasculaire global","ok":true,"why":"C'est l'un des cinq objectifs de l'évaluation initiale."},{"t":"Une atteinte infraclinique des organes cibles","ok":true,"why":"Recherche systématique d'un retentissement cardiaque, vasculaire, cérébral ou rénal."},{"t":"Des facteurs aggravants (alimentation, alcool, sédentarité, SAOS)","ok":true,"why":"Ils font partie de l'évaluation initiale et orientent les mesures hygiénodiététiques."},{"t":"Des arguments pour une HTA secondaire","ok":true,"why":"Un des cinq objectifs, même en l'absence de point d'appel évident au premier abord."},{"t":"La réalisation systématique d'une IRM des surrénales","ok":false,"why":"Aucune imagerie surrénalienne systématique en l'absence de point d'appel pour une HTA secondaire."}],"explanation":"L'évaluation initiale vise cinq objectifs : niveau de PA, risque CV global, organes cibles, facteurs aggravants, arguments pour une HTA secondaire, avant la consultation d'annonce."},"reveal":"Le bilan minimal est prescrit : glycémie à jeun, HbA1c, bilan lipidique, ionogramme, créatininémie avec DFG, rapport protéinurie/créatininurie, ECG de repos.","src":"p. 90-92"},{"id":"224-case-01-s05","phase":2,"narrative":"Résultats : LDL-C 1,7 g/L, glycémie à jeun normale, créatininémie normale avec DFG à 92 ml/min/1,73 m², kaliémie normale, protéinurie/créatininurie négative. L'ECG de repos est normal, sans signe d'hypertrophie ventriculaire gauche.","question":{"type":"QRU","stem":"Une échocardiographie doit-elle être demandée systématiquement chez ce patient ?","options":[{"t":"Oui, systématiquement chez tout hypertendu","ok":false,"why":"L'échocardiographie n'est pas systématique."},{"t":"Non, car il est asymptomatique et l'ECG est normal","ok":true,"why":"L'échocardiographie n'est indiquée qu'en cas d'ECG anormal ou de symptômes cardiaques."},{"t":"Oui, car le LDL-C est élevé","ok":false,"why":"L'élévation du LDL-C n'est pas une indication à l'échocardiographie."},{"t":"Non, mais un scanner cérébral est nécessaire","ok":false,"why":"Aucune indication de scanner cérébral chez ce patient asymptomatique."},{"t":"Oui, car il fume","ok":false,"why":"Le tabagisme n'est pas en soi une indication à l'échocardiographie."}],"explanation":"L'échographie cardiaque n'est indiquée qu'en cas d'ECG anormal ou de symptômes cardiaques, jamais de façon systématique chez l'asymptomatique à ECG normal."},"reveal":"Le risque cardiovasculaire est évalué par SCORE2 (tabac, âge, dyslipidémie, ATCD familial) : risque élevé. Une consultation d'annonce est programmée.","src":"p. 93-95"},{"id":"224-case-01-s06","phase":3,"narrative":"Lors de la consultation d'annonce, le médecin explique la maladie, ses complications potentielles et les bénéfices démontrés du traitement, puis fixe avec le patient les objectifs et le plan de soins.","question":{"type":"OPEN","prompt":"Quelles mesures hygiénodiététiques proposez-vous à ce patient, et quel bénéfice attendu sur la PA pouvez-vous lui annoncer ?","rubric":[{"point":"Arrêt du tabac","weight":1},{"point":"Réduction du sel à 5-6 g/j","weight":1},{"point":"Activité physique régulière et lutte contre la sédentarité","weight":1},{"point":"Objectif de tour de taille et d'IMC (< 94 cm, IMC 20-25)","weight":1},{"point":"Bénéfice attendu de 5 à 10 mmHg de baisse de la PAS","weight":1}],"model":"Il faut proposer l'arrêt du tabac, une réduction du sel à 5-6 g/j, une activité physique régulière (aérobie et résistance), un objectif de tour de taille inférieur à 94 cm et d'IMC entre 20 et 25 kg/m², ainsi qu'une alimentation de type méditerranéen. Ces mesures permettent une baisse attendue de la PAS de 5 à 10 mmHg et réduisent le nombre et les doses de médicaments nécessaires."},"reveal":"Compte tenu de l'HTA confirmée, un traitement médicamenteux est décidé d'emblée en complément des MHD, sans attendre.","src":"p. 94-96"},{"id":"224-case-01-s07","phase":3,"narrative":"Le médecin choisit d'instaurer un traitement médicamenteux chez ce patient de 54 ans, sans fragilité ni hypotension orthostatique.","question":{"type":"QRU","stem":"Quelle est la stratégie d'initiation recommandée en l'absence de critère de monothérapie ?","options":[{"t":"Bithérapie fixe à faible dose en monoprise, associant deux des classes IEC/ARA2, IC, thiazidique","ok":true,"why":"C'est la stratégie d'initiation recommandée chez l'hypertendu confirmé sans critère de monothérapie."},{"t":"Bêtabloquant seul","ok":false,"why":"Les bêtabloquants ne sont jamais utilisés en monothérapie dans l'HTA."},{"t":"Association IEC + ARA2","ok":false,"why":"Cette association est proscrite."},{"t":"Monothérapie par thiazidique uniquement","ok":false,"why":"La monothérapie n'est indiquée que dans des situations particulières, non présentes ici."},{"t":"Trithérapie d'emblée","ok":false,"why":"La trithérapie n'est proposée qu'en cas d'échec de la bithérapie, pas en 1re intention."}],"explanation":"Chez l'hypertendu confirmé sans critère de monothérapie, le traitement débute par une bithérapie fixe à faible dose en monoprise, jamais par une association IEC + ARA2."},"reveal":"Une association fixe IEC + inhibiteur calcique dihydropyridine est prescrite en monoprise, avec un contrôle du ionogramme et de la créatininémie prévu et une AMT à 1 mois.","src":"p. 96-98"},{"id":"224-case-01-s08","phase":4,"narrative":"Un mois plus tard, le patient rapporte une AMT moyenne à 134/86 mmHg. Le ionogramme est normal.","question":{"type":"QRU","stem":"La cible tensionnelle générale recommandée est-elle atteinte ?","options":[{"t":"Oui, la cible est atteinte","ok":false,"why":"La cible générale est plus basse que 134/86 mmHg."},{"t":"Non, la cible générale est 120-129/70-79 mmHg","ok":true,"why":"La cible générale de PAS est 120-129 mmHg et de PAD 70-79 mmHg, idéalement 120/70."},{"t":"Non, la cible est 160/100 mmHg","ok":false,"why":"Ce chiffre ne correspond à aucune cible recommandée."},{"t":"Oui, car la PA est inférieure à 140/90 mmHg","ok":false,"why":"Ce seuil correspond au repli en cas de cible inatteignable, pas à la cible générale."},{"t":"La cible n'est pertinente qu'en cas de diabète","ok":false,"why":"La cible générale s'applique à tout hypertendu, adaptée selon la tolérance."}],"explanation":"La cible générale (PAS 120-129, PAD 70-79 mmHg) n'est pas atteinte ; la conduite est de renforcer MHD et observance avant de passer en trithérapie."},"reveal":"Le médecin renforce l'observance et les MHD, et programme une réévaluation à 1 mois supplémentaire avant d'envisager une trithérapie si besoin.","src":"p. 95-100"},{"id":"224-case-01-s09","phase":5,"narrative":"À 3 mois, l'AMT est à 128/78 mmHg, bien tolérée, sans hypotension orthostatique. Le patient a arrêté le tabac.","question":{"type":"QROC","question":"À quel rythme ce patient à la cible, à risque cardiovasculaire élevé, doit-il être revu en consultation ?","answer":"Tous les 3 mois","accept":["3 mois","trimestriel"],"keywords":["3","mois"],"explanation":"Le rythme de suivi une fois la cible atteinte est de 3 mois en cas de risque cardiovasculaire élevé, contre 6 mois en cas de faible risque ou de grade 1."},"reveal":"Le suivi est organisé avec consultation trimestrielle, bilan biologique annuel, glycémie et lipides tous les 3 ans, ECG tous les 3 à 5 ans.","src":"p. 101"},{"id":"224-case-01-s10","phase":5,"narrative":"Un an plus tard, en période de canicule, le patient présente une diarrhée fébrile de 2 jours.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir concernant son traitement antihypertenseur pendant cet épisode ?","options":[{"t":"Suspendre transitoirement l'IEC en raison du risque d'hypovolémie","ok":true,"why":"Le risque de déshydratation impose une suspension transitoire des IEC/ARA2/diurétiques."},{"t":"Contrôler le ionogramme et la créatininémie","ok":true,"why":"Un contrôle biologique est recommandé lors de la reprise ou en cas de suspicion d'hypovolémie."},{"t":"Augmenter la dose de l'antihypertenseur pour compenser les pertes hydriques","ok":false,"why":"Augmenter la dose aggraverait le risque d'insuffisance rénale fonctionnelle."},{"t":"Poursuivre le traitement sans aucune adaptation","ok":false,"why":"La poursuite sans adaptation expose à une insuffisance rénale aiguë en contexte de déshydratation."},{"t":"Arrêter définitivement tout traitement antihypertenseur","ok":false,"why":"La suspension doit être transitoire, le temps de l'épisode aigu, pas définitive."}],"explanation":"L'éducation thérapeutique prévoit la suspension transitoire des diurétiques, IEC et ARA2 en cas de risque d'hypovolémie (diarrhée, vomissements, fièvre, canicule), avec contrôle biologique."},"reveal":"Le traitement est suspendu 48 heures, avec un contrôle biologique normal, puis repris à la disparition des symptômes digestifs.","src":"p. 100"}]},{"id":"224-case-02","title":"Mme Gauthier, 34 ans, HTA résistante avec hypokaliémie","rank":"A","summary":"Jeune femme suivie pour une HTA mal contrôlée sous trithérapie, chez qui une hypokaliémie oriente vers un hyperaldostéronisme primaire.","difficulty":3,"timeline":["Consultation pour HTA mal contrôlée","Bilan de résistance","Recherche étiologique","Diagnostic","Traitement","Suivi"],"steps":[{"id":"224-case-02-s01","phase":0,"narrative":"Mme Gauthier, 34 ans, sans antécédent notable, suivie depuis 8 mois pour une HTA, consulte car sa PA de consultation reste à 168/104 mmHg malgré son traitement. Elle prend un IEC, un inhibiteur calcique et un diurétique thiazidique, tous à dose optimale, et suit les mesures hygiénodiététiques.","question":{"type":"QRU","stem":"Quel diagnostic doit être évoqué devant ce tableau ?","options":[{"t":"Une HTA résistante","ok":true,"why":"PA au-dessus de la cible malgré MHD et 3 classes à dose optimale dont un thiazidique."},{"t":"Une HTA blouse blanche","ok":false,"why":"Le tableau ne décrit pas de discordance entre mesures de cabinet et hors cabinet, mais un échec thérapeutique sous trithérapie."},{"t":"Une urgence hypertensive","ok":false,"why":"Aucune atteinte aiguë d'organe cible n'est décrite ici."},{"t":"Une HTA masquée","ok":false,"why":"Ce terme décrit une PA de cabinet normale avec HTA en ambulatoire, non le cas ici."},{"t":"Une hypotension orthostatique","ok":false,"why":"Aucun élément clinique ne l'évoque dans cette observation."}],"explanation":"La patiente reçoit trois classes à dose optimale dont un thiazidique, avec MHD suivies, et reste au-dessus de la cible : le tableau évoque une HTA résistante à confirmer."},"reveal":"Avant de conclure, le médecin programme une confirmation par AMT et interroge la patiente sur l'observance.","src":"p. 101-102"},{"id":"224-case-02-s02","phase":1,"narrative":"L'AMT confirme une moyenne à 152/96 mmHg. La patiente affirme prendre correctement son traitement. Elle ne consomme pas d'AINS ni de réglisse, ne fume pas, boit occasionnellement de l'alcool.","question":{"type":"QRM","stem":"Quels éléments doivent être systématiquement recherchés avant de retenir une HTA résistante vraie ?","options":[{"t":"Un effet blouse blanche persistant malgré l'AMT","ok":false,"why":"L'AMT confirme déjà l'élévation ambulatoire ; ce n'est plus l'hypothèse principale une fois l'AMT réalisée."},{"t":"Une mauvaise observance médicamenteuse","ok":true,"why":"L'inobservance est une cause classique de fausse résistance à éliminer systématiquement."},{"t":"Un brassard inadapté à la taille du bras","ok":true,"why":"Une erreur de matériel peut fausser les mesures et doit être vérifiée."},{"t":"Une consommation excessive de sel non suivie","ok":true,"why":"Le non-respect des MHD (sel, poids, alcool) est une cause fréquente de fausse résistance."},{"t":"Un dosage systématique de la TSH sans autre point d'appel","ok":false,"why":"Aucun élément clinique ne pointe vers une dysthyroïdie ici, ce n'est pas systématique."}],"explanation":"Avant de parler d'HTA résistante vraie, il faut éliminer une fausse résistance : effet blouse blanche, brassard inadapté, doses insuffisantes ou absence de diurétique, inobservance, MHD non suivies."},"reveal":"L'interrogatoire approfondi et la vérification du matériel ne retrouvent aucune fausse résistance. Un bilan biologique de contrôle est prescrit.","src":"p. 101-102"},{"id":"224-case-02-s03","phase":1,"narrative":"Le ionogramme sanguin revient avec une kaliémie à 3,2 mmol/L, sans prise de garrot prolongée, non expliquée par une perte digestive ou une cause iatrogène évidente en dehors du thiazidique.","question":{"type":"QROC","question":"Quel diagnostic évoquer en priorité devant une HTA résistante avec hypokaliémie chez cette femme jeune ?","answer":"Hyperaldostéronisme primaire (syndrome de Conn)","accept":["hyperaldostéronisme primaire","syndrome de Conn","Conn"],"keywords":["hyperaldostéronisme","Conn"],"explanation":"L'association HTA résistante et hypokaliémie, même sous thiazidique, doit faire évoquer un hyperaldostéronisme primaire, cause classique d'HTA secondaire."},"reveal":"Le médecin décide un dosage de la rénine et de l'aldostérone plasmatiques après avoir organisé l'arrêt des traitements interférents.","src":"p. 102, 104"},{"id":"224-case-02-s04","phase":2,"narrative":"Pour interpréter correctement le dosage hormonal, l'équipe doit respecter des conditions de prélèvement strictes.","question":{"type":"QRM","stem":"Quelles conditions doivent être réunies avant le dosage de la rénine et de l'aldostérone plasmatiques ?","options":[{"t":"Arrêt des antagonistes des récepteurs minéralocorticoïdes depuis 6 semaines","ok":true,"why":"C'est le délai recommandé avant le dosage."},{"t":"Arrêt des IEC, ARA2, diurétiques et bêtabloquants depuis 2 semaines","ok":true,"why":"Ces classes modifient le système rénine-angiotensine-aldostérone et faussent l'interprétation."},{"t":"Prélèvement le matin, 2 heures après le lever","ok":true,"why":"C'est l'horaire recommandé pour ce dosage."},{"t":"Normokaliémie et apports sodés larges au moment du dosage","ok":true,"why":"Ces conditions sont nécessaires à l'interprétation correcte du dosage."},{"t":"Le dosage peut être réalisé sous n'importe quel traitement en cours","ok":false,"why":"Plusieurs classes antihypertensives rendent le dosage ininterprétable si elles ne sont pas arrêtées au préalable."}],"explanation":"Les dosages de rénine et d'aldostérone nécessitent des conditions de prélèvement strictes : arrêt des ARM depuis 6 semaines, des IEC/ARA2/diurétiques/bêtabloquants depuis 2 semaines, le matin 2 h après le lever, en normokaliémie et apports sodés larges."},"reveal":"Un relais transitoire par un antihypertenseur non interférent est mis en place le temps de la fenêtre thérapeutique, sous surveillance rapprochée.","src":"p. 104"},{"id":"224-case-02-s05","phase":3,"narrative":"Le dosage revient avec une aldostérone élevée, une rénine basse, et un rapport aldostérone/rénine très élevé. Un scanner surrénalien est demandé.","question":{"type":"QRU","stem":"Quelle est la répartition attendue des causes d'hyperaldostéronisme primaire ?","options":[{"t":"Hyperplasie bilatérale dans 70 % des cas, adénome dans 30 % des cas","ok":true,"why":"C'est la répartition rapportée pour l'hyperaldostéronisme primaire."},{"t":"Adénome dans 90 % des cas","ok":false,"why":"L'adénome ne représente qu'environ 30 % des cas."},{"t":"Corticosurrénalome malin dans la majorité des cas","ok":false,"why":"Le corticosurrénalome malin est une cause rare, non majoritaire."},{"t":"Hyperplasie bilatérale dans 30 % des cas seulement","ok":false,"why":"C'est l'inverse : l'hyperplasie bilatérale est la cause la plus fréquente (70 %)."},{"t":"La répartition est inconnue","ok":false,"why":"La répartition entre hyperplasie bilatérale et adénome est bien précisée."}],"explanation":"L'hyperaldostéronisme primaire est dû à une hyperplasie bilatérale dans 70 % des cas et à un adénome surrénalien (syndrome de Conn) dans 30 % des cas."},"reveal":"Le scanner surrénalien met en évidence un nodule surrénalien unilatéral de 12 mm.","src":"p. 104"},{"id":"224-case-02-s06","phase":3,"narrative":"Devant ce nodule unilatéral et une patiente demandeuse d'un geste curatif, une exploration complémentaire est discutée.","question":{"type":"QROC","question":"Quel examen permet de confirmer la latéralisation de la sécrétion avant d'envisager une chirurgie ?","answer":"Cathétérisme des veines surrénaliennes","accept":["cathétérisme veineux surrénalien","prélèvement veineux surrénalien étagé"],"keywords":["cathétérisme","veines surrénaliennes"],"explanation":"En cas de lésion unilatérale chez un patient demandeur d'un geste curatif, le cathétérisme des veines surrénaliennes confirme la latéralisation avant surrénalectomie."},"reveal":"Le cathétérisme confirme une hypersécrétion unilatérale du côté du nodule.","src":"p. 104"},{"id":"224-case-02-s07","phase":4,"narrative":"La patiente est adressée en chirurgie pour une surrénalectomie unilatérale.","question":{"type":"QRU","stem":"En l'absence de possibilité chirurgicale ou de latéralisation confirmée, quel traitement médical est proposé en 1re intention ?","options":[{"t":"Spironolactone","ok":true,"why":"L'ARM spironolactone est le traitement médical de 1re intention de l'hyperaldostéronisme primaire."},{"t":"Bêtabloquant seul","ok":false,"why":"Le bêtabloquant n'est pas le traitement de 1re intention de l'hyperaldostéronisme."},{"t":"Thiazidique seul","ok":false,"why":"Le thiazidique majore l'hypokaliémie et n'est pas adapté ici."},{"t":"Alphabloquant seul","ok":false,"why":"L'alphabloquant n'est pas le traitement de 1re intention de cette pathologie."},{"t":"Aucun traitement médicamenteux n'est nécessaire","ok":false,"why":"Un traitement médicamenteux ciblé est nécessaire si la chirurgie n'est pas réalisée."}],"explanation":"Sans chirurgie, la spironolactone est le traitement médical de 1re intention (éplérénone en cas d'intolérance)."},"reveal":"La patiente bénéficie finalement de la surrénalectomie, avec normalisation progressive de la PA et de la kaliémie en post-opératoire.","src":"p. 104"},{"id":"224-case-02-s08","phase":5,"narrative":"Trois mois après la chirurgie, la PA de la patiente est à 122/76 mmHg en AMT, sans traitement antihypertenseur, la kaliémie s'est normalisée.","question":{"type":"OPEN","prompt":"Expliquez pourquoi la recherche d'une cause secondaire était justifiée chez cette patiente, et quels éléments cliniques initiaux l'orientaient.","rubric":[{"point":"Âge jeune (< 40 ans)","weight":1},{"point":"HTA résistante malgré trithérapie optimale dont thiazidique","weight":1},{"point":"Hypokaliémie associée","weight":1},{"point":"Ces critères imposent un dépistage d'HTA secondaire et un avis spécialisé","weight":1}],"model":"Chez cette patiente de 34 ans, plusieurs critères imposaient de rechercher une HTA secondaire : l'âge inférieur à 40 ans, la résistance de l'HTA malgré une trithérapie optimale comportant un thiazidique, et la découverte d'une hypokaliémie. Ces éléments justifiaient un avis spécialisé et un bilan orienté (rénine, aldostérone), qui ont permis d'identifier et de traiter la cause curable."},"reveal":"La patiente reste surveillée annuellement, sans traitement antihypertenseur nécessaire à un an de la chirurgie.","src":"p. 102-104"}]},{"id":"224-case-03","title":"M. Belkacem, 61 ans, céphalées brutales et PA à 226/128 mmHg aux urgences","rank":"A","summary":"Patient hypertendu connu mais peu suivi, amené aux urgences pour des céphalées intenses avec une PA très élevée, imposant d'éliminer une urgence hypertensive avant tout traitement.","difficulty":3,"timeline":["Admission aux urgences","Bilan en urgence","Diagnostic de gravité","Traitement initial","Évolution","Relais et suivi"],"steps":[{"id":"224-case-03-s01","phase":0,"narrative":"M. Belkacem, 61 ans, hypertendu connu depuis 5 ans mais mal suivi et peu observant, est amené aux urgences pour des céphalées intenses apparues brutalement il y a 2 heures, associées à des troubles visuels. La PA mesurée est à 226/128 mmHg. Il n'a pas de déficit moteur ni sensitif visible.","question":{"type":"QRU","stem":"Quelle est la première étape de la démarche diagnostique devant ce tableau ?","options":[{"t":"Débuter immédiatement un antihypertenseur IV avant tout examen","ok":false,"why":"Devant un tableau neurologique, aucun antihypertenseur n'est débuté avant le scanner cérébral."},{"t":"Rechercher une atteinte aiguë d'un organe cible pour distinguer crise et urgence hypertensive","ok":true,"why":"C'est l'étape clé : une HTA sévère sans souffrance viscérale est une crise hypertensive, non une urgence."},{"t":"Renvoyer le patient à domicile avec une simple consultation de contrôle à 1 semaine","ok":false,"why":"Un tableau neurologique avec PA très élevée impose une évaluation en urgence, pas un simple différé."},{"t":"Réaliser d'emblée une automesure tensionnelle à domicile","ok":false,"why":"L'AMT n'a pas sa place dans l'évaluation immédiate d'un tableau potentiellement grave aux urgences."},{"t":"Attendre la confirmation par MAPA avant tout geste","ok":false,"why":"La MAPA n'est pas adaptée à l'urgence ; il faut d'abord rechercher une atteinte aiguë d'organe cible."}],"explanation":"La première question est de savoir s'il existe une atteinte aiguë d'un organe cible : c'est ce qui distingue la crise hypertensive (pas d'urgence) de l'urgence hypertensive, à pronostic vital engagé."},"reveal":"Devant les troubles visuels et les céphalées brutales, un bilan en urgence est engagé, avec un scanner cérébral programmé en priorité.","src":"p. 105-106"},{"id":"224-case-03-s02","phase":1,"narrative":"Le bilan biologique en urgence est prélevé : créatininémie, protéinurie, plaquettes, coagulation, troponine, NFS. Un ECG et une radiographie thoracique sont réalisés.","question":{"type":"QRM","stem":"Quels examens complémentaires sont pertinents dans ce contexte d'urgence hypertensive suspectée ?","options":[{"t":"Fond d'œil à la recherche d'un œdème papillaire","ok":true,"why":"Le fond d'œil recherche un stade 4 (œdème papillaire), signant l'HTA maligne."},{"t":"Recherche de schizocytes, bilirubine libre et haptoglobine","ok":true,"why":"Ces éléments recherchent une microangiopathie thrombotique associée à l'HTA maligne."},{"t":"Scanner cérébral devant les troubles visuels et les céphalées brutales","ok":true,"why":"Un signe neurologique impose un scanner cérébral avant tout traitement antihypertenseur."},{"t":"Coloscopie systématique","ok":false,"why":"Aucune indication de coloscopie dans ce contexte."},{"t":"Épreuve d'effort cardiaque immédiate","ok":false,"why":"Une épreuve d'effort est contre-indiquée et inutile dans ce contexte aigu."}],"explanation":"Le bilan d'une urgence hypertensive comprend selon le contexte : fond d'œil, recherche de microangiopathie thrombotique (schizocytes, bilirubine libre, haptoglobine), et un scanner cérébral avant traitement en cas de signe neurologique."},"reveal":"Le scanner cérébral ne montre pas d'hémorragie ni d'ischémie constituée. Le fond d'œil objective un œdème papillaire bilatéral.","src":"p. 105-107"},{"id":"224-case-03-s03","phase":2,"narrative":"La biologie révèle une créatininémie élevée avec DFG abaissé, une protéinurie abondante, une anémie avec schizocytes, une haptoglobine effondrée et une thrombopénie modérée.","question":{"type":"QRU","stem":"Quel diagnostic ce tableau (œdème papillaire + IRA + microangiopathie thrombotique) évoque-t-il ?","options":[{"t":"Une HTA maligne","ok":true,"why":"L'association œdème papillaire (stade 4) et atteintes aiguës (rénale, microangiopathie) définit l'HTA maligne."},{"t":"Une crise hypertensive simple","ok":false,"why":"La crise hypertensive est par définition sans souffrance viscérale, ce qui n'est pas le cas ici."},{"t":"Une HTA blouse blanche","ok":false,"why":"Ce diagnostic ne s'applique pas dans un contexte d'urgence avec atteinte d'organe documentée."},{"t":"Un syndrome néphrotique isolé","ok":false,"why":"Le tableau associe bien plus qu'une protéinurie isolée : œdème papillaire et microangiopathie thrombotique orientent vers l'HTA maligne."},{"t":"Une insuffisance rénale chronique stable","ok":false,"why":"Le tableau est celui d'une insuffisance rénale aiguë dans un contexte d'urgence hypertensive, non d'une maladie chronique stable."}],"explanation":"L'HTA maligne associe une PA élevée à un œdème papillaire (stade 4) avec, comme ici, une atteinte rénale aiguë et une microangiopathie thrombotique (anémie hémolytique mécanique, thrombopénie)."},"reveal":"Le patient est transféré en soins intensifs pour prise en charge d'une HTA maligne avec insuffisance rénale aiguë.","src":"p. 106-107"},{"id":"224-case-03-s04","phase":3,"narrative":"En soins intensifs, l'équipe débute le traitement antihypertenseur, avec surveillance rapprochée de la PA.","question":{"type":"QRM","stem":"Quels sont les principes de la baisse tensionnelle initiale dans ce contexte (hors dissection aortique) ?","options":[{"t":"Baisse de 20 à 25 % de la PA en 2 heures","ok":true,"why":"C'est l'objectif initial recommandé dans le cas général d'urgence hypertensive."},{"t":"Cible de 160/110 mmHg en 2 à 6 heures","ok":true,"why":"C'est la cible intermédiaire recommandée avant une normalisation plus progressive."},{"t":"Surveillance de la PA toutes les 15 minutes","ok":true,"why":"Une surveillance rapprochée est nécessaire pour éviter une chute trop rapide."},{"t":"Normalisation complète de la PA en moins d'une heure","ok":false,"why":"Une chute brutale est dangereuse : elle expose à une hypoperfusion cérébrale, myocardique ou rénale."},{"t":"Aucune surveillance particulière n'est nécessaire une fois le traitement débuté","ok":false,"why":"Une surveillance rapprochée de la PA est indispensable en urgence hypertensive."}],"explanation":"Dans le cas général, la baisse tensionnelle doit être progressive : 20 à 25 % en 2 h, puis 160/110 mmHg en 2 à 6 h, avec surveillance de la PA toutes les 15 minutes, sans chute brutale."},"reveal":"Un traitement par urapidil IV est débuté, avec une décroissance progressive de la PA sous surveillance continue.","src":"p. 106"},{"id":"224-case-03-s05","phase":3,"narrative":"Le patient s'améliore progressivement sur les 6 premières heures, avec disparition des céphalées.","question":{"type":"QROC","question":"Quelle molécule alternative à l'urapidil, contre-indiquée en cas d'insuffisance cardiaque, aurait pu être utilisée en 1re intention ?","answer":"Nicardipine","accept":["nicardipine IV"],"keywords":["nicardipine"],"explanation":"La nicardipine IV est, avec l'urapidil, l'antihypertenseur de 1re intention dans le cas général, mais elle est contre-indiquée en cas d'insuffisance cardiaque."},"reveal":"L'échocardiographie ne montre pas de dysfonction ventriculaire gauche significative, confirmant que la nicardipine aurait pu être une option.","src":"p. 106"},{"id":"224-case-03-s06","phase":4,"narrative":"À J2, la PA est stabilisée à 168/104 mmHg, la fonction rénale se stabilise, la NFS montre une amélioration progressive de l'anémie et de la thrombopénie.","question":{"type":"QRU","stem":"Quel est le risque évolutif en l'absence de contrôle durable de la PA après un épisode d'HTA maligne ?","options":[{"t":"Insuffisance rénale sévère irréversible, pouvant être mortelle en quelques mois","ok":true,"why":"C'est l'évolution naturelle décrite en l'absence de traitement de l'HTA maligne."},{"t":"Guérison spontanée systématique sans séquelle","ok":false,"why":"L'HTA maligne non traitée évolue vers une insuffisance rénale sévère, pas vers une guérison spontanée."},{"t":"Aucun risque particulier si la PA redescend transitoirement","ok":false,"why":"Le risque persiste tant que le contrôle tensionnel n'est pas durable."},{"t":"Risque uniquement digestif","ok":false,"why":"Le risque principal décrit est rénal, pas digestif."},{"t":"Disparition définitive du besoin de traitement antihypertenseur","ok":false,"why":"Un traitement antihypertenseur au long cours reste nécessaire après un épisode d'HTA maligne."}],"explanation":"Sans traitement, l'HTA maligne évolue vers une insuffisance rénale sévère irréversible, pouvant être mortelle en quelques mois."},"reveal":"Le patient est mis sous trithérapie orale progressive (IEC/ARA2 + inhibiteur calcique + thiazidique) en relais du traitement IV, avec surveillance rapprochée.","src":"p. 106"},{"id":"224-case-03-s07","phase":5,"narrative":"Avant la sortie, l'équipe organise le relais ambulatoire et l'éducation du patient, qui reconnaît avoir arrêté son traitement plusieurs mois auparavant faute de symptômes.","question":{"type":"OPEN","prompt":"Quels messages d'éducation thérapeutique délivrez-vous à ce patient pour prévenir une récidive d'HTA maligne ?","rubric":[{"point":"Importance de l'observance médicamenteuse même en l'absence de symptômes","weight":1},{"point":"Surveillance par AMT régulière (règle des 3, 1 mois après adaptation)","weight":1},{"point":"Reconnaître les signes d'alerte (céphalées, troubles visuels) imposant une consultation en urgence","weight":1},{"point":"Nécessité d'un suivi rapproché initial puis régulier au long cours","weight":1}],"model":"Il faut expliquer que l'HTA est le plus souvent asymptomatique et que l'absence de symptôme ne signifie pas l'absence de danger, d'où l'importance de l'observance même sans plainte. Le patient doit surveiller sa PA par AMT régulière, notamment après toute adaptation thérapeutique, et consulter en urgence en cas de céphalées brutales ou de troubles visuels. Un suivi rapproché est nécessaire dans les suites immédiates, puis régulier au long cours pour prévenir toute récidive."},"reveal":"Le patient est revu à 1 mois avec une AMT correcte à 138/88 mmHg, en cours de descente vers la cible, sous trithérapie bien tolérée et observante.","src":"p. 100, 107"},{"id":"224-case-03-s08","phase":5,"narrative":"Six mois plus tard, le patient est stable, sa fonction rénale s'est partiellement récupérée, la PA en AMT est à 130/80 mmHg sous trithérapie bien tolérée.","question":{"type":"QRU","stem":"Quel bilan paraclinique de suivi est recommandé chez ce patient désormais à la cible ?","options":[{"t":"Ionogramme, créatininémie et protéinurie une fois par an, ECG tous les 3 à 5 ans","ok":true,"why":"C'est le rythme de surveillance paraclinique recommandé chez le patient contrôlé, à adapter ici du fait de l'antécédent rénal."},{"t":"Aucun bilan biologique n'est plus nécessaire","ok":false,"why":"Un suivi biologique régulier reste indispensable, en particulier après un épisode d'atteinte rénale aiguë."},{"t":"IRM cérébrale systématique tous les ans","ok":false,"why":"Aucune indication d'IRM cérébrale systématique en dehors d'un contexte clinique évocateur."},{"t":"Dosage systématique de la rénine et de l'aldostérone tous les 3 mois","ok":false,"why":"Ce dosage n'est pas indiqué en l'absence de nouveau point d'appel pour une HTA secondaire."},{"t":"Scanner cérébral systématique tous les 6 mois","ok":false,"why":"Aucune indication de scanner cérébral de surveillance systématique en l'absence de symptôme."}],"explanation":"Chez le patient contrôlé, la surveillance paraclinique comprend un bilan ionique et rénal annuel et un ECG tous les 3 à 5 ans, avec une vigilance accrue ici compte tenu de l'antécédent d'insuffisance rénale aiguë."},"reveal":"Le patient reste suivi conjointement par son médecin traitant et le néphrologue, avec une fonction rénale stable et une PA contrôlée à un an.","src":"p. 101, 107"}]}],"ecg":{"data":[],"method":""},"echo":{"data":[]}});
